# Python port of Rust's std BinaryHeap (max-heap) with custom 'le' and 'ge' and 'lt'
class RHeap:
    def __init__(self, cmp, data=None):
        # cmp(a,b) -> -1,0,1  (Ordering of a relative to b)
        self.cmp = cmp
        self.data = list(data) if data else []
        if data:
            self.rebuild()
    def le(self, a, b): return self.cmp(a, b) <= 0
    def ge(self, a, b): return self.cmp(a, b) >= 0
    def lt(self, a, b): return self.cmp(a, b) < 0
    def sift_up(self, start, pos):
        d = self.data
        elem = d[pos]
        while pos > start:
            parent = (pos - 1) // 2
            if self.le(elem, d[parent]):
                break
            d[pos] = d[parent]
            pos = parent
        d[pos] = elem
        return pos
    def sift_down_range(self, pos, end):
        d = self.data
        elem = d[pos]
        child = 2 * pos + 1
        while child <= end - 2 if end >= 2 else False:
            if self.le(d[child], d[child + 1]):
                child += 1
            if self.ge(elem, d[child]):
                d[pos] = elem
                return
            d[pos] = d[child]
            pos = child
            child = 2 * pos + 1
        if child == end - 1 and self.lt(elem, d[child]):
            d[pos] = d[child]
            pos = child
        d[pos] = elem
    def sift_down_to_bottom(self, pos):
        d = self.data
        end = len(d)
        start = pos
        elem = d[pos]
        child = 2 * pos + 1
        while child <= (end - 2 if end >= 2 else -1):
            if self.le(d[child], d[child + 1]):
                child += 1
            d[pos] = d[child]
            pos = child
            child = 2 * pos + 1
        if child == end - 1:
            d[pos] = d[child]
            pos = child
        d[pos] = elem
        self.sift_up(start, pos)
    def rebuild(self):
        n = len(self.data) // 2
        while n > 0:
            n -= 1
            self.sift_down_range(n, len(self.data))
    def push(self, x):
        self.data.append(x)
        self.sift_up(0, len(self.data) - 1)
    def pop(self):
        if not self.data: return None
        item = self.data.pop()
        if self.data:
            item, self.data[0] = self.data[0], item
            self.sift_down_to_bottom(0)
        return item
    def __len__(self): return len(self.data)

if __name__ == '__main__':
    def mk(tie):
        def c(a, b):
            if a[1] != b[1]:
                return -1 if a[1] > b[1] else 1  # lower score = greater
            return tie
        return c
    for tie in (0, -1, 1):
        for n in (4, 10, 14):
            h = RHeap(mk(tie))
            for i in range(n): h.push((i, 5))
            print('push', tie, n, [h.pop()[0] for _ in range(n)])
            h = RHeap(mk(tie), [(i, 5) for i in range(n)])
            print('from', tie, n, [h.pop()[0] for _ in range(n)])
