import sys, os, itertools, re
sys.path.insert(0, '/tmp/sim')
from rheap import RHeap

def scan(path):
    """return nested structure: (name, is_dir, children list)"""
    def rec(p, name):
        if os.path.isdir(p) and not os.path.islink(p):
            ch = []
            for n in sorted(os.listdir(p), key=lambda s: s.lower()):
                if n.startswith('.'): continue
                ch.append(rec(os.path.join(p, n), n))
            return [name, True, ch]
        return [name, False, None]
    return rec(path, path)

class BL:
    __slots__ = ('id','name','depth','is_dir','children','parent','next_child_idx','has_match','nb_kept','score','struct','gathered_any','pruned_dropped','loaded')

def simulate(struct, area, params, trim_root=False):
    bl = []
    def new(s, depth, parent):
        b = BL(); b.id = len(bl); b.name = s[0]; b.depth = depth; b.is_dir = s[1]; b.children = None
        b.parent = parent; b.next_child_idx = 0; b.has_match = True; b.nb_kept = 0
        b.score = 10000 - depth; b.struct = s; b.gathered_any = False; b.pruned_dropped = False; b.loaded=False
        bl.append(b); return b.id
    def load(i):
        b = bl[i]
        if b.loaded: return
        b.loaded = True
        b.children = [new(c, b.depth + 1, i) for c in b.struct[2]]
    T = area
    root = new(struct, 0, None)
    load(root)
    out = [root]; nb = 1
    from collections import deque
    open_dirs = deque([root]); next_level = []
    while True:
        if nb > T and not (not trim_root and bl[open_dirs[0]].depth == 0 if open_dirs else False):
            break
        if open_dirs:
            d = open_dirs.popleft()
            b = bl[d]
            if b.next_child_idx < len(b.children):
                c = b.children[b.next_child_idx]; b.next_child_idx += 1
                b.gathered_any = True
                open_dirs.append(d)
                nb += 1
                if bl[c].is_dir: next_level.append(c)
                out.append(c)
        else:
            if not next_level: break
            for d in next_level:
                load(d); open_dirs.append(d)
            next_level = []
    # trim
    mode = params
    def prune_count():
        n = 0
        for i in out:
            b = bl[i]
            if b.has_match and b.is_dir and b.loaded and b.next_child_idx < len(b.children) and not b.pruned_dropped:
                if mode['prune_rule'] == 'any' or b.gathered_any:
                    n += 1
        return n
    for i in out[1:]:
        if bl[i].has_match:
            bl[bl[i].parent].nb_kept += 1
    count = sum(1 for i in out if bl[i].has_match)
    tie = mode['tie']
    def cmpf(a, b):
        if a[1] != b[1]: return -1 if a[1] > b[1] else 1
        return tie
    cands = [(i, bl[i].score) for i in out[1:] if bl[i].has_match and bl[i].nb_kept == 0 and (bl[i].depth > 1 or trim_root)]
    if mode['build'] == 'from':
        heap = RHeap(cmpf, cands)
    else:
        heap = RHeap(cmpf)
        for c in cands: heap.push(c)
    def total():
        return count + (prune_count() if mode['count_prunes'] else 0)
    while total() > T:
        x = heap.pop()
        if x is None: break
        i = x[0]; b = bl[i]
        removable = b.depth > 1 or (trim_root and b.depth > 0)
        if not removable:
            b.pruned_dropped = True
            continue
        b.has_match = False
        p = bl[b.parent]
        p.nb_kept -= 1
        p.next_child_idx -= 1
        count -= 1
