//! Colors and styles

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Color {
    Ansi(u8),
    Rgb(u8, u8, u8),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Hash)]
pub struct Attrs {
    pub bold: bool,
    pub italic: bool,
    pub underlined: bool,
    pub reverse: bool,
    pub crossed: bool,
    pub dim: bool,
    pub overlined: bool,
    pub slow_blink: bool,
}

impl Attrs {
    pub fn is_empty(&self) -> bool {
        *self == Attrs::default()
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Hash)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub attrs: Attrs,
}

impl Style {
    pub const fn new() -> Self {
        Style {
            fg: None,
            bg: None,
            attrs: Attrs {
                bold: false,
                italic: false,
                underlined: false,
                reverse: false,
                crossed: false,
                dim: false,
                overlined: false,
                slow_blink: false,
            },
        }
    }
    pub fn fg(c: Color) -> Self {
        Style { fg: Some(c), ..Style::new() }
    }
    pub fn with_bg(mut self, c: Option<Color>) -> Self {
        self.bg = c;
        self
    }
    pub fn with_fg(mut self, c: Option<Color>) -> Self {
        self.fg = c;
        self
    }
    pub fn bold(mut self) -> Self {
        self.attrs.bold = true;
        self
    }
    pub fn italic(mut self) -> Self {
        self.attrs.italic = true;
        self
    }
    pub fn reverse(mut self) -> Self {
        self.attrs.reverse = true;
        self
    }
    /// overlay: the other's fg/bg replace ours when defined, attributes are added
    pub fn overlaid(mut self, other: &Style) -> Self {
        if other.fg.is_some() {
            self.fg = other.fg;
        }
        if other.bg.is_some() {
            self.bg = other.bg;
        }
        let a = &other.attrs;
        self.attrs.bold |= a.bold;
        self.attrs.italic |= a.italic;
        self.attrs.underlined |= a.underlined;
        self.attrs.reverse |= a.reverse;
        self.attrs.crossed |= a.crossed;
        self.attrs.dim |= a.dim;
        self.attrs.overlined |= a.overlined;
        self.attrs.slow_blink |= a.slow_blink;
        self
    }
    pub fn no_color() -> Self {
        Style::new()
    }
}

pub fn gray(level: u8) -> Color {
    Color::Ansi(232 + level.min(23))
}
pub fn ansi(v: u8) -> Color {
    Color::Ansi(v)
}

fn parse_u8(s: &str) -> Option<u8> {
    s.trim().parse::<u8>().ok()
}

/// parse a color token. Returns Ok(None) for "none"
pub fn parse_color(s: &str) -> Result<Option<Color>, String> {
    let t = s.trim();
    let l = t.to_lowercase();
    if l == "none" || l == "default" {
        return Ok(None);
    }
    if let Some(rest) = l.strip_prefix("gray(").or_else(|| l.strip_prefix("grey(")) {
        if let Some(v) = rest.strip_suffix(')') {
            if let Some(n) = parse_u8(v) {
                if n < 24 {
                    return Ok(Some(gray(n)));
                }
            }
        }
        return Err(format!("{} not recognized as a color", t));
    }
    if let Some(rest) = l.strip_prefix("ansi(") {
        if let Some(v) = rest.strip_suffix(')') {
            if let Some(n) = parse_u8(v) {
                return Ok(Some(Color::Ansi(n)));
            }
        }
        return Err(format!("{} not recognized as a color", t));
    }
    if let Some(rest) = l.strip_prefix("rgb(") {
        if let Some(v) = rest.strip_suffix(')') {
            let parts: Vec<&str> = v.split(',').collect();
            if parts.len() == 3 {
                if let (Some(r), Some(g), Some(b)) =
                    (parse_u8(parts[0]), parse_u8(parts[1]), parse_u8(parts[2]))
                {
                    return Ok(Some(Color::Rgb(r, g, b)));
                }
            }
        }
        return Err(format!("{} not recognized as a color", t));
    }
    if let Some(hex) = l.strip_prefix('#') {
        if hex.len() == 6 {
            if let Ok(v) = u32::from_str_radix(hex, 16) {
                return Ok(Some(Color::Rgb((v >> 16) as u8, (v >> 8) as u8, v as u8)));
            }
        }
    }
    let v = match l.as_str() {
        "black" => 16,
        "red" => 9,
        "darkred" => 1,
        "green" => 10,
        "darkgreen" => 2,
        "yellow" => 11,
        "darkyellow" => 11,
        "blue" => 12,
        "darkblue" => 12,
        "magenta" => 13,
        "darkmagenta" => 5,
        "cyan" => 14,
        "darkcyan" => 14,
        "white" => 231,
        "grey" => 7,
        "darkgrey" => 7,
        _ => {
            // some lax matching
            let names = [
                ("black", 16),
                ("red", 9),
                ("green", 10),
                ("yellow", 11),
                ("blue", 12),
                ("magenta", 13),
                ("cyan", 14),
                ("white", 231),
                ("grey", 7),
            ];
            for (n, v) in names {
                if l.ends_with(n) && l.starts_with("dark") {
                    return Ok(Some(Color::Ansi(v)));
                }
            }
            return Err(format!("{} not recognized as a color", t));
        }
    };
    Ok(Some(Color::Ansi(v)))
}

/// Parse a style definition like "gray(22) none bold"
pub fn parse_style(s: &str) -> Result<Style, String> {
    let mut style = Style::new();
    // tokens: split on whitespace but keep parentheses groups together
    let mut tokens: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut depth = 0;
    for c in s.chars() {
        match c {
            '(' => {
                depth += 1;
                cur.push(c);
            }
            ')' => {
                depth -= 1;
                cur.push(c);
            }
            c if c.is_whitespace() && depth == 0 => {
                if !cur.is_empty() {
                    tokens.push(std::mem::take(&mut cur));
                }
            }
            c => cur.push(c),
        }
    }
    if !cur.is_empty() {
        tokens.push(cur);
    }
    let mut color_idx = 0;
    for tok in tokens {
        let l = tok.to_lowercase();
        match l.as_str() {
            "bold" => style.attrs.bold = true,
            "italic" => style.attrs.italic = true,
            "underlined" | "underline" => style.attrs.underlined = true,
            "reverse" | "reversed" => style.attrs.reverse = true,
            "crossedout" | "crossed_out" => style.attrs.crossed = true,
            "dim" => style.attrs.dim = true,
            "overlined" => style.attrs.overlined = true,
            "slowblink" => style.attrs.slow_blink = true,
            _ => {
                let c = parse_color(&tok)?;
                if color_idx == 0 {
                    style.fg = c;
                } else if color_idx == 1 {
                    style.bg = c;
                } else {
                    return Err(format!("too many colors in {:?}", s));
                }
                color_idx += 1;
            }
        }
    }
    Ok(style)
}

/// parse a skin entry "focused / unfocused"
pub fn parse_skin_entry(s: &str) -> Result<(Style, Option<Style>), String> {
