    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
}

impl Value {
    pub fn get(&self, key: &str) -> Option<&Value> {
        match self {
            Value::Object(v) => v.iter().rev().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Value::String(s) => Some(s),
            _ => None,
        }
    }
    pub fn as_string_lossy(&self) -> Option<String> {
        match self {
            Value::String(s) => Some(s.clone()),
            Value::Number(n) => Some(fmt_num(*n)),
            Value::Bool(b) => Some(b.to_string()),
            _ => None,
        }
    }
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Value::Bool(b) => Some(*b),
            Value::String(s) => match s.as_str() {
                "true" => Some(true),
                "false" => Some(false),
                _ => None,
            },
            _ => None,
        }
    }
    pub fn as_f64(&self) -> Option<f64> {
        match self {
            Value::Number(n) => Some(*n),
            Value::String(s) => s.trim().parse().ok(),
            _ => None,
        }
    }
    pub fn as_array(&self) -> Option<&Vec<Value>> {
        match self {
            Value::Array(a) => Some(a),
            _ => None,
        }
    }
    pub fn as_object(&self) -> Option<&Vec<(String, Value)>> {
        match self {
            Value::Object(o) => Some(o),
            _ => None,
        }
    }
}

pub fn fmt_num(n: f64) -> String {
    if n.fract() == 0.0 && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

struct Parser<'a> {
    chars: Vec<char>,
    pos: usize,
    _src: &'a str,
}

type Res<T> = Result<T, String>;

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }
    fn peek_at(&self, off: usize) -> Option<char> {
        self.chars.get(self.pos + off).copied()
    }
    fn err<T>(&self, msg: &str) -> Res<T> {
        let line = self.chars[..self.pos.min(self.chars.len())].iter().filter(|&&c| c == '\n').count() + 1;
        Err(format!("{} at line {}", msg, line))
    }
    /// skip whitespace and comments
    fn skip_ws(&mut self) {
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => self.pos += 1,
                Some('#') => self.skip_line(),
                Some('/') if self.peek_at(1) == Some('/') => self.skip_line(),
                Some('/') if self.peek_at(1) == Some('*') => {
                    self.pos += 2;
                    while let Some(c) = self.peek() {
                        if c == '*' && self.peek_at(1) == Some('/') {
                            self.pos += 2;
                            break;
                        }
                        self.pos += 1;
                    }
                }
                _ => break,
            }
        }
    }
    /// skip whitespace (not newlines) and comments on the current line
    fn skip_inline_ws(&mut self) {
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() && c != '\n' => self.pos += 1,
                Some('#') => {
                    while let Some(c) = self.peek() {
                        if c == '\n' {
                            break;
                        }
                        self.pos += 1;
                    }
                }
                Some('/') if self.peek_at(1) == Some('/') => {
                    while let Some(c) = self.peek() {
                        if c == '\n' {
                            break;
                        }
                        self.pos += 1;
                    }
                }
                _ => break,
            }
        }
    }
    fn skip_line(&mut self) {
        while let Some(c) = self.peek() {
            self.pos += 1;
            if c == '\n' {
                break;
            }
        }
    }
    fn parse_root(&mut self) -> Res<Value> {
        self.skip_ws();
        match self.peek() {
            None => Ok(Value::Object(vec![])),
            Some('{') => {
                let v = self.parse_object(true)?;
                self.skip_ws();
                Ok(v)
            }
            Some('[') => self.parse_array(),
            _ => self.parse_object_members(false),
        }
    }
    fn parse_object(&mut self, braced: bool) -> Res<Value> {
        if braced {
            self.pos += 1; // {
        }
        self.parse_object_members(braced)
    }
    fn parse_object_members(&mut self, braced: bool) -> Res<Value> {
        let mut members = Vec::new();
        loop {
            self.skip_ws();
            match self.peek() {
                None => {
                    if braced {
                        return self.err("unexpected end of input in object");
                    }
                    break;
                }
                Some('}') => {
                    if braced {
                        self.pos += 1;
                        break;
                    }
                    return self.err("unexpected }");
                }
                Some(',') => {
                    self.pos += 1;
                    continue;
                }
                _ => {}
            }
            let key = self.parse_key()?;
            self.skip_ws();
            if self.peek() != Some(':') {
                return self.err(&format!("expected ':' after key {:?}", key));
            }
            self.pos += 1;
            self.skip_inline_ws();
            if self.peek() == Some('\n') {
                self.skip_ws();
            }
            let value = self.parse_value(if braced { Ctx::Object } else { Ctx::Root })?;
            members.push((key, value));
        }
        Ok(Value::Object(members))
    }
    fn parse_key(&mut self) -> Res<String> {
        match self.peek() {
            Some('"') | Some('\'') => self.parse_quoted(),
            _ => {
                let mut s = String::new();
                while let Some(c) = self.peek() {
                    if c == ':' || c.is_whitespace() {
                        break;
                    }
                    if c == '{' || c == '}' || c == '[' || c == ']' || c == ',' {
                        return self.err(&format!("UnexpectedChar {:?} in key", c));
                    }
                    s.push(c);
                    self.pos += 1;
                }
                if s.is_empty() {
                    return self.err("empty key");
                }
                Ok(s)
            }
        }
    }
    fn parse_quoted(&mut self) -> Res<String> {
        let q = self.peek().unwrap();
        // multiline '''
        if q == '\'' && self.peek_at(1) == Some('\'') && self.peek_at(2) == Some('\'') {
            return self.parse_multiline();
        }
        self.pos += 1;
        let mut s = String::new();
        loop {
            match self.peek() {
                None => return self.err("unterminated string"),
                Some(c) if c == q => {
                    self.pos += 1;
                    break;
                }
                Some('\\') => {
                    self.pos += 1;
                    match self.peek() {
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\u{8}'),
                        Some('f') => s.push('\u{c}'),
                        Some('/') => s.push('/'),
                        Some('\\') => s.push('\\'),
                        Some('"') => s.push('"'),
                        Some('\'') => s.push('\''),
                        Some('u') => {
                            let hex: String = (1..=4).filter_map(|i| self.peek_at(i)).collect();
                            if let Ok(v) = u32::from_str_radix(&hex, 16) {
                                if let Some(ch) = char::from_u32(v) {
                                    s.push(ch);
                                }
                            }
                            self.pos += 4;
                        }
                        Some(c) => {
                            s.push('\\');
                            s.push(c);
                        }
                        None => return self.err("unterminated string"),
                    }
                    self.pos += 1;
                }
                Some(c) => {
                    s.push(c);
                    self.pos += 1;
                }
            }
        }
        Ok(s)
    }
    fn parse_multiline(&mut self) -> Res<String> {
        // compute indentation of the opening '''
        let mut col = 0;
        let mut i = self.pos;
        while i > 0 && self.chars[i - 1] != '\n' {
            i -= 1;
            col += 1;
        }
        self.pos += 3;
        // skip to end of line if only whitespace
        let mut lines: Vec<String> = Vec::new();
        let mut cur = String::new();
        loop {
            match self.peek() {
                None => return self.err("unterminated multiline string"),
                Some('\'') if self.peek_at(1) == Some('\'') && self.peek_at(2) == Some('\'') => {
                    self.pos += 3;
                    lines.push(cur);
                    break;
                }
                Some('\n') => {
                    lines.push(std::mem::take(&mut cur));
                    self.pos += 1;
                }
                Some(c) => {
                    cur.push(c);
                    self.pos += 1;
                }
            }
        }
        // remove first line if empty
        if !lines.is_empty() && lines[0].trim().is_empty() {
            lines.remove(0);
        }
        if let Some(last) = lines.last() {
            if last.trim().is_empty() {
                lines.pop();
            }
        }
        let out: Vec<String> = lines
            .into_iter()
            .map(|l| {
                let mut n = 0;
                let mut cs = l.chars().peekable();
                let mut res = String::new();
                while let Some(&c) = cs.peek() {
                    if n < col && c.is_whitespace() {
                        cs.next();
                        n += 1;
                    } else {
                        break;
                    }
                }
                res.extend(cs);
                res
            })
            .collect();
        Ok(out.join("\n"))
    }
    fn parse_array(&mut self) -> Res<Value> {
        self.pos += 1; // [
        let mut items = Vec::new();
        loop {
            self.skip_ws();
            match self.peek() {
                None => return self.err("unexpected end of input in array"),
                Some(']') => {
                    self.pos += 1;
                    break;
                }
                Some(',') => {
                    self.pos += 1;
                    continue;
                }
                _ => {}
            }
            let v = self.parse_value(Ctx::Array)?;
            items.push(v);
        }
        Ok(Value::Array(items))
    }
    fn parse_value(&mut self, ctx: Ctx) -> Res<Value> {
        match self.peek() {
            None => self.err("expected value"),
            Some('{') => self.parse_object(true),
            Some('[') => self.parse_array(),
            Some('"') | Some('\'') => {
                let s = self.parse_quoted()?;
                Ok(Value::String(s))
            }
            _ => self.parse_quoteless(ctx),
        }
    }
    fn parse_quoteless(&mut self, ctx: Ctx) -> Res<Value> {
        let start = self.pos;
        let mut s = String::new();
        let mut depth: i32 = 0;
        while let Some(c) = self.peek() {
            if c == '\n' || c == '\r' {
                break;
            }
            match ctx {
                Ctx::Array => {
                    if c == ',' || c == ']' {
                        break;
                    }
                }
                Ctx::Object => {
                    if c == '{' {
                        depth += 1;
                    } else if c == '}' {
                        if depth == 0 {
                            break;
                        }
                        depth -= 1;
                    } else if c == ',' && depth == 0 {
                        // a comma ends the value only if what follows looks like a key
                        let rest: String = self.chars[self.pos + 1..].iter().take_while(|&&c| c != '\n').collect();
                        if looks_like_member(&rest) {
                            break;
                        }
                    }
                }
                Ctx::Root => {}
            }
            s.push(c);
            self.pos += 1;
        }
        let _ = start;
        let t = s.trim();
        // strip trailing comments for literals only
        let lit = strip_comment(t);
        match lit {
            "true" => return Ok(Value::Bool(true)),
            "false" => return Ok(Value::Bool(false)),
            "null" => return Ok(Value::Null),
            _ => {}
        }
        if let Some(n) = parse_number(lit) {
            return Ok(Value::Number(n));
        }
        Ok(Value::String(t.to_string()))
    }
}

fn looks_like_member(rest: &str) -> bool {
    let r = rest.trim_start();
    if r.is_empty() {
        return true;
    }
    if r.starts_with('"') {
        return true;
    }
    // unquoted key followed by ':'
    let mut chars = r.chars();
    let mut n = 0;
    for c in chars.by_ref() {
        if c == ':' {
            return n > 0;
        }
        if c.is_whitespace() || c == ',' || c == '{' || c == '}' {
            return false;
        }
        n += 1;
    }
    false
}

fn strip_comment(s: &str) -> &str {
    let mut end = s.len();
    if let Some(i) = s.find(" #") {
        end = end.min(i);
    }
    if let Some(i) = s.find(" //") {
        end = end.min(i);
    }
    s[..end].trim()
}

fn parse_number(s: &str) -> Option<f64> {
    if s.is_empty() {
        return None;
    }
    let first = s.chars().next().unwrap();
    if !(first.is_ascii_digit() || first == '-') {
        return None;
    }
    if !s.chars().all(|c| c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E') {
        return None;
    }
    s.parse::<f64>().ok()
}

#[derive(Debug, Clone, Copy)]
enum Ctx {
    Root,
    Object,
    Array,
}

pub fn parse(src: &str) -> Result<Value, String> {
    let mut p = Parser {
        chars: src.chars().collect(),
        pos: 0,
        _src: src,
    };
    let v = p.parse_root()?;
    p.skip_ws();
    if p.pos < p.chars.len() {
        return p.err("trailing characters");
    }
    Ok(v)
}
EOF
