//! A cell buffer and its writing to the terminal

use crate::style::{Color, Style};
use std::io::Write;
use unicode_width::UnicodeWidthChar;

#[derive(Debug, Clone, PartialEq)]
pub struct Cell {
    pub ch: char,
    /// 0 for the continuation of a wide char
    pub width: u8,
    pub style: Style,
}

impl Cell {
    pub fn blank(style: Style) -> Self {
        Cell { ch: ' ', width: 1, style }
    }
}

pub struct Screen {
    pub width: usize,
    pub height: usize,
    pub cells: Vec<Cell>,
    prev: Vec<Cell>,
    pub first_draw: bool,
    pub cursor: Option<(usize, usize)>,
}

pub fn char_width(c: char) -> usize {
    if c == '\t' {
        return 1;
    }
    c.width().unwrap_or(0)
}

pub fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

impl Screen {
    pub fn new(width: usize, height: usize) -> Self {
        let n = width * height;
        Screen {
            width,
            height,
            cells: vec![Cell::blank(Style::new()); n],
            prev: Vec::new(),
            first_draw: true,
            cursor: None,
        }
    }
    pub fn resize(&mut self, width: usize, height: usize) {
        self.width = width;
        self.height = height;
        self.cells = vec![Cell::blank(Style::new()); width * height];
        self.prev.clear();
        self.first_draw = true;
    }
    pub fn clear(&mut self, style: Style) {
        for c in self.cells.iter_mut() {
            *c = Cell::blank(style);
        }
    }
    pub fn set(&mut self, x: usize, y: usize, ch: char, style: Style) -> usize {
        if y >= self.height || x >= self.width {
            return 0;
        }
        let w = char_width(ch);
        if w == 0 {
            return 0;
        }
        if w == 2 && x + 1 >= self.width {
            // doesn't fit
            let idx = y * self.width + x;
            self.cells[idx] = Cell { ch: ' ', width: 1, style };
            return 1;
        }
        let idx = y * self.width + x;
        self.cells[idx] = Cell { ch, width: w as u8, style };
        if w == 2 {
            self.cells[idx + 1] = Cell { ch: ' ', width: 0, style };
        }
        w
    }
    /// writes a string from x, clipping at max_x (exclusive). Returns the new x
    pub fn write_str(&mut self, x: usize, y: usize, s: &str, style: Style, max_x: usize) -> usize {
        let mut x = x;
        let max_x = max_x.min(self.width);
        for ch in s.chars() {
            let ch = if ch == '\t' { ' ' } else { ch };
            let w = char_width(ch);
            if w == 0 {
                continue;
            }
            if x + w > max_x {
                break;
            }
            x += self.set(x, y, ch, style);
        }
        x
    }
    pub fn fill(&mut self, x: usize, y: usize, to_x: usize, style: Style) -> usize {
        let to_x = to_x.min(self.width);
        let mut x = x;
        while x < to_x {
            self.set(x, y, ' ', style);
            x += 1;
        }
        x
    }
    pub fn flush<W: Write>(&mut self, w: &mut W) -> std::io::Result<()> {
        let mut out = String::new();
        let full = self.first_draw || self.prev.len() != self.cells.len();
        for y in 0..self.height {
            let row = &self.cells[y * self.width..(y + 1) * self.width];
            if !full {
                let prow = &self.prev[y * self.width..(y + 1) * self.width];
                if row == prow {
                    continue;
                }
            }
            out.push_str(&format!("\x1b[{};1H", y + 1));
            let mut cur: Option<Style> = None;
            for cell in row {
                if cell.width == 0 {
                    continue;
                }
                if cur != Some(cell.style) {
                    out.push_str("\x1b[0m");
                    push_style(&mut out, &cell.style);
                    cur = Some(cell.style);
                }
                out.push(cell.ch);
            }
            out.push_str("\x1b[0m");
        }
        if let Some((x, y)) = self.cursor {
            out.push_str(&format!("\x1b[{};{}H", y + 1, x + 1));
        }
        w.write_all(out.as_bytes())?;
        w.flush()?;
        self.prev = self.cells.clone();
        self.first_draw = false;
        Ok(())
    }
}

pub fn push_color(out: &mut String, c: &Color, fg: bool) {
    match c {
        Color::Ansi(v) => {
            out.push_str(&format!("\x1b[{};5;{}m", if fg { 38 } else { 48 }, v));
        }
        Color::Rgb(r, g, b) => {
            out.push_str(&format!("\x1b[{};2;{};{};{}m", if fg { 38 } else { 48 }, r, g, b));
        }
    }
}

pub fn push_style(out: &mut String, s: &Style) {
    if s.attrs.bold {
        out.push_str("\x1b[1m");
    }
    if s.attrs.dim {
        out.push_str("\x1b[2m");
    }
    if s.attrs.italic {
        out.push_str("\x1b[3m");
    }
    if s.attrs.underlined {
        out.push_str("\x1b[4m");
    }
    if s.attrs.slow_blink {
        out.push_str("\x1b[5m");
    }
    if s.attrs.reverse {
        out.push_str("\x1b[7m");
    }
    if s.attrs.crossed {
        out.push_str("\x1b[9m");
    }
    if s.attrs.overlined {
        out.push_str("\x1b[53m");
    }
    if let Some(c) = &s.fg {
        push_color(out, c, true);
    }
    if let Some(c) = &s.bg {
        push_color(out, c, false);
    }
}

/// Styled string writing, for non TUI outputs
pub fn styled(s: &str, style: &Style, color: bool) -> String {
    if !color || *style == Style::new() {
        return s.to_string();
    }
    let mut out = String::new();
    push_style(&mut out, style);
    out.push_str(s);
    out.push_str("\x1b[0m");
    out
}
