//! Search patterns

use regex::Regex;

#[derive(Debug, Clone)]
pub struct NameMatch {
    pub score: i32,
    /// char positions in the candidate
    pub pos: Vec<usize>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SearchObject {
    Name,
    Path,
    Content,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SearchKind {
    Fuzzy,
    Exact,
    Regex,
    Tokens,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SearchMode {
    pub object: SearchObject,
    pub kind: SearchKind,
}

impl SearchMode {
    pub const fn new(object: SearchObject, kind: SearchKind) -> Self {
        SearchMode { object, kind }
    }
}

pub struct SearchModeMap {
    /// (key, mode) ; key None means "no slash"
    pub entries: Vec<(Option<String>, SearchMode)>,
}

impl Default for SearchModeMap {
    fn default() -> Self {
        use SearchKind::*;
        use SearchObject::*;
        let mut entries: Vec<(Option<String>, SearchMode)> = Vec::new();
        let mut setm = |keys: &[&str], mode: SearchMode| {
            for k in keys {
                entries.push((Some(k.to_string()), mode));
            }
        };
        setm(&["ep", "pe"], SearchMode::new(Path, Exact));
        setm(&["fp", "pf", "p"], SearchMode::new(Path, Fuzzy));
        setm(&["rp", "pr"], SearchMode::new(Path, Regex));
        setm(&["tp", "pt", "t"], SearchMode::new(Path, Tokens));
        setm(&["en", "ne", "e"], SearchMode::new(Name, Exact));
        setm(&["fn", "nf", "n", "f"], SearchMode::new(Name, Fuzzy));
        setm(&["rn", "nr", "r"], SearchMode::new(Name, Regex));
        setm(&["tn", "nt"], SearchMode::new(Name, Tokens));
        setm(&["ce", "ec", "c"], SearchMode::new(Content, Exact));
        setm(&["rx", "rc", "cr"], SearchMode::new(Content, Regex));
        entries.push((None, SearchMode::new(Path, Fuzzy)));
        entries.push((Some(String::new()), SearchMode::new(Name, Regex)));
        SearchModeMap { entries }
    }
}

impl SearchModeMap {
    pub fn search_mode(&self, key: Option<&str>) -> Option<SearchMode> {
        for (k, m) in self.entries.iter().rev() {
            if k.as_deref() == key {
                return Some(*m);
            }
        }
        None
    }
    pub fn set(&mut self, key: Option<String>, mode: SearchMode) {
        self.entries.push((key, mode));
    }
}

// ---------------------------------------------------------------- fuzzy

const BONUS_MATCH: i32 = 50_000;
const BONUS_EXACT: i32 = 1_000;
const BONUS_START: i32 = 10;
const BONUS_START_WORD: i32 = 5;
const BONUS_CANDIDATE_LENGTH: i32 = -1;
const BONUS_MATCH_LENGTH: i32 = -10;
const BONUS_NB_HOLES: i32 = -30;
const BONUS_SINGLED_CHAR: i32 = -15;

pub fn lower_lay_char(c: char) -> char {
    let c = remove_diacritics(c);
    if c.is_uppercase() {
        c.to_lowercase().next().unwrap_or(c)
    } else {
        c
    }
}

pub fn remove_diacritics(c: char) -> char {
    match c {
        'à' | 'á' | 'â' | 'ã' | 'ä' | 'å' | 'ā' | 'ă' | 'ą' => 'a',
        'À' | 'Á' | 'Â' | 'Ã' | 'Ä' | 'Å' | 'Ā' | 'Ă' | 'Ą' => 'A',
        'ç' | 'ć' | 'ĉ' | 'ċ' | 'č' => 'c',
        'Ç' | 'Ć' | 'Ĉ' | 'Ċ' | 'Č' => 'C',
        'ď' | 'đ' => 'd',
        'Ď' | 'Đ' => 'D',
        'è' | 'é' | 'ê' | 'ë' | 'ē' | 'ĕ' | 'ė' | 'ę' | 'ě' => 'e',
        'È' | 'É' | 'Ê' | 'Ë' | 'Ē' | 'Ĕ' | 'Ė' | 'Ę' | 'Ě' => 'E',
        'ĝ' | 'ğ' | 'ġ' | 'ģ' => 'g',
        'Ĝ' | 'Ğ' | 'Ġ' | 'Ģ' => 'G',
        'ĥ' | 'ħ' => 'h',
        'Ĥ' | 'Ħ' => 'H',
        'ì' | 'í' | 'î' | 'ï' | 'ĩ' | 'ī' | 'ĭ' | 'į' | 'ı' => 'i',
        'Ì' | 'Í' | 'Î' | 'Ï' | 'Ĩ' | 'Ī' | 'Ĭ' | 'Į' | 'İ' => 'I',
        'ĵ' => 'j',
        'Ĵ' => 'J',
        'ķ' => 'k',
        'Ķ' => 'K',
        'ĺ' | 'ļ' | 'ľ' | 'ŀ' | 'ł' => 'l',
        'Ĺ' | 'Ļ' | 'Ľ' | 'Ŀ' | 'Ł' => 'L',
        'ñ' | 'ń' | 'ņ' | 'ň' => 'n',
        'Ñ' | 'Ń' | 'Ņ' | 'Ň' => 'N',
        'ò' | 'ó' | 'ô' | 'õ' | 'ö' | 'ø' | 'ō' | 'ŏ' | 'ő' => 'o',
        'Ò' | 'Ó' | 'Ô' | 'Õ' | 'Ö' | 'Ø' | 'Ō' | 'Ŏ' | 'Ő' => 'O',
        'ŕ' | 'ŗ' | 'ř' => 'r',
        'Ŕ' | 'Ŗ' | 'Ř' => 'R',
        'ś' | 'ŝ' | 'ş' | 'š' => 's',
        'Ś' | 'Ŝ' | 'Ş' | 'Š' => 'S',
        'ţ' | 'ť' | 'ŧ' => 't',
        'Ţ' | 'Ť' | 'Ŧ' => 'T',
        'ù' | 'ú' | 'û' | 'ü' | 'ũ' | 'ū' | 'ŭ' | 'ů' | 'ű' | 'ų' => 'u',
        'Ù' | 'Ú' | 'Û' | 'Ü' | 'Ũ' | 'Ū' | 'Ŭ' | 'Ů' | 'Ű' | 'Ų' => 'U',
        'ŵ' => 'w',
        'Ŵ' => 'W',
        'ý' | 'ÿ' | 'ŷ' => 'y',
        'Ý' | 'Ÿ' | 'Ŷ' => 'Y',
        'ź' | 'ż' | 'ž' => 'z',
        'Ź' | 'Ż' | 'Ž' => 'Z',
        _ => c,
    }
}

#[derive(Debug, Clone)]
pub struct FuzzyPattern {
    pub chars: Vec<char>,
    max_nb_holes: usize,
}

enum MatchSearchResult {
    Perfect(NameMatch),
    Some(NameMatch),
    None,
}

impl FuzzyPattern {
    pub fn from(pat: &str) -> Self {
        let chars: Vec<char> = pat.chars().map(lower_lay_char).collect();
        let max_nb_holes = match chars.len() {
            1 => 0,
            2 => 1,
            3 => 2,
            4 => 2,
            5 => 2,
            6 => 3,
            7 => 3,
            8 => 4,
            _ => chars.len() * 4 / 7,
        };
        FuzzyPattern { chars, max_nb_holes }
    }

    fn tight_match_from_index(&self, cand: &[char], start_idx: usize) -> MatchSearchResult {
        let mut pos = vec![0usize; self.chars.len()];
        let mut cand_idx = 1 + start_idx;
        let mut pat_idx = 1;
        let mut in_hole = false;
        let mut nb_holes = 0;
        let mut nb_singled_chars = 0;
        pos[0] = start_idx;
        let cand_len = cand.len();
        while pat_idx < self.chars.len() {
            if cand_idx >= cand_len {
                return MatchSearchResult::None;
            }
            if cand[cand_idx] == self.chars[pat_idx] {
                pos[pat_idx] = cand_idx;
                if in_hole {
                    // we're no more in a hole
                    in_hole = false;
                    if pos[pat_idx - 1] < cand_idx - 1 {
                        // the previous matching char was isolated
                        if pat_idx > 1 && pos[pat_idx - 2] < pos[pat_idx - 1] - 1 {
                            nb_singled_chars += 1;
                        }
                    }
                }
                pat_idx += 1;
            } else if !in_hole {
                // we're entering a hole
                nb_holes += 1;
                if nb_holes > self.max_nb_holes {
                    return MatchSearchResult::None;
                }
                in_hole = true;
            }
            cand_idx += 1;
        }
        let match_len = 1 + cand_idx - pos[0] - 1;
        let mut score = BONUS_MATCH;
        score += BONUS_CANDIDATE_LENGTH * (cand_len as i32);
        score += BONUS_SINGLED_CHAR * nb_singled_chars;
        score += BONUS_NB_HOLES * (nb_holes as i32);
        score += match_len as i32 * BONUS_MATCH_LENGTH;
        if start_idx == 0 {
            score += BONUS_START + BONUS_START_WORD;
            if cand_len == self.chars.len() {
                score += BONUS_EXACT;
                return MatchSearchResult::Perfect(NameMatch { score, pos });
            }
        } else {
            let previous = cand[start_idx - 1];
            if previous == '_' || previous == ' ' || previous == '-' {
                score += BONUS_START_WORD;
            }
        }
        MatchSearchResult::Some(NameMatch { score, pos })
    }

    pub fn find(&self, candidate: &str) -> Option<NameMatch> {
        if self.chars.is_empty() {
            return None;
        }
        let cand: Vec<char> = candidate.chars().map(lower_lay_char).collect();
        if cand.len() < self.chars.len() {
            return None;
        }
        let mut best_score = 0;
        let mut best_match: Option<NameMatch> = None;
        let n = cand.len() - self.chars.len();
        for start_idx in 0..=n {
            if cand[start_idx] == self.chars[0] {
                match self.tight_match_from_index(&cand, start_idx) {
                    MatchSearchResult::Perfect(m) => return Some(m),
                    MatchSearchResult::Some(m) => {
                        if m.score > best_score {
                            best_score = m.score;
                            best_match = Some(m);
                        }
                    }
                    MatchSearchResult::None => {}
                }
            }
        }
        best_match
    }
}

// ---------------------------------------------------------------- exact

#[derive(Debug, Clone)]
pub struct ExactPattern {
    pub pattern: String,
    lower: Vec<char>,
}

impl ExactPattern {
    pub fn from(s: &str) -> Self {
        ExactPattern { pattern: s.to_string(), lower: s.chars().collect() }
    }
    pub fn find(&self, candidate: &str) -> Option<NameMatch> {
        let cand: Vec<char> = candidate.chars().collect();
        let n = self.lower.len();
        if n == 0 || cand.len() < n {
            return None;
        }
        for start in 0..=(cand.len() - n) {
            if cand[start..start + n] == self.lower[..] {
                let mut score = BONUS_MATCH + BONUS_CANDIDATE_LENGTH * cand.len() as i32;
                if start == 0 {
                    score += BONUS_START;
                    if cand.len() == n {
                        score += BONUS_EXACT;
                    }
                } else {
                    let prev = cand[start - 1];
                    if prev == '_' || prev == ' ' || prev == '-' || prev == '/' {
                        score += BONUS_START_WORD;
                    }
                }
                return Some(NameMatch { score, pos: (start..start + n).collect() });
            }
        }
        None
    }
}

// ---------------------------------------------------------------- tokens

#[derive(Debug, Clone)]
pub struct TokPattern {
    tokens: Vec<Vec<char>>,
}

impl TokPattern {
    pub fn from(s: &str) -> Self {
        let mut tokens: Vec<Vec<char>> = s
            .split(|c| c == ',' || c == ' ')
            .filter(|t| !t.is_empty())
            .map(|t| t.chars().map(lower_lay_char).collect())
            .collect();
        tokens.sort_by(|a, b| b.len().cmp(&a.len()));
        TokPattern { tokens }
    }
    pub fn find(&self, candidate: &str) -> Option<NameMatch> {
        if self.tokens.is_empty() {
            return None;
        }
        let cand: Vec<char> = candidate.chars().map(lower_lay_char).collect();
        let mut used = vec![false; cand.len()];
        let mut pos = Vec::new();
        for tok in &self.tokens {
            let n = tok.len();
            if n > cand.len() {
                return None;
            }
            let mut found = false;
            for start in 0..=(cand.len() - n) {
                if (start..start + n).any(|i| used[i]) {
                    continue;
                }
                if cand[start..start + n] == tok[..] {
                    for i in start..start + n {
                        used[i] = true;
                        pos.push(i);
                    }
                    found = true;
                    break;
                }
            }
            if !found {
                return None;
            }
        }
        pos.sort_unstable();
        let score = BONUS_MATCH + BONUS_CANDIDATE_LENGTH * cand.len() as i32;
        Some(NameMatch { score, pos })
    }
}

// ---------------------------------------------------------------- regex

#[derive(Debug, Clone)]
pub struct RegexPattern {
    pub rex: Regex,
    pub source: String,
    pub flags: String,
}

impl RegexPattern {
    pub fn from(pat: &str, flags: &str) -> Result<Self, String> {
        let mut builder = regex::RegexBuilder::new(pat);
        for c in flags.chars() {
            match c {
                'i' => {
                    builder.case_insensitive(true);
                }
                'U' => {
                    builder.swap_greed(true);
                }
                _ => return Err(format!("Unknown regular expression flag: {:?}", c)),
            }
        }
        let rex = builder.build().map_err(|e| format!("Invalid Regular Expression: {}", e))?;
        Ok(RegexPattern { rex, source: pat.to_string(), flags: flags.to_string() })
    }
    pub fn find(&self, candidate: &str) -> Option<NameMatch> {
        self.rex.find(candidate).map(|rm| {
            let before = candidate[..rm.start()].chars().count();
            let n = rm.as_str().chars().count();
            NameMatch { score: 1, pos: (before..before + n).collect() }
        })
    }
}

// ---------------------------------------------------------------- elementary patterns

#[derive(Debug, Clone)]
pub enum Pattern {
    NameFuzzy(FuzzyPattern),
    PathFuzzy(FuzzyPattern),
    NameExact(ExactPattern),
    PathExact(ExactPattern),
    NameRegex(RegexPattern),
    PathRegex(RegexPattern),
    NameTokens(TokPattern),
    PathTokens(TokPattern),
    ContentExact(ExactPattern),
    ContentRegex(RegexPattern),
}

pub struct Candidate<'a> {
    pub name: &'a str,
    pub subpath: &'a str,
    pub path: &'a std::path::Path,
    pub regular_file: bool,
}

impl Pattern {
    pub fn object(&self) -> SearchObject {
        match self {
            Pattern::NameFuzzy(_) | Pattern::NameExact(_) | Pattern::NameRegex(_) | Pattern::NameTokens(_) => {
                SearchObject::Name
            }
            Pattern::PathFuzzy(_) | Pattern::PathExact(_) | Pattern::PathRegex(_) | Pattern::PathTokens(_) => {
                SearchObject::Path
            }
            Pattern::ContentExact(_) | Pattern::ContentRegex(_) => SearchObject::Content,
        }
    }
    pub fn find_str(&self, s: &str) -> Option<NameMatch> {
        match self {
            Pattern::NameFuzzy(p) | Pattern::PathFuzzy(p) => p.find(s),
            Pattern::NameExact(p) | Pattern::PathExact(p) => p.find(s),
            Pattern::NameRegex(p) | Pattern::PathRegex(p) => p.find(s),
            Pattern::NameTokens(p) | Pattern::PathTokens(p) => p.find(s),
            Pattern::ContentExact(_) | Pattern::ContentRegex(_) => None,
        }
    }
    pub fn score_of(&self, c: &Candidate) -> Option<i32> {
        match self.object() {
            SearchObject::Name => self.find_str(c.name).map(|m| m.score),
            SearchObject::Path => self.find_str(c.subpath).map(|m| m.score),
            SearchObject::Content => {
                if !c.regular_file {
                    return None;
                }
                if content_match(self, c.path) {
                    Some(1)
                } else {
                    None
                }
            }
        }
    }
    pub fn has_real_scores(&self) -> bool {
        matches!(
            self,
            Pattern::NameFuzzy(_) | Pattern::PathFuzzy(_) | Pattern::NameExact(_) | Pattern::PathExact(_)
                | Pattern::NameTokens(_) | Pattern::PathTokens(_)
        )
    }
}

pub const MAX_CONTENT_SIZE: u64 = 10 * 1000 * 1000;

fn content_match(p: &Pattern, path: &std::path::Path) -> bool {
    let Ok(md) = std::fs::metadata(path) else { return false };
    if md.len() > MAX_CONTENT_SIZE {
        return false;
    }
    let Ok(bytes) = std::fs::read(path) else { return false };
    // binary files are skipped
    if bytes.iter().take(1000).any(|&b| b == 0) {
        return false;
    }
    match p {
        Pattern::ContentExact(e) => {
            let needle = e.pattern.as_bytes();
            if needle.is_empty() {
                return false;
            }
            bytes.windows(needle.len()).any(|w| w == needle)
        }
        Pattern::ContentRegex(r) => {
            let s = String::from_utf8_lossy(&bytes);
            r.rex.is_match(&s)
        }
        _ => false,
    }
}

/// Find the line of the first content match in a file, if any
pub fn content_first_match(p: &Pattern, path: &std::path::Path) -> Option<(usize, String)> {
    let bytes = std::fs::read(path).ok()?;
    let s = String::from_utf8_lossy(&bytes);
    for (i, line) in s.lines().enumerate() {
        let m = match p {
            Pattern::ContentExact(e) => line.contains(&e.pattern),
            Pattern::ContentRegex(r) => r.rex.is_match(line),
            _ => false,
        };
        if m {
            return Some((i + 1, line.to_string()));
        }
    }
    None
}

// ---------------------------------------------------------------- composite

#[derive(Debug, Clone)]
pub enum Composite {
    Atom(Pattern),
    Not(Box<Composite>),
    And(Box<Composite>, Box<Composite>),
    Or(Box<Composite>, Box<Composite>),
}

#[derive(Debug, Clone, Default)]
pub struct InputPattern {
    pub raw: String,
    pub composite: Option<Composite>,
}

impl InputPattern {
    pub fn none() -> Self {
        InputPattern::default()
    }
    pub fn is_some(&self) -> bool {
        self.composite.is_some()
    }
    pub fn is_none(&self) -> bool {
        self.composite.is_none()
    }
    pub fn score_of(&self, c: &Candidate) -> Option<i32> {
        match &self.composite {
            None => Some(1),
            Some(comp) => comp.score_of(c),
        }
    }
    pub fn has_real_scores(&self) -> bool {
        match &self.composite {
            None => false,
            Some(c) => c.has_real_scores(),
        }
    }
    /// the first elementary pattern, used for highlighting names
    pub fn first_atom(&self) -> Option<&Pattern> {
        self.composite.as_ref().and_then(|c| c.first_positive_atom())
    }
    pub fn is_path_search(&self) -> bool {
        self.first_atom().map(|p| p.object() == SearchObject::Path).unwrap_or(false)
    }
    pub fn content_atom(&self) -> Option<&Pattern> {
        self.composite.as_ref().and_then(|c| c.content_atom())
    }
}

impl Composite {
    pub fn score_of(&self, c: &Candidate) -> Option<i32> {
        match self {
            Composite::Atom(p) => p.score_of(c),
            Composite::Not(inner) => match inner.score_of(c) {
                Some(_) => None,
                None => Some(1),
            },
            Composite::And(a, b) => {
                let sa = a.score_of(c)?;
                let sb = b.score_of(c)?;
                Some(sa + sb)
            }
            Composite::Or(a, b) => match a.score_of(c) {
                Some(s) => Some(s),
                None => b.score_of(c),
            },
        }
    }
    pub fn has_real_scores(&self) -> bool {
        match self {
            Composite::Atom(p) => p.has_real_scores(),
            Composite::Not(_) => false,
            Composite::And(a, b) | Composite::Or(a, b) => a.has_real_scores() || b.has_real_scores(),
        }
    }
    pub fn first_positive_atom(&self) -> Option<&Pattern> {
        match self {
            Composite::Atom(p) => Some(p),
            Composite::Not(_) => None,
            Composite::And(a, b) | Composite::Or(a, b) => a.first_positive_atom().or_else(|| b.first_positive_atom()),
        }
    }
    pub fn content_atom(&self) -> Option<&Pattern> {
        match self {
            Composite::Atom(p) => {
                if p.object() == SearchObject::Content {
                    Some(p)
                } else {
                    None
                }
            }
            Composite::Not(_) => None,
            Composite::And(a, b) | Composite::Or(a, b) => a.content_atom().or_else(|| b.content_atom()),
        }
    }
}

/// build an elementary pattern from its mode key, body and flags
pub fn make_pattern(map: &SearchModeMap, key: Option<&str>, body: &str, flags: Option<&str>) -> Result<Option<Pattern>, String> {
    let mode = match map.search_mode(key) {
        Some(m) => m,
        None => {
            return Err(format!("Invalid search mode key: {:?}", key.unwrap_or("")));
        }
    };
    if body.is_empty() {
        return Ok(None);
    }
    let flags = flags.unwrap_or("");
    use SearchKind::*;
    use SearchObject::*;
    Ok(Some(match (mode.object, mode.kind) {
        (Name, Fuzzy) => Pattern::NameFuzzy(FuzzyPattern::from(body)),
        (Path, Fuzzy) => Pattern::PathFuzzy(FuzzyPattern::from(body)),
        (Name, Exact) => Pattern::NameExact(ExactPattern::from(body)),
        (Path, Exact) => Pattern::PathExact(ExactPattern::from(body)),
        (Name, Regex) => Pattern::NameRegex(RegexPattern::from(body, flags)?),
        (Path, Regex) => Pattern::PathRegex(RegexPattern::from(body, flags)?),
        (Name, Tokens) => Pattern::NameTokens(TokPattern::from(body)),
        (Path, Tokens) => Pattern::PathTokens(TokPattern::from(body)),
        (Content, Exact) => Pattern::ContentExact(ExactPattern::from(body)),
        (Content, Regex) => Pattern::ContentRegex(RegexPattern::from(body, flags)?),
        (Content, _) => Pattern::ContentExact(ExactPattern::from(body)),
    }))
}
