//! Search patterns

use regex::Regex;

#[derive(Debug, Clone)]
pub struct NameMatch {
    pub score: i32,
    /// char positions in the candidate
    pub pos: Vec<usize>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SearchObject {
    Name,
    Path,
    Content,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SearchKind {
    Fuzzy,
    Exact,
    Regex,
    Tokens,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SearchMode {
    pub object: SearchObject,
    pub kind: SearchKind,
}

impl SearchMode {
    pub const fn new(object: SearchObject, kind: SearchKind) -> Self {
        SearchMode { object, kind }
    }
}

pub struct SearchModeMap {
    /// (key, mode) ; key None means "no slash"
    pub entries: Vec<(Option<String>, SearchMode)>,
}

impl Default for SearchModeMap {
    fn default() -> Self {
        use SearchKind::*;
        use SearchObject::*;
        let mut entries: Vec<(Option<String>, SearchMode)> = Vec::new();
        let mut setm = |keys: &[&str], mode: SearchMode| {
