#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Not,
    And,
    Or,
    Open,
    Close,
    Atom(Option<String>, String, Option<String>),
}

fn tokenize(s: &str) -> Vec<Tok> {
    let chars: Vec<char> = s.chars().collect();
    let mut toks = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '!' => {
                toks.push(Tok::Not);
                i += 1;
            }
            '&' => {
                toks.push(Tok::And);
                i += 1;
            }
