                let mut part = String::new();
                let mut mode: Option<String> = None;
                let mut body = String::new();
                let mut flags: Option<String> = None;
                let mut stage = 0; // 0: before slash, 1: in body after slash, 2: flags
                while i < chars.len() {
                    let c = chars[i];
                    if c == '\\' && i + 1 < chars.len() {
                        let n = chars[i + 1];
