                            }
                        }
                        _ => {
                            if matches!(c, '&' | '|' | '(' | ')') {
                                break;
                            }
                            flags.get_or_insert_with(String::new).push(c);
                        }
                    }
                    i += 1;
                }
                if stage == 0 {
                    toks.push(Tok::Atom(None, part, None));
                } else {
                    toks.push(Tok::Atom(mode, body, flags));
                }
