            let right = self.parse_not()?;
            left = match (left, right) {
                (Some(l), Some(r)) => Some(Composite::And(Box::new(l), Box::new(r))),
                (l, None) => l,
                (None, r) => r,
            };
        }
        Ok(left)
    }
    fn parse_not(&mut self) -> Result<Option<Composite>, String> {
        if self.pos < self.toks.len() && self.toks[self.pos] == Tok::Not {
            self.pos += 1;
            let inner = self.parse_not()?;
            return Ok(inner.map(|i| Composite::Not(Box::new(i))));
        }
        self.parse_primary()
    }
    fn parse_primary(&mut self) -> Result<Option<Composite>, String> {
        if self.pos >= self.toks.len() {
            return Ok(None);
        }
        match self.toks[self.pos].clone() {
            Tok::Open => {
                self.pos += 1;
                let inner = self.parse_or()?;
                if self.pos < self.toks.len() && self.toks[self.pos] == Tok::Close {
                    self.pos += 1;
                }
                Ok(inner)
            }
            Tok::Close => {
                self.pos += 1;
                Ok(None)
            }
            Tok::Atom(mode, body, flags) => {
                self.pos += 1;
                let p = make_pattern(self.map, mode.as_deref(), &body, flags.as_deref())?;
                Ok(p.map(Composite::Atom))
            }
            _ => {
                self.pos += 1;
                Ok(None)
            }
        }
    }
}

pub fn parse_pattern(raw: &str, map: &SearchModeMap) -> Result<InputPattern, String> {
    if raw.is_empty() {
        return Ok(InputPattern::none());
    }
    let toks = tokenize(raw);
    let mut p = TokParser { toks, pos: 0, map };
    let mut comp = p.parse_or()?;
    while p.pos < p.toks.len() {
        // remaining tokens (unbalanced parenthesis...)
        p.pos += 1;
        if let Some(c) = p.parse_or()? {
            comp = Some(match comp {
                Some(l) => Composite::And(Box::new(l), Box::new(c)),
                None => c,
            });
        }
    }
    Ok(InputPattern { raw: raw.to_string(), composite: comp })
}

pub fn parse(raw: &str, map: &SearchModeMap) -> CommandParts {
    let (pat, verb) = split(raw);
    let (pattern, pattern_error) = match parse_pattern(&pat, map) {
        Ok(p) => (p, None),
        Err(e) => (InputPattern::none(), Some(e)),
    };
    CommandParts {
        raw_pattern: pat,
        pattern,
        pattern_error,
        verb_invocation: verb.map(|v| VerbInvocation::from(&v)),
    }
}
