    rex: Regex,
    negated: bool,
    dir_only: bool,
    /// whether the rule is matched against the relative path (else the name)
    anchored: bool,
}

#[derive(Debug, Clone, Default)]
pub struct IgnoreFile {
    /// directory containing the file
    dir: PathBuf,
    rules: Vec<Rule>,
