fn glob_to_regex(glob: &str) -> String {
    let mut re = String::from("^");
    let chars: Vec<char> = glob.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '*' => {
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    // **
                    let at_start = i == 0 || chars[i - 1] == '/';
                    let at_end = i + 2 >= chars.len() || chars[i + 2] == '/';
                    if at_start && at_end {
                        if i + 2 < chars.len() {
                            // "**/" : zero or more directories
                            re.push_str("(?:.*/)?");
                            i += 3;
                            continue;
                        } else {
                            re.push_str(".*");
                            i += 2;
                            continue;
                        }
                    }
                    re.push_str("[^/]*");
                    i += 2;
                    continue;
                }
                re.push_str("[^/]*");
            }
            '?' => re.push_str("[^/]"),
            '[' => {
                // character class
                let mut j = i + 1;
                let mut class = String::from("[");
                if j < chars.len() && (chars[j] == '!' || chars[j] == '^') {
                    class.push('^');
                    j += 1;
                }
                let mut closed = false;
                while j < chars.len() {
                    let d = chars[j];
                    if d == ']' && j > i + 1 {
                        closed = true;
                        break;
                    }
                    if d == '\\' {
                        class.push_str("\\\\");
                    } else if d == '[' {
                        class.push_str("\\[");
                    } else {
                        class.push(d);
                    }
                    j += 1;
                }
                if closed {
                    class.push(']');
                    re.push_str(&class);
                    i = j + 1;
                    continue;
                } else {
                    re.push_str("\\[");
                }
            }
            '\\' => {
                if i + 1 < chars.len() {
                    re.push_str(&regex::escape(&chars[i + 1].to_string()));
                    i += 2;
                    continue;
                }
            }
            c => re.push_str(&regex::escape(&c.to_string())),
        }
        i += 1;
    }
    re.push('$');
    re
}

impl IgnoreFile {
    pub fn parse(dir: &Path, content: &str) -> Self {
        let mut rules = Vec::new();
        for line in content.lines() {
            let mut l = line.trim_end_matches('\r');
            if l.is_empty() || l.starts_with('#') {
                continue;
            }
            // trailing spaces are ignored unless escaped
            let trimmed = l.trim_end();
            if !trimmed.ends_with('\\') {
                l = trimmed;
            }
            let mut negated = false;
            let mut p = l;
            if let Some(r) = p.strip_prefix('!') {
                negated = true;
                p = r;
            } else if p.starts_with("\\!") || p.starts_with("\\#") {
                p = &p[1..];
            }
            let mut dir_only = false;
            if let Some(r) = p.strip_suffix('/') {
                dir_only = true;
                p = r;
            }
            if p.is_empty() {
                continue;
            }
            let anchored = p.contains('/');
            let p = p.strip_prefix('/').unwrap_or(p);
            let re = glob_to_regex(p);
            if let Ok(rex) = Regex::new(&re) {
                rules.push(Rule { rex, negated, dir_only, anchored });
            }
        }
        IgnoreFile { dir: dir.to_path_buf(), rules }
    }
    /// Some(true) if ignored, Some(false) if explicitly whitelisted, None if no rule matches
    fn check(&self, path: &Path, name: &str, is_dir: bool) -> Option<bool> {
        let rel = match path.strip_prefix(&self.dir) {
            Ok(r) => r.to_string_lossy().to_string(),
            Err(_) => return None,
        };
        for rule in self.rules.iter().rev() {
            if rule.dir_only && !is_dir {
                continue;
            }
            let m = if rule.anchored { rule.rex.is_match(&rel) } else { rule.rex.is_match(name) };
            if m {
                return Some(!rule.negated);
            }
        }
        None
    }
}

/// The chain of ignore files applying to a directory
#[derive(Debug, Clone, Default)]
pub struct IgnoreChain {
    files: Vec<std::rc::Rc<IgnoreFile>>,
    pub in_repo: bool,
}

impl IgnoreChain {
    pub fn is_ignored(&self, path: &Path, name: &str, is_dir: bool) -> bool {
        for f in self.files.iter().rev() {
            if let Some(r) = f.check(path, name, is_dir) {
                return r;
            }
        }
        false
    }
}

pub struct Ignorer {
    cache: HashMap<PathBuf, Option<std::rc::Rc<IgnoreFile>>>,
}

pub fn find_git_root(dir: &Path) -> Option<PathBuf> {
    let mut d = Some(dir);
    while let Some(p) = d {
        if p.join(".git").exists() {
            return Some(p.to_path_buf());
        }
        d = p.parent();
    }
    None
}

impl Ignorer {
    pub fn new() -> Self {
        Ignorer { cache: HashMap::new() }
    }
    fn load(&mut self, path: PathBuf) -> Option<std::rc::Rc<IgnoreFile>> {
        if let Some(c) = self.cache.get(&path) {
            return c.clone();
        }
        let r = std::fs::read_to_string(&path)
            .ok()
            .map(|c| std::rc::Rc::new(IgnoreFile::parse(path.parent().unwrap_or(Path::new("/")), &c)));
        self.cache.insert(path, r.clone());
        r
    }
    /// chain for the root directory of the tree (taking parents into account)
    pub fn root_chain(&mut self, dir: &Path) -> IgnoreChain {
        let mut chain = IgnoreChain::default();
        let git_root = find_git_root(dir);
        // directories from the top to dir
        let mut dirs: Vec<PathBuf> = Vec::new();
        let mut d = Some(dir);
        while let Some(p) = d {
            dirs.push(p.to_path_buf());
            if let Some(gr) = &git_root {
                if p == gr.as_path() {
                    break;
                }
            }
            d = p.parent();
        }
        dirs.reverse();
        if let Some(gr) = &git_root {
            chain.in_repo = true;
            if let Some(home) = std::env::var_os("HOME") {
                let global = PathBuf::from(home).join(".config/git/ignore");
                if let Some(f) = self.load_with_dir(&global, gr) {
                    chain.files.push(f);
                }
            }
            if let Some(f) = self.load_with_dir(&gr.join(".git/info/exclude"), gr) {
                chain.files.push(f);
            }
        }
        for d in dirs {
            self.push_dir(&mut chain, &d, git_root.is_some());
        }
        chain
    }
    fn load_with_dir(&mut self, file: &Path, dir: &Path) -> Option<std::rc::Rc<IgnoreFile>> {
        let key = file.to_path_buf();
        if let Some(c) = self.cache.get(&key) {
            return c.clone();
        }
        let r = std::fs::read_to_string(file).ok().map(|c| std::rc::Rc::new(IgnoreFile::parse(dir, &c)));
        self.cache.insert(key, r.clone());
        r
    }
    fn push_dir(&mut self, chain: &mut IgnoreChain, dir: &Path, in_repo: bool) {
        if in_repo {
            if let Some(f) = self.load(dir.join(".gitignore")) {
                chain.files.push(f);
            }
        }
        if let Some(f) = self.load(dir.join(".ignore")) {
            chain.files.push(f);
        }
    }
    pub fn child_chain(&mut self, parent: &IgnoreChain, dir: &Path) -> IgnoreChain {
        let mut chain = parent.clone();
        let mut in_repo = parent.in_repo;
        if !in_repo && dir.join(".git").exists() {
            in_repo = true;
            chain.in_repo = true;
        }
        self.push_dir(&mut chain, dir, in_repo);
        chain
    }
}
