//! Tree building and tree structure

use crate::gitignore::{IgnoreChain, Ignorer};
use crate::pattern::{Candidate, InputPattern};
use std::collections::VecDeque;
use std::fs;
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Sort {
    None,
    Count,
    Date,
    Size,
    TypeDirsFirst,
    TypeDirsLast,
}

impl Sort {
    pub fn prevent_deep_display(&self) -> bool {
        matches!(self, Sort::Count | Sort::Date | Sort::Size)
    }
}

#[derive(Debug, Clone)]
pub struct TreeOptions {
    pub show_hidden: bool,
    pub respect_git_ignore: bool,
    pub only_folders: bool,
    pub show_sizes: bool,
    pub show_dates: bool,
    pub show_permissions: bool,
    pub show_counts: bool,
    pub show_git_file_info: bool,
    pub show_device_id: bool,
    pub show_root_fs: bool,
    pub trim_root: bool,
    pub sort: Sort,
    pub show_tree: bool,
    pub filter_by_git_status: bool,
    pub max_depth: Option<u16>,
    pub date_time_format: String,
    pub pattern: InputPattern,
}

impl Default for TreeOptions {
    fn default() -> Self {
        TreeOptions {
            show_hidden: false,
            respect_git_ignore: true,
            only_folders: false,
            show_sizes: false,
            show_dates: false,
            show_permissions: false,
            show_counts: false,
            show_git_file_info: false,
            show_device_id: false,
            show_root_fs: false,
            trim_root: false,
            sort: Sort::None,
            show_tree: true,
            filter_by_git_status: false,
            max_depth: None,
            date_time_format: "%Y/%m/%d %R".to_string(),
            pattern: InputPattern::none(),
        }
    }
}

impl TreeOptions {
    pub fn without_pattern(&self) -> Self {
        let mut o = self.clone();
        o.pattern = InputPattern::none();
        o
    }
    pub fn needs_sums(&self) -> bool {
        self.show_sizes || self.show_dates || self.show_counts || self.sort != Sort::None
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum LineType {
    File,
    Dir,
    SymLink { direct_target: String, final_is_dir: bool, final_target: PathBuf },
    BrokenSymLink(String),
    Pruning,
}

#[derive(Debug, Clone, Copy, Default)]
pub struct FileSum {
    pub size: u64,
    pub count: usize,
    pub modified: i64,
    pub sparse: bool,
}

#[derive(Debug, Clone)]
pub struct TreeLine {
    pub bid: usize,
    pub parent_bid: Option<usize>,
    pub left_branches: Vec<bool>,
    pub depth: u16,
    pub path: PathBuf,
    pub subpath: String,
    pub name: String,
    pub line_type: LineType,
    pub has_error: bool,
    pub unlisted: usize,
    pub score: i32,
    pub direct_match: bool,
    pub is_exe: bool,
    pub mode: u32,
    pub uid: u32,
    pub gid: u32,
    pub dev: u64,
    pub size: u64,
    pub blocks: u64,
    pub mtime: i64,
    pub sum: Option<FileSum>,
    pub nb_kept_children: usize,
}

impl TreeLine {
    pub fn is_dir(&self) -> bool {
        matches!(self.line_type, LineType::Dir)
    }
    pub fn is_selectable(&self) -> bool {
        !matches!(self.line_type, LineType::Pruning)
    }
    pub fn is_file(&self) -> bool {
        matches!(self.line_type, LineType::File)
    }
    /// a dir or a link to a dir
    pub fn is_dir_like(&self) -> bool {
        match &self.line_type {
            LineType::Dir => true,
            LineType::SymLink { final_is_dir, .. } => *final_is_dir,
            _ => false,
        }
    }
    pub fn target_path(&self) -> PathBuf {
        match &self.line_type {
            LineType::SymLink { final_target, .. } => final_target.clone(),
            _ => self.path.clone(),
        }
    }
}

