//! Tree building and tree structure

use crate::gitignore::{IgnoreChain, Ignorer};
use crate::pattern::{Candidate, InputPattern};
use std::collections::VecDeque;
use std::fs;
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Sort {
    None,
    Count,
    Date,
    Size,
    TypeDirsFirst,
    TypeDirsLast,
}

impl Sort {
    pub fn prevent_deep_display(&self) -> bool {
        matches!(self, Sort::Count | Sort::Date | Sort::Size)
    }
}

#[derive(Debug, Clone)]
pub struct TreeOptions {
    pub show_hidden: bool,
    pub respect_git_ignore: bool,
    pub only_folders: bool,
    pub show_sizes: bool,
    pub show_dates: bool,
    pub show_permissions: bool,
    pub show_counts: bool,
    pub show_git_file_info: bool,
    pub show_device_id: bool,
    pub show_root_fs: bool,
    pub trim_root: bool,
    pub sort: Sort,
    pub show_tree: bool,
    pub filter_by_git_status: bool,
    pub max_depth: Option<u16>,
    pub date_time_format: String,
    pub pattern: InputPattern,
}

impl Default for TreeOptions {
    fn default() -> Self {
        TreeOptions {
            show_hidden: false,
            respect_git_ignore: true,
            only_folders: false,
            show_sizes: false,
            show_dates: false,
            show_permissions: false,
            show_counts: false,
            show_git_file_info: false,
            show_device_id: false,
            show_root_fs: false,
            trim_root: false,
            sort: Sort::None,
            show_tree: true,
            filter_by_git_status: false,
            max_depth: None,
            date_time_format: "%Y/%m/%d %R".to_string(),
            pattern: InputPattern::none(),
        }
    }
}

impl TreeOptions {
    pub fn without_pattern(&self) -> Self {
        let mut o = self.clone();
        o.pattern = InputPattern::none();
        o
    }
    pub fn needs_sums(&self) -> bool {
        self.show_sizes || self.show_dates || self.show_counts || self.sort != Sort::None
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum LineType {
    File,
    Dir,
    SymLink { direct_target: String, final_is_dir: bool, final_target: PathBuf },
    BrokenSymLink(String),
    Pruning,
}

#[derive(Debug, Clone, Copy, Default)]
pub struct FileSum {
    pub size: u64,
    pub count: usize,
    pub modified: i64,
    pub sparse: bool,
}

#[derive(Debug, Clone)]
pub struct TreeLine {
    pub bid: usize,
    pub parent_bid: Option<usize>,
    pub left_branches: Vec<bool>,
    pub depth: u16,
    pub path: PathBuf,
    pub subpath: String,
    pub name: String,
    pub line_type: LineType,
    pub has_error: bool,
    pub unlisted: usize,
    pub score: i32,
    pub direct_match: bool,
    pub is_exe: bool,
    pub mode: u32,
    pub uid: u32,
    pub gid: u32,
    pub dev: u64,
    pub size: u64,
    pub blocks: u64,
    pub mtime: i64,
    pub sum: Option<FileSum>,
    pub nb_kept_children: usize,
}

impl TreeLine {
    pub fn is_dir(&self) -> bool {
        matches!(self.line_type, LineType::Dir)
    }
    pub fn is_selectable(&self) -> bool {
        !matches!(self.line_type, LineType::Pruning)
    }
    pub fn is_file(&self) -> bool {
        matches!(self.line_type, LineType::File)
    }
    /// a dir or a link to a dir
    pub fn is_dir_like(&self) -> bool {
        match &self.line_type {
            LineType::Dir => true,
            LineType::SymLink { final_is_dir, .. } => *final_is_dir,
            _ => false,
        }
    }
    pub fn target_path(&self) -> PathBuf {
        match &self.line_type {
            LineType::SymLink { final_target, .. } => final_target.clone(),
            _ => self.path.clone(),
        }
    }
}

#[derive(Debug, Clone)]
pub struct Tree {
    pub lines: Vec<TreeLine>,
    pub selection: usize,
    pub options: TreeOptions,
    pub scroll: usize,
    pub total_search: bool,
    pub nb_gitignored: usize,
    pub nb_hidden: usize,
}

struct BLine {
    parent: Option<usize>,
    path: PathBuf,
    subpath: String,
    name: String,
    depth: u16,
    kind: Kind,
    children: Option<Vec<usize>>,
    next_child_idx: usize,
    has_match: bool,
    direct_match: bool,
    score: i32,
    nb_kept: usize,
    gathered_any: bool,
    pruned_dropped: bool,
    ignore: Option<IgnoreChain>,
    list_never: bool,
    has_error: bool,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum Kind {
    Dir,
    File,
    Link,
}

pub struct SpecialPaths {
    pub entries: Vec<(regex::Regex, SpecialHandling)>,
}

#[derive(Debug, Clone, Copy, Default)]
pub struct SpecialHandling {
    pub show: Option<bool>,
    pub list: Option<bool>,
    pub sum: Option<bool>,
}

impl SpecialPaths {
    pub fn find(&self, path: &Path) -> SpecialHandling {
        let s = path.to_string_lossy();
        let mut h = SpecialHandling::default();
        for (rex, sh) in &self.entries {
            if rex.is_match(&s) {
                if sh.show.is_some() {
                    h.show = sh.show;
                }
                if sh.list.is_some() {
                    h.list = sh.list;
                }
                if sh.sum.is_some() {
                    h.sum = sh.sum;
                }
            }
        }
        h
    }
}

pub struct TreeBuilder<'a> {
    blines: Vec<BLine>,
    options: &'a TreeOptions,
    targeted_size: usize,
    ignorer: Ignorer,
    special: &'a SpecialPaths,
    pub nb_gitignored: usize,
    pub nb_hidden: usize,
    total_search: bool,
}

fn sort_key(name: &str) -> String {
    name.to_lowercase()
}

impl<'a> TreeBuilder<'a> {
    pub fn new(root: &Path, options: &'a TreeOptions, targeted_size: usize, special: &'a SpecialPaths) -> Self {
        let mut ignorer = Ignorer::new();
        let ignore = if options.respect_git_ignore { Some(ignorer.root_chain(root)) } else { None };
        let name = root.to_string_lossy().to_string();
        let md = fs::symlink_metadata(root);
        let kind = match &md {
            Ok(m) if m.is_dir() => Kind::Dir,
            Ok(m) if m.file_type().is_symlink() => {
                if fs::metadata(root).map(|m| m.is_dir()).unwrap_or(false) {
                    Kind::Dir
                } else {
                    Kind::Link
                }
            }
            _ => Kind::File,
        };
        let root_line = BLine {
            parent: None,
            path: root.to_path_buf(),
            subpath: String::new(),
            name,
            depth: 0,
            kind,
            children: None,
            next_child_idx: 0,
            has_match: true,
            direct_match: false,
            score: 10000,
            nb_kept: 0,
            gathered_any: false,
            pruned_dropped: false,
            ignore,
            list_never: false,
            has_error: false,
        };
        TreeBuilder {
            blines: vec![root_line],
            options,
            targeted_size: targeted_size.max(2),
            ignorer,
            special,
            nb_gitignored: 0,
            nb_hidden: 0,
            total_search: true,
        }
    }

    fn make_line(&mut self, parent: usize, path: PathBuf, name: String, depth: u16) -> Option<BLine> {
        let options = self.options;
        let special = self.special.find(&path);
        if special.show == Some(false) {
            return None;
        }
        if name.starts_with('.') && !options.show_hidden && special.show != Some(true) {
            self.nb_hidden += 1;
            return None;
        }
        let md = fs::symlink_metadata(&path).ok();
        let kind = match &md {
            Some(m) if m.is_dir() => Kind::Dir,
            Some(m) if m.file_type().is_symlink() => Kind::Link,
            _ => Kind::File,
        };
        if options.respect_git_ignore {
            if let Some(chain) = &self.blines[parent].ignore {
                if chain.is_ignored(&path, &name, kind == Kind::Dir) && special.show != Some(true) {
                    self.nb_gitignored += 1;
                    return None;
                }
            }
        }
        let parent_subpath = &self.blines[parent].subpath;
        let subpath = if parent_subpath.is_empty() { name.clone() } else { format!("{}/{}", parent_subpath, name) };
        let mut score = 10000 - depth as i32;
        let mut has_match = true;
        let mut direct_match = false;
        if options.pattern.is_some() {
            let cand = Candidate { name: &name, subpath: &subpath, path: &path, regular_file: kind == Kind::File };
            match options.pattern.score_of(&cand) {
                Some(s) => {
                    score += s + 10;
                    direct_match = true;
                }
                None => has_match = false,
            }
        }
        if kind != Kind::Dir {
            if !has_match {
                return None;
            }
            if options.only_folders {
                let is_dir_link = kind == Kind::Link && fs::metadata(&path).map(|m| m.is_dir()).unwrap_or(false);
                if !is_dir_link {
                    return None;
                }
            }
        }
        Some(BLine {
            parent: Some(parent),
            path,
            subpath,
            name,
            depth,
            kind,
            children: None,
            next_child_idx: 0,
            has_match,
            direct_match,
            score,
            nb_kept: 0,
            gathered_any: false,
            pruned_dropped: false,
            ignore: None,
            list_never: special.list == Some(false),
            has_error: false,
        })
    }

    /// load the children; return whether there's a child match
    fn load_children(&mut self, bid: usize) -> bool {
        if self.blines[bid].children.is_some() {
            return self.blines[bid]
                .children
                .as_ref()
                .unwrap()
                .iter()
                .any(|&c| self.blines[c].has_match);
        }
        let path = self.blines[bid].path.clone();
        let depth = self.blines[bid].depth + 1;
        let mut has_child_match = false;
        let mut children = Vec::new();
        // ignore chain for this dir
        if self.options.respect_git_ignore && self.blines[bid].ignore.is_none() {
            if let Some(pid) = self.blines[bid].parent {
                if let Some(pchain) = self.blines[pid].ignore.clone() {
                    let chain = self.ignorer.child_chain(&pchain, &path);
                    self.blines[bid].ignore = Some(chain);
                }
            }
        }
        match fs::read_dir(&path) {
            Ok(entries) => {
                let mut lines: Vec<BLine> = Vec::new();
                for e in entries.flatten() {
                    let name = e.file_name().to_string_lossy().to_string();
                    if let Some(l) = self.make_line(bid, e.path(), name, depth) {
                        lines.push(l);
                    }
                }
                lines.sort_by(|a, b| sort_key(&a.name).cmp(&sort_key(&b.name)));
                for l in lines {
                    if l.has_match {
                        has_child_match = true;
                    }
                    self.blines.push(l);
                    children.push(self.blines.len() - 1);
                }
                if self.options.pattern.has_real_scores() {
                    let bl = &self.blines;
                    children.sort_by(|&a, &b| bl[b].score.cmp(&bl[a].score));
                }
            }
            Err(_) => {
                self.blines[bid].has_error = true;
            }
        }
        self.blines[bid].children = Some(children);
        has_child_match
    }

    fn next_child(&mut self, bid: usize) -> Option<usize> {
        let b = &mut self.blines[bid];
        let children = b.children.as_ref()?;
        if b.next_child_idx < children.len() {
            let c = children[b.next_child_idx];
            b.next_child_idx += 1;
            b.gathered_any = true;
            Some(c)
        } else {
            None
        }
    }

    fn can_enter(&self, bid: usize) -> bool {
        let b = &self.blines[bid];
        if b.kind != Kind::Dir || b.list_never {
            return false;
        }
        if let Some(md) = self.options.max_depth {
            if b.depth >= md {
                return false;
            }
        }
        true
    }

    fn gather_lines(&mut self) -> Vec<usize> {
        let start = std::time::Instant::now();
        let has_pattern = self.options.pattern.is_some();
        let optimal_size = if self.options.pattern.has_real_scores() { 10 * self.targeted_size } else { self.targeted_size };
        let mut out = vec![0usize];
        let mut nb_lines_ok = 1;
        let mut open_dirs: VecDeque<usize> = VecDeque::new();
        let mut next_level: Vec<usize> = Vec::new();
        if self.blines[0].kind == Kind::Dir {
            self.load_children(0);
            open_dirs.push_back(0);
        }
        let complete_first_level = !self.options.trim_root || has_pattern;
        loop {
            let on_first_level = open_dirs.front().map(|&d| d == 0).unwrap_or(false);
            if !(complete_first_level && on_first_level && !has_pattern)
                && (nb_lines_ok > optimal_size
                    || (has_pattern && nb_lines_ok >= self.targeted_size && start.elapsed().as_millis() > 300))
            {
                self.total_search = false;
                break;
            }
            if let Some(dir) = open_dirs.pop_front() {
                if let Some(child) = self.next_child(dir) {
                    open_dirs.push_back(dir);
                    if self.blines[child].has_match {
                        nb_lines_ok += 1;
                    }
                    if self.can_enter(child) {
                        next_level.push(child);
                    }
                    out.push(child);
                }
            } else {
                if self.options.sort.prevent_deep_display() && !self.options.show_tree_for_sort() {
                    break;
                }
                if next_level.is_empty() {
                    break;
                }
                for &d in &next_level {
                    let has_child_match = self.load_children(d);
                    if has_child_match {
                        let mut id = d;
                        loop {
                            let b = &mut self.blines[id];
                            if !b.has_match {
                                b.has_match = true;
                                nb_lines_ok += 1;
                            }
                            match b.parent {
                                Some(p) => id = p,
                                None => break,
                            }
                        }
                    }
                    open_dirs.push_back(d);
                }
                next_level.clear();
            }
        }
        out
    }

    fn hasprune(&self, b: usize) -> bool {
        let bl = &self.blines[b];
        if bl.kind != Kind::Dir || bl.pruned_dropped || !bl.gathered_any {
            return false;
        }
        match &bl.children {
            Some(c) => c.len() > bl.next_child_idx,
            None => false,
        }
    }

    fn total(&self, out: &[usize]) -> usize {
        let mut n = 0;
        for &i in out {
            if self.blines[i].has_match {
                n += 1;
                if self.hasprune(i) {
                    n += 1;
                }
            }
        }
        n
    }

    fn removable(&self, i: usize, trim_root: bool) -> bool {
        let b = &self.blines[i];
        b.has_match && b.nb_kept == 0 && (b.depth > 1 || (trim_root && b.depth > 0))
    }

    fn remove(&mut self, i: usize) {
        self.blines[i].has_match = false;
        if let Some(p) = self.blines[i].parent {
            let pb = &mut self.blines[p];
            pb.nb_kept = pb.nb_kept.saturating_sub(1);
            pb.next_child_idx = pb.next_child_idx.saturating_sub(1);
        }
    }

    fn trim_excess(&mut self, out: &[usize]) {
        let target = self.targeted_size;
        let trim_root = self.options.trim_root && self.options.pattern.is_none() && !self.options.sort.prevent_deep_display();
        for &i in &out[1..] {
            if self.blines[i].has_match {
                if let Some(p) = self.blines[i].parent {
                    self.blines[p].nb_kept += 1;
                }
            }
        }
        if self.total(out) <= target {
            return;
        }
        let maxd = out.iter().map(|&i| self.blines[i].depth).max().unwrap_or(0);
        let mut depth = maxd;
        while depth > 0 {
            if self.total(out) <= target {
                break;
            }
            let level: Vec<usize> = out[1..].iter().copied().filter(|&i| self.blines[i].depth == depth).collect();
            if let Some(&first) = level.iter().find(|&&i| self.removable(i, trim_root)) {
                self.remove(first);
            }
            let mut parents: Vec<usize> = Vec::new();
            for &i in &level {
                if let Some(p) = self.blines[i].parent {
                    if !parents.contains(&p) {
                        parents.push(p);
                    }
                }
            }
            let mut progress = true;
            while self.total(out) > target && progress {
                progress = false;
                for &p in &parents {
                    if self.total(out) <= target {
                        break;
                    }
                    if !self.blines[p].has_match || !self.hasprune(p) {
                        continue;
                    }
                    let kept: Vec<usize> = self.blines[p]
                        .children
                        .as_ref()
                        .unwrap()
                        .iter()
                        .copied()
                        .filter(|&c| self.blines[c].has_match && self.blines[c].gathered_flag())
                        .collect();
                    if kept.is_empty() {
                        self.blines[p].pruned_dropped = true;
                        progress = true;
                        continue;
                    }
                    if self.blines[p].depth == 0 && kept.len() == 1 {
                        self.blines[p].pruned_dropped = true;
                        progress = true;
                        continue;
                    }
                    let kept: Vec<usize> = kept.into_iter().filter(|&c| self.removable(c, trim_root)).collect();
                    if let Some(&last) = kept.last() {
                        self.remove(last);
                        progress = true;
                    }
                }
            }
            depth -= 1;
        }
    }

    pub fn build(mut self, root_selected_path: Option<&Path>) -> Tree {
        let out = self.gather_lines();
        // mark gathered lines
        for &i in &out {
            self.blines[i].direct_match |= false;
        }
        let mut in_out = vec![false; self.blines.len()];
        for &i in &out {
            in_out[i] = true;
        }
        self.gathered = in_out;
        if self.options.pattern.is_none() {
            self.trim_excess(&out);
        }
        self.take(out, root_selected_path)
    }

    fn take(mut self, out: Vec<usize>, _sel: Option<&Path>) -> Tree {
        let options = self.options.clone();
        let mut lines: Vec<TreeLine> = Vec::new();
        // DFS over the bline tree, using only gathered & matching lines
        let mut stack: Vec<(usize, Vec<bool>)> = vec![(0, vec![])];
        let _ = &out;
        // we need to know the children in display (name) order
        while let Some((bid, branches)) = stack.pop() {
            if self.blines[bid].kind == Kind::Dir && self.blines[bid].children.is_none() && bid != 0 {
                self.load_children(bid);
            }
            let line = self.make_tree_line(bid, branches.clone());
            let is_dir = self.blines[bid].kind == Kind::Dir;
            lines.push(line);
            if !is_dir {
                continue;
            }
            let mut kids: Vec<usize> = self.blines[bid]
                .children
                .as_ref()
                .map(|c| c.iter().copied().filter(|&c| self.is_kept(c)).collect())
                .unwrap_or_default();
            kids.sort_by(|&a, &b| {
                let ka = sort_key(&self.blines[a].name);
                let kb = sort_key(&self.blines[b].name);
                ka.cmp(&kb).then(a.cmp(&b))
            });
            let prune = self.hasprune(bid) && self.blines[bid].has_match;
            if prune {
                // push a pruning pseudo line marker
                stack.push((usize::MAX - bid, branches.clone()));
            }
            for &k in kids.iter().rev() {
                stack.push((k, branches.clone()));
            }
            // pruning markers are handled below
            while let Some(&(top, _)) = stack.last() {
                if top > self.blines.len() && top != usize::MAX {
                    break;
                }
                break;
            }
            let _ = prune;
            // process pruning markers lazily
            loop {
                match stack.last() {
                    Some(&(top, _)) if top >= usize::MAX - self.blines.len() && top > self.blines.len() => {
                        // it's a pruning marker for a dir whose children are all processed
                        // only if it's directly on top (no remaining children)
                        let (_, br) = stack.pop().unwrap();
                        let dir = usize::MAX - top;
                        lines.push(self.make_pruning_line(dir, br));
                    }
                    _ => break,
                }
            }
        }
        let mut tree = Tree {
            lines,
            selection: 0,
            options,
            scroll: 0,
            total_search: self.total_search,
            nb_gitignored: self.nb_gitignored,
            nb_hidden: self.nb_hidden,
        };
        tree.after_lines_changed();
        tree
    }

    fn is_kept(&self, c: usize) -> bool {
        self.blines[c].has_match && self.gathered.get(c).copied().unwrap_or(false)
    }

    fn make_pruning_line(&self, dir: usize, _branches: Vec<bool>) -> TreeLine {
        let b = &self.blines[dir];
        let unlisted = b.children.as_ref().map(|c| c.len()).unwrap_or(0).saturating_sub(b.next_child_idx);
        TreeLine {
            bid: usize::MAX,
            parent_bid: Some(dir),
            left_branches: vec![],
            depth: b.depth + 1,
            path: b.path.clone(),
            subpath: String::new(),
            name: format!("{} unlisted", unlisted),
            line_type: LineType::Pruning,
            has_error: false,
            unlisted,
            score: 0,
            direct_match: false,
            is_exe: false,
            mode: 0,
            uid: 0,
            gid: 0,
            dev: 0,
            size: 0,
            blocks: 0,
            mtime: 0,
            sum: None,
            nb_kept_children: 0,
        }
    }

    fn make_tree_line(&self, bid: usize, branches: Vec<bool>) -> TreeLine {
        let b = &self.blines[bid];
        let md = fs::symlink_metadata(&b.path).ok();
        let mut line_type = match b.kind {
            Kind::Dir => LineType::Dir,
            Kind::File => LineType::File,
            Kind::Link => LineType::File,
        };
        let mut has_error = b.has_error;
        if let Some(m) = &md {
            if m.file_type().is_symlink() {
                match fs::read_link(&b.path) {
                    Ok(target) => {
                        let direct_target = target.to_string_lossy().to_string();
                        let parent = b.path.parent().unwrap_or(Path::new("/"));
