                            Err(_) => {
                                line_type = LineType::BrokenSymLink(normalize(&final_target).to_string_lossy().to_string());
                            }
                        }
                    }
                    Err(_) => has_error = true,
                }
            }
        } else {
            has_error = true;
        }
        let unlisted = if b.kind == Kind::Dir {
            b.children.as_ref().map(|c| c.len()).unwrap_or(0).saturating_sub(b.next_child_idx)
        } else {
            0
        };
        let (mode, uid, gid, dev, size, blocks, mtime) = match &md {
            Some(m) => (m.permissions().mode(), m.uid(), m.gid(), m.dev(), m.len(), m.blocks(), m.mtime()),
            None => (0, 0, 0, 0, 0, 0, 0),
        };
        let is_exe = matches!(line_type, LineType::File) && mode & 0o111 != 0;
        TreeLine {
            bid,
            parent_bid: b.parent,
            left_branches: branches,
            depth: b.depth,
            path: b.path.clone(),
            subpath: b.subpath.clone(),
            name: b.name.clone(),
            line_type,
            has_error,
            unlisted,
            score: b.score,
            direct_match: b.direct_match,
            is_exe,
            mode,
            uid,
            gid,
            dev,
            size,
            blocks,
            mtime,
            sum: None,
            nb_kept_children: b.nb_kept,
