//! Key representations (crokey-like)

use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};

/// format a key event the way broot shows it in help and uses in conf
pub fn format_key(k: &KeyEvent) -> String {
    let mut s = String::new();
    let mods = k.modifiers;
    let code_s = match k.code {
        KeyCode::Char(c) => {
            if c == ' ' {
                "Space".to_string()
            } else {
                c.to_string()
            }
        }
        KeyCode::Enter => "Enter".to_string(),
        KeyCode::Esc => "Esc".to_string(),
        KeyCode::Tab => "Tab".to_string(),
        KeyCode::BackTab => "BackTab".to_string(),
        KeyCode::Backspace => "Backspace".to_string(),
        KeyCode::Delete => "Delete".to_string(),
        KeyCode::Insert => "Insert".to_string(),
        KeyCode::Up => "Up".to_string(),
        KeyCode::Down => "Down".to_string(),
        KeyCode::Left => "Left".to_string(),
        KeyCode::Right => "Right".to_string(),
        KeyCode::Home => "Home".to_string(),
        KeyCode::End => "End".to_string(),
        KeyCode::PageUp => "PageUp".to_string(),
        KeyCode::PageDown => "PageDown".to_string(),
        KeyCode::F(n) => format!("F{}", n),
        _ => "?".to_string(),
    };
    if mods.contains(KeyModifiers::CONTROL) {
        s.push_str("ctrl-");
    }
    if mods.contains(KeyModifiers::ALT) {
        s.push_str("alt-");
    }
    if mods.contains(KeyModifiers::SHIFT) {
        match k.code {
            KeyCode::Char(_) => {}
            _ => s.push_str("shift-"),
        }
    }
    s.push_str(&code_s);
    s
}

/// normalize a key description from conf ("ctrl-E", "Alt-enter"...) to the internal format
pub fn normalize_key(desc: &str) -> Option<String> {
    let desc = desc.trim();
    if desc.is_empty() {
        return None;
    }
    let mut ctrl = false;
    let mut alt = false;
    let mut shift = false;
    let mut rest = desc;
    loop {
        let l = rest.to_lowercase();
        if l.starts_with("ctrl-") && rest.len() > 5 {
            ctrl = true;
            rest = &rest[5..];
        } else if l.starts_with("alt-") && rest.len() > 4 {
            alt = true;
            rest = &rest[4..];
        } else if l.starts_with("shift-") && rest.len() > 6 {
            shift = true;
            rest = &rest[6..];
        } else {
            break;
        }
    }
    let l = rest.to_lowercase();
    let code = match l.as_str() {
        "enter" | "ret" | "return" => "Enter".to_string(),
        "esc" | "escape" => "Esc".to_string(),
        "tab" => "Tab".to_string(),
        "backtab" => "BackTab".to_string(),
        "backspace" => "Backspace".to_string(),
        "del" | "delete" => "Delete".to_string(),
        "insert" | "ins" => "Insert".to_string(),
        "up" => "Up".to_string(),
        "down" => "Down".to_string(),
        "left" => "Left".to_string(),
        "right" => "Right".to_string(),
        "home" => "Home".to_string(),
        "end" => "End".to_string(),
        "pageup" => "PageUp".to_string(),
        "pagedown" => "PageDown".to_string(),
        "space" => "Space".to_string(),
        "hyphen" | "minus" => "-".to_string(),
        _ => {
            if (l.starts_with('f')) && l.len() > 1 && l[1..].chars().all(|c| c.is_ascii_digit()) {
                format!("F{}", &l[1..])
            } else if rest.chars().count() == 1 {
                let c = rest.chars().next().unwrap();
                if shift && c.is_alphabetic() {
                    shift = false;
                    c.to_uppercase().to_string()
                } else if c.is_uppercase() && !ctrl && !alt {
                    c.to_string()
                } else {
                    c.to_lowercase().to_string()
                }
            } else {
                return None;
            }
        }
    };
    let mut s = String::new();
    if ctrl {
        s.push_str("ctrl-");
    }
    if alt {
        s.push_str("alt-");
    }
    if shift {
        s.push_str("shift-");
    }
    s.push_str(&code);
    Some(s)
}

/// the key as matched against bindings
pub fn key_id(k: &KeyEvent) -> String {
    let mut k2 = *k;
    if let KeyCode::Char(c) = k.code {
        if k.modifiers.contains(KeyModifiers::CONTROL) || k.modifiers.contains(KeyModifiers::ALT) {
            k2.code = KeyCode::Char(c.to_ascii_lowercase());
            if c.is_ascii_uppercase() {
                k2.modifiers |= KeyModifiers::SHIFT;
            }
        }
    }
    let mut s = format_key(&k2);
    if let KeyCode::Char(c) = k2.code {
        if c.is_ascii_alphabetic() && k2.modifiers.contains(KeyModifiers::SHIFT)
            && (k2.modifiers.contains(KeyModifiers::CONTROL) || k2.modifiers.contains(KeyModifiers::ALT))
        {
            s = s.replace(&format!("-{}", c), &format!("-shift-{}", c));
        }
    }
    s
}
