        s.push_str("alt-");
    }
    if shift {
        s.push_str("shift-");
    }
    s.push_str(&code);
    Some(s)
}

/// the key as matched against bindings
pub fn key_id(k: &KeyEvent) -> String {
    let mut k2 = *k;
    if let KeyCode::Char(c) = k.code {
        if k.modifiers.contains(KeyModifiers::CONTROL) || k.modifiers.contains(KeyModifiers::ALT) {
            k2.code = KeyCode::Char(c.to_ascii_lowercase());
            if c.is_ascii_uppercase() {
                k2.modifiers |= KeyModifiers::SHIFT;
            }
        }
    }
    let mut s = format_key(&k2);
    if let KeyCode::Char(c) = k2.code {
        if c.is_ascii_alphabetic() && k2.modifiers.contains(KeyModifiers::SHIFT)
            && (k2.modifiers.contains(KeyModifiers::CONTROL) || k2.modifiers.contains(KeyModifiers::ALT))
        {
            s = s.replace(&format!("-{}", c), &format!("-shift-{}", c));
        }
    }
    s
}
