/// parse a verb definition from the conf
pub fn verb_from_conf(v: &Value) -> Result<Verb, String> {
    let gs = |k: &str| v.get(k).and_then(|x| x.as_string_lossy());
    let invocation = gs("invocation");
    let name_field = gs("name");
    let execution = gs("execution");
    let internal = gs("internal");
    let external = gs("external");
    let cmd = gs("cmd");
    let mut keys: Vec<String> = Vec::new();
    let mut keys_raw: Vec<String> = Vec::new();
    if let Some(k) = gs("key") {
        keys_raw.push(k.clone());
    }
    if let Some(Value::Array(arr)) = v.get("keys") {
        for k in arr {
            if let Some(s) = k.as_string_lossy() {
                keys_raw.push(s);
            }
        }
    }
    for k in &keys_raw {
        match normalize_key(k) {
            Some(n) => keys.push(n),
            None => return Err(format!("Invalid key: {:?}", k)),
        }
    }
    let exec = if let Some(i) = internal {
        parse_internal(&i)
    } else if let Some(e) = external {
        Execution::External(e)
    } else if let Some(c) = cmd {
        Execution::Sequence(c)
    } else if let Some(e) = execution {
        if e.starts_with(':') || e.starts_with(' ') {
            parse_internal(&e)
        } else {
            Execution::External(e)
        }
    } else {
        return Err("Invalid verb conf: missing execution".to_string());
    };
    let (inv_name, inv_args) = match &invocation {
        Some(inv) => {
            let inv = inv.trim();
            match inv.find(' ') {
                Some(i) => (Some(inv[..i].to_string()), Some(inv[i + 1..].trim().to_string())),
                None => (Some(inv.to_string()), None),
            }
        }
        None => (None, None),
    };
    let name = name_field.clone().or(inv_name.clone()).unwrap_or_else(|| match &exec {
        Execution::Internal(n, _) => n.clone(),
        _ => String::new(),
    });
    let apply_to = match gs("apply_to").as_deref() {
        Some("file") => ApplyTo::File,
        Some("text_file") => ApplyTo::TextFile,
        Some("binary_file") => ApplyTo::BinaryFile,
        Some("directory") => ApplyTo::Directory,
        _ => ApplyTo::Any,
    };
    let leave_broot = v.get("leave_broot").and_then(|b| b.as_bool()).unwrap_or(!matches!(exec, Execution::Internal(_, _)));
    let description = match gs("description") {
        Some(d) => d,
        None => match &exec {
            Execution::External(e) => e.clone(),
            Execution::Sequence(c) => c.clone(),
            Execution::Internal(n, a) => match a {
                Some(a) => format!(":{} {}", n, a),
                None => format!(":{}", n),
            },
        },
    };
    let mut verb = Verb {
        name: inv_name.clone().unwrap_or(name.clone()),
        shortcut: gs("shortcut"),
        keys,
        keys_desc: keys_raw.join(", "),
        description,
        invocation_args: inv_args,
        execution: exec,
        apply_to,
        leave_broot,
        auto_exec: v.get("auto_exec").and_then(|b| b.as_bool()).unwrap_or(true),
        from_shell: v.get("from_shell").and_then(|b| b.as_bool()).unwrap_or(false),
        set_working_dir: v.get("set_working_dir").and_then(|b| b.as_bool()).unwrap_or(false),
        from_conf: true,
        panels: vec![],
    };
    if let Some(n) = name_field {
        if invocation.is_none() {
            verb.name = n;
        }
    }
    Ok(verb)
}

fn parse_internal(s: &str) -> Execution {
    let s = s.trim().trim_start_matches(':').trim();
    match s.find(' ') {
        Some(i) => Execution::Internal(s[..i].to_string(), Some(s[i + 1..].trim().to_string())),
        None => Execution::Internal(s.to_string(), None),
    }
}

pub struct VerbStore {
    pub verbs: Vec<Verb>,
}

pub enum VerbSearch<'a> {
    None,
    Exact(&'a Verb),
    Unique(&'a Verb),
    Several(Vec<&'a str>),
}

impl VerbStore {
    pub fn new(conf_verbs: Vec<Verb>) -> Self {
        let mut verbs = conf_verbs;
        // a conf verb with the same name as a builtin with only a key definition
        // replaces the builtin's key binding
        verbs.extend(builtin_verbs());
        VerbStore { verbs }
    }
    pub fn search(&self, prefix: &str) -> VerbSearch<'_> {
        // exact match first
        for v in &self.verbs {
            if v.name == prefix || v.shortcut.as_deref() == Some(prefix) {
                return VerbSearch::Exact(v);
            }
        }
        let mut found: Vec<&Verb> = Vec::new();
        let mut names: Vec<&str> = Vec::new();
        for v in &self.verbs {
            let mut m = false;
            for n in v.names() {
                if n.starts_with(prefix) {
                    names.push(n);
                    m = true;
                }
            }
            if m {
                found.push(v);
            }
        }
        match found.len() {
            0 => VerbSearch::None,
            1 => VerbSearch::Unique(found[0]),
            _ => VerbSearch::Several(names),
        }
    }
    pub fn find_by_name(&self, name: &str) -> Vec<&Verb> {
        self.verbs.iter().filter(|v| v.name == name || v.shortcut.as_deref() == Some(name)).collect()
    }
    pub fn internal(&self, name: &str) -> Option<&Verb> {
        self.verbs.iter().find(|v| !v.from_conf && v.name == name)
    }
}
