                        Some("never") => Some(false),
                        _ => None,
                    }
                };
                if let Value::String(s) = sv {
                    match s.as_str() {
                        "hide" => h.show = Some(false),
                        "no-enter" | "no-list" => h.list = Some(false),
                        "enter" => h.list = Some(true),
                        _ => {}
                    }
                } else {
                    h.show = parse_b("show");
                    h.list = parse_b("list");
                    h.sum = parse_b("sum");
                }
                self.special_paths.push((k.clone(), h));
            }
        }
        if let Some(Value::Object(o)) = v.get("search_modes") {
            for (k, mv) in o {
                if let Some(m) = mv.as_string_lossy() {
                    self.search_modes.push((k.clone(), m));
                }
            }
        }
        if let Some(Value::Object(o)) = v.get("ext_colors") {
            for (k, c) in o {
                if let Some(c) = c.as_string_lossy() {
                    self.ext_colors.push((k.clone(), c));
                }
            }
        }
        if let Some(Value::Object(o)) = v.get("skin") {
            for (k, sv) in o {
                if let Some(s) = sv.as_string_lossy() {
                    self.skin.insert(k.clone(), s);
                }
            }
        }
        if let Some(Value::Array(a)) = v.get("verbs") {
            for vv in a {
                match verb_from_conf(vv) {
                    Ok(verb) => self.verbs.push(verb),
                    Err(e) => self.verb_errors.push(e),
                }
            }
        }
        if let Some(Value::Array(a)) = v.get("imports") {
            let base = path.parent().unwrap_or(Path::new("."));
            for imp in a {
                let (file, ok) = match imp {
                    Value::String(s) => (Some(s.clone()), true),
                    Value::Object(_) => {
                        let file = imp.get("file").and_then(|x| x.as_string_lossy());
                        let ok = match imp.get("luma") {
                            None => true,
                            Some(Value::String(l)) => luma_matches(l, luma),
                            Some(Value::Array(ls)) => ls.iter().any(|l| l.as_str().map(|l| luma_matches(l, luma)).unwrap_or(false)),
                            _ => true,
                        };
                        (file, ok)
                    }
                    _ => (None, false),
                };
                if let (Some(f), true) = (file, ok) {
                    let p = expand_tilde(&f);
                    let p = if p.is_absolute() { p } else { base.join(p) };
                    if p.exists() {
                        self.read_file(&p, luma, depth + 1)?;
                    }
                }
            }
        }
        Ok(())
    }

    pub fn special_paths(&self) -> SpecialPaths {
        let mut entries = Vec::new();
        for (glob, h) in &self.special_paths {
            let g = if glob.starts_with('~') { expand_tilde(glob).to_string_lossy().to_string() } else { glob.clone() };
            let g = if g.starts_with('/') { g } else { format!("**/{}", g) };
            let re = glob_to_regex(&g);
            if let Ok(r) = regex::Regex::new(&re) {
                entries.push((r, *h));
            }
        }
        SpecialPaths { entries }
    }

    pub fn search_mode_map(&self) -> SearchModeMap {
        let mut map = SearchModeMap::default();
        for (k, m) in &self.search_modes {
            if let Some(mode) = parse_search_mode(m) {
                let key = if k == "<empty>" {
                    None
                } else if k == "/" {
                    Some(String::new())
                } else {
                    Some(k.trim_end_matches('/').to_string())
                };
                map.set(key, mode);
            }
        }
        map
    }
}

fn parse_search_mode(s: &str) -> Option<SearchMode> {
    let mut object = None;
    let mut kind = None;
    for w in s.split_whitespace() {
        match w {
            "fuzzy" => kind = Some(SearchKind::Fuzzy),
            "exact" => kind = Some(SearchKind::Exact),
            "regex" => kind = Some(SearchKind::Regex),
            "tokens" => kind = Some(SearchKind::Tokens),
            "name" => object = Some(SearchObject::Name),
            "path" => object = Some(SearchObject::Path),
            "content" => object = Some(SearchObject::Content),
            _ => return None,
        }
    }
    Some(SearchMode::new(object.unwrap_or(SearchObject::Path), kind.unwrap_or(SearchKind::Fuzzy)))
}

fn luma_matches(l: &str, luma: &Luma) -> bool {
    matches!(
        (l, luma),
        ("dark", Luma::Dark) | ("light", Luma::Light) | ("unknown", Luma::Unknown)
    )
}

fn glob_to_regex(g: &str) -> String {
    let mut re = String::from("^");
    let chars: Vec<char> = g.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '*' {
            if i + 1 < chars.len() && chars[i + 1] == '*' {
                if i + 2 < chars.len() && chars[i + 2] == '/' {
                    re.push_str("(?:.*/)?");
                    i += 3;
                } else {
                    re.push_str(".*");
                    i += 2;
                }
                continue;
            }
            re.push_str("[^/]*");
        } else if c == '?' {
            re.push_str("[^/]");
        } else {
            re.push_str(&regex::escape(&c.to_string()));
        }
        i += 1;
    }
    re.push('$');
    re
}
