//! A minimal TOML parser producing hjson Values

use crate::hjson::Value;

fn set_path(root: &mut Value, path: &[String], key: &str, v: Value) {
    let mut cur = root;
    for p in path {
        let obj = match cur {
            Value::Object(o) => o,
            _ => return,
        };
        let idx = match obj.iter().position(|(k, _)| k == p) {
            Some(i) => i,
            None => {
                obj.push((p.clone(), Value::Object(vec![])));
                obj.len() - 1
            }
        };
        cur = &mut obj[idx].1;
        if let Value::Array(a) = cur {
            if a.is_empty() {
                a.push(Value::Object(vec![]));
            }
            cur = a.last_mut().unwrap();
        }
    }
    if let Value::Object(o) = cur {
        o.push((key.to_string(), v));
    }
}

fn parse_value(s: &str) -> Result<Value, String> {
    let s = s.trim();
    if s.starts_with('"') || s.starts_with('\'') {
        let q = s.chars().next().unwrap();
        let inner = &s[1..];
        let end = inner.find(q).ok_or("unterminated string")?;
        let raw = &inner[..end];
        let out = if q == '"' { raw.replace("\\\\", "\\").replace("\\\"", "\"").replace("\\n", "\n") } else { raw.to_string() };
        return Ok(Value::String(out));
    }
    if s.starts_with('[') {
        let inner = s.trim_start_matches('[').trim_end_matches(']');
        let mut items = Vec::new();
        for part in split_top(inner) {
            let p = part.trim();
            if !p.is_empty() {
                items.push(parse_value(p)?);
            }
        }
        return Ok(Value::Array(items));
    }
    if s.starts_with('{') {
        let inner = s.trim_start_matches('{').trim_end_matches('}');
        let mut obj = Vec::new();
        for part in split_top(inner) {
            if let Some(i) = part.find('=') {
                let k = part[..i].trim().trim_matches('"').to_string();
                obj.push((k, parse_value(&part[i + 1..])?));
            }
        }
        return Ok(Value::Object(obj));
    }
    match s {
        "true" => return Ok(Value::Bool(true)),
        "false" => return Ok(Value::Bool(false)),
        _ => {}
    }
    if let Ok(n) = s.parse::<f64>() {
        return Ok(Value::Number(n));
    }
    Ok(Value::String(s.to_string()))
}

fn split_top(s: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut cur = String::new();
    let mut depth = 0;
    let mut in_str: Option<char> = None;
    for c in s.chars() {
        if let Some(q) = in_str {
            cur.push(c);
            if c == q {
                in_str = None;
            }
            continue;
        }
        match c {
            '"' | '\'' => {
                in_str = Some(c);
                cur.push(c);
            }
            '[' | '{' => {
                depth += 1;
                cur.push(c);
            }
            ']' | '}' => {
                depth -= 1;
                cur.push(c);
            }
            ',' if depth == 0 => parts.push(std::mem::take(&mut cur)),
            _ => cur.push(c),
        }
    }
    if !cur.trim().is_empty() {
        parts.push(cur);
    }
    parts
}

fn strip_comment(line: &str) -> &str {
    let mut in_str: Option<char> = None;
    for (i, c) in line.char_indices() {
        if let Some(q) = in_str {
            if c == q {
                in_str = None;
            }
            continue;
        }
        if c == '"' || c == '\'' {
            in_str = Some(c);
        } else if c == '#' {
            return &line[..i];
        }
    }
    line
}

pub fn parse(src: &str) -> Result<Value, String> {
    let mut root = Value::Object(vec![]);
    let mut path: Vec<String> = Vec::new();
    for raw in src.lines() {
        let line = strip_comment(raw).trim();
        if line.is_empty() {
            continue;
        }
        if line.starts_with("[[") {
            let name = line.trim_start_matches("[[").trim_end_matches("]]").trim().to_string();
            // append a new object to the array
            let mut parts: Vec<String> = name.split('.').map(|s| s.trim().to_string()).collect();
            let last = parts.pop().unwrap();
            let mut cur = &mut root;
            for p in &parts {
                let obj = match cur {
                    Value::Object(o) => o,
                    _ => return Err("bad table".into()),
                };
                let idx = match obj.iter().position(|(k, _)| k == p) {
                    Some(i) => i,
                    None => {
                        obj.push((p.clone(), Value::Object(vec![])));
                        obj.len() - 1
                    }
                };
                cur = &mut obj[idx].1;
            }
            if let Value::Object(o) = cur {
                match o.iter().position(|(k, _)| *k == last) {
                    Some(i) => {
                        if let Value::Array(a) = &mut o[i].1 {
                            a.push(Value::Object(vec![]));
                        }
                    }
                    None => o.push((last.clone(), Value::Array(vec![Value::Object(vec![])]))),
                }
            }
            parts.push(last);
            path = parts;
            continue;
        }
        if line.starts_with('[') {
            let name = line.trim_start_matches('[').trim_end_matches(']').trim().to_string();
            path = name.split('.').map(|s| s.trim().trim_matches('"').to_string()).collect();
            continue;
        }
        if let Some(i) = line.find('=') {
            let key = line[..i].trim().trim_matches('"').to_string();
            let v = parse_value(&line[i + 1..])?;
            set_path(&mut root, &path, &key, v);
        }
    }
    Ok(root)
}
