    if let Some(d) = std::env::var_os("BROOT_CONFIG_DIR") {
        return PathBuf::from(d);
    }
    if let Some(x) = std::env::var_os("XDG_CONFIG_HOME") {
        let p = PathBuf::from(x);
        if p.is_absolute() {
            return p.join("broot");
        }
    }
    home_dir().join(".config").join("broot")
}

pub fn data_dir() -> PathBuf {
