    let dir = config_dir();
    let toml = dir.join("conf.toml");
    if toml.exists() {
        return toml;
    }
    dir.join("conf.hjson")
}

/// write the default configuration files in the given directory (without overwriting)
pub fn write_default_conf_in(dir: &Path) -> std::io::Result<bool> {
    std::fs::create_dir_all(dir)?;
    let mut written = false;
    let mut w = |p: PathBuf, content: &str| -> std::io::Result<()> {
        if !p.exists() {
            if let Some(parent) = p.parent() {
                std::fs::create_dir_all(parent)?;
            }
            std::fs::write(&p, content)?;
            written = true;
        }
        Ok(())
    };
    w(dir.join("conf.hjson"), DEFAULT_CONF)?;
    w(dir.join("verbs.hjson"), DEFAULT_VERBS)?;
    for (name, content) in SKINS {
        w(dir.join("skins").join(name), content)?;
    }
    Ok(written)
}

pub fn expand_tilde(s: &str) -> PathBuf {
    if s == "~" {
        return home_dir();
    }
    if let Some(r) = s.strip_prefix("~/") {
        return home_dir().join(r);
    }
    PathBuf::from(s)
}

fn parse_size(s: &str) -> Option<u64> {
    let s = s.trim();
    let digits: String = s.chars().take_while(|c| c.is_ascii_digit() || *c == '.').collect();
    let unit = s[digits.len()..].trim().to_lowercase();
    let n: f64 = digits.parse().ok()?;
    let m: f64 = match unit.as_str() {
        "" | "b" => 1.0,
        "k" | "kb" => 1e3,
        "m" | "mb" => 1e6,
        "g" | "gb" => 1e9,
        "t" | "tb" => 1e12,
        "kib" | "ki" => 1024.0,
        "mib" | "mi" => 1024.0 * 1024.0,
        "gib" | "gi" => 1024.0 * 1024.0 * 1024.0,
        _ => return None,
    };
    Some((n * m) as u64)
}

