            "tokens" => kind = Some(SearchKind::Tokens),
            "name" => object = Some(SearchObject::Name),
            "path" => object = Some(SearchObject::Path),
            "content" => object = Some(SearchObject::Content),
            _ => return None,
        }
    }
    Some(SearchMode::new(object.unwrap_or(SearchObject::Path), kind.unwrap_or(SearchKind::Fuzzy)))
}

fn luma_matches(l: &str, luma: &Luma) -> bool {
    matches!(
        (l, luma),
        ("dark", Luma::Dark) | ("light", Luma::Light) | ("unknown", Luma::Unknown)
    )
}

fn glob_to_regex(g: &str) -> String {
    let mut re = String::from("^");
    let chars: Vec<char> = g.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '*' {
            if i + 1 < chars.len() && chars[i + 1] == '*' {
                if i + 2 < chars.len() && chars[i + 2] == '/' {
                    re.push_str("(?:.*/)?");
                    i += 3;
                } else {
                    re.push_str(".*");
                    i += 2;
                }
                continue;
            }
            re.push_str("[^/]*");
        } else if c == '?' {
            re.push_str("[^/]");
        } else {
            re.push_str(&regex::escape(&c.to_string()));
        }
        i += 1;
    }
    re.push('$');
    re
}
