//! Drawing of trees

use crate::pattern::{InputPattern, SearchObject};
use crate::screen::{str_width, Screen};
use crate::skin::StyleMap;
use crate::style::Style;
use crate::tree::{LineType, Tree, TreeLine};

pub struct Area {
    pub left: usize,
    pub top: usize,
    pub width: usize,
    pub height: usize,
}

/// compute the scrollbar (top, bottom inclusive), if any
pub fn compute_scrollbar(scroll: usize, content_height: usize, available_height: usize, top: usize) -> Option<(usize, usize)> {
    if content_height <= available_height || available_height < 3 {
        return None;
    }
    let mut track_before = scroll * available_height / content_height;
    if track_before == 0 && scroll > 0 {
        track_before = 1;
    }
    let thumb_height = (available_height * available_height / content_height).max(1);
    let mut start = top + track_before;
    let mut end = start + thumb_height;
    let bottom = top + available_height - 1;
    if end > bottom {
        end = bottom;
        if start > end {
            start = end;
        }
    }
    if scroll + available_height >= content_height {
        // at the end
        let shift = bottom - end;
        start += shift;
        end += shift;
    }
    Some((start, end))
}

pub fn format_date(ts: i64, fmt: &str) -> String {
    unsafe {
        let t: libc::time_t = ts as libc::time_t;
        let mut tm: libc::tm = std::mem::zeroed();
        libc::localtime_r(&t, &mut tm);
        let cfmt = std::ffi::CString::new(fmt).unwrap();
        let mut buf = [0u8; 256];
        let n = libc::strftime(buf.as_mut_ptr() as *mut libc::c_char, buf.len(), cfmt.as_ptr(), &tm);
        String::from_utf8_lossy(&buf[..n]).to_string()
    }
}

pub fn file_size_4(size: u64) -> String {
    // 4 chars max
    const UNITS: &[&str] = &["", "K", "M", "G", "T", "P"];
    let mut v = size as f64;
    let mut i = 0;
    while v >= 1000.0 && i < UNITS.len() - 1 {
        v /= 1000.0;
        i += 1;
    }
    if i == 0 {
        format!("{}", size)
    } else if v < 10.0 {
        format!("{:.1}{}", v, UNITS[i])
    } else {
        format!("{:.0}{}", v, UNITS[i])
    }
}

pub fn mode_string(mode: u32) -> String {
    let mut s = String::new();
    let bits = [(0o400, 'r'), (0o200, 'w'), (0o100, 'x'), (0o040, 'r'), (0o020, 'w'), (0o010, 'x'), (0o004, 'r'), (0o002, 'w'), (0o001, 'x')];
    for (b, c) in bits {
        s.push(if mode & b != 0 { c } else { '_' });
    }
    s
}

pub fn user_name(uid: u32) -> String {
    unsafe {
        let pw = libc::getpwuid(uid);
        if pw.is_null() {
            return uid.to_string();
        }
        std::ffi::CStr::from_ptr((*pw).pw_name).to_string_lossy().to_string()
    }
}

pub fn group_name(gid: u32) -> String {
    unsafe {
        let gr = libc::getgrgid(gid);
        if gr.is_null() {
            return gid.to_string();
        }
        std::ffi::CStr::from_ptr((*gr).gr_name).to_string_lossy().to_string()
    }
}

pub struct DisplayCtx<'a> {
    pub skin: &'a StyleMap,
    pub show_selection_mark: bool,
    pub in_app: bool,
    pub focused: bool,
    pub date_time_format: &'a str,
}

fn name_style(line: &TreeLine, skin: &StyleMap) -> Style {
    match &line.line_type {
        LineType::Dir => skin.directory,
        LineType::File => {
            if line.is_exe {
                skin.exe
            } else {
                skin.file
            }
        }
        LineType::SymLink { .. } | LineType::BrokenSymLink(_) => skin.link,
        LineType::Pruning => skin.pruning,
    }
}

/// write a string with the matching chars highlighted
fn write_matched(
    screen: &mut Screen,
    x: usize,
    y: usize,
    s: &str,
    base: Style,
    match_style: Style,
    positions: &[usize],
    char_offset: usize,
    max_x: usize,
) -> usize {
    let mut x = x;
    for (i, c) in s.chars().enumerate() {
        let st = if positions.contains(&(i + char_offset)) { base.overlaid(&match_style) } else { base };
        let w = crate::screen::char_width(c);
        if x + w > max_x {
            return max_x.min(x);
        }
        x += screen.set(x, y, c, st);
    }
    x
}

fn with_bg(s: Style, bg: Option<crate::style::Color>) -> Style {
    let mut s = s;
    if bg.is_some() {
        s.bg = bg;
    }
    s
}

pub struct Columns {
    pub size_w: usize,
    pub count_w: usize,
    pub owner_w: usize,
    pub group_w: usize,
}

pub fn compute_columns(tree: &Tree) -> Columns {
    let mut owner_w = 0;
    let mut group_w = 0;
    let mut count_w = 1;
    if tree.options.show_permissions {
        for l in tree.lines.iter().skip(1) {
            if l.is_selectable() {
                owner_w = owner_w.max(str_width(&user_name(l.uid)));
                group_w = group_w.max(str_width(&group_name(l.gid)));
            }
        }
    }
    if tree.options.show_counts {
        for l in tree.lines.iter() {
            if let Some(s) = &l.sum {
                count_w = count_w.max(s.count.to_string().len());
            }
        }
    }
    Columns { size_w: 4, count_w, owner_w, group_w }
}

pub fn draw_tree(screen: &mut Screen, tree: &Tree, area: &Area, ctx: &DisplayCtx, pattern: &InputPattern) {
    let skin = ctx.skin;
    let page_height = area.height;
    let scrollbar = compute_scrollbar(tree.scroll, tree.lines.len().saturating_sub(1), page_height.saturating_sub(1), area.top + 1);
    let width = if scrollbar.is_some() { area.width - 1 } else { area.width };
    let max_x = area.left + width;
    let cols = compute_columns(tree);
    let path_search = pattern.is_path_search();
    let atom = pattern.first_atom();
    for row in 0..page_height {
        let y = area.top + row;
        let idx = if row == 0 { 0 } else { tree.scroll + row };
        let mut x = area.left;
        if idx >= tree.lines.len() {
            screen.fill(area.left, y, area.left + area.width, skin.default.with_bg(None).with_fg(skin.default.fg));
            continue;
        }
        let line = &tree.lines[idx];
        let selected = ctx.in_app && idx == tree.selection;
        let bg = if selected { skin.selected_line.bg } else { None };
        let fill_style = with_bg(Style { fg: skin.default.fg, bg: None, attrs: Default::default() }, bg);
        if idx > 0 {
            if ctx.show_selection_mark && ctx.in_app {
                let mark = if selected { '▶' } else { ' ' };
                x += screen.set(x, y, mark, fill_style);
            } else {
                x += screen.set(x, y, ' ', fill_style);
            }
        }
        // optional columns
        if line.is_selectable() {
            if tree.options.show_sizes {
                let s = match &line.sum {
                    Some(sum) => file_size_4(sum.size),
                    None => String::new(),
                };
                let st = with_bg(skin.default, bg);
                let txt = format!("{:>4}", s);
                x = screen.write_str(x, y, &txt, st, max_x);
                x = screen.write_str(x, y, " ", fill_style, max_x);
            }
            if tree.options.show_permissions && idx > 0 {
                let ms = mode_string(line.mode);
                for c in ms.chars() {
                    let st = match c {
                        'r' => skin.perm_r,
                        'w' => skin.perm_w,
                        'x' => skin.perm_x,
                        _ => skin.perm__,
                    };
                    x += screen.set(x, y, c, with_bg(st, bg));
                }
                x = screen.write_str(x, y, " ", fill_style, max_x);
                let owner = format!("{:<w$}", user_name(line.uid), w = cols.owner_w);
                x = screen.write_str(x, y, &owner, with_bg(skin.owner, bg), max_x);
                x = screen.write_str(x, y, " ", fill_style, max_x);
                let group = format!("{:<w$}", group_name(line.gid), w = cols.group_w);
                x = screen.write_str(x, y, &group, with_bg(skin.group, bg), max_x);
                x = screen.write_str(x, y, " ", fill_style, max_x);
            }
            if tree.options.show_dates && idx > 0 {
                let ts = line.sum.map(|s| s.modified).unwrap_or(line.mtime);
                let d = format_date(ts, ctx.date_time_format);
                x = screen.write_str(x, y, &d, with_bg(skin.dates, bg), max_x);
                x = screen.write_str(x, y, " ", fill_style, max_x);
            }
            if tree.options.show_counts && idx > 0 {
                let c = line.sum.map(|s| s.count).unwrap_or(1);
                let txt = format!("{:>w$}", c, w = cols.count_w);
                x = screen.write_str(x, y, &txt, with_bg(skin.count, bg), max_x);
                x = screen.write_str(x, y, " ", fill_style, max_x);
            }
        } else if idx > 0 {
            // pruning line: blank columns
            let mut w = 0;
            if tree.options.show_sizes {
                w += 5;
            }
            if tree.options.show_permissions {
                w += 10 + cols.owner_w + 1 + cols.group_w + 1;
            }
            if tree.options.show_dates {
                w += str_width(&format_date(0, ctx.date_time_format)) + 1;
            }
            if tree.options.show_counts {
                w += cols.count_w + 1;
            }
            x = screen.fill(x, y, (x + w).min(max_x), fill_style);
        }
        // branches
        if idx > 0 {
            let depth = line.depth as usize;
            let tree_st = with_bg(skin.tree, bg);
            for d in 0..depth.saturating_sub(1) {
                let s = if line.left_branches.get(d).copied().unwrap_or(false) { "│  " } else { "   " };
                x = screen.write_str(x, y, s, tree_st, max_x);
            }
            let last = if tree.has_branch_continuation(idx) { "├──" } else { "└──" };
            x = screen.write_str(x, y, last, tree_st, max_x);
        }
        // name
        let nst = with_bg(name_style(line, skin), bg);
        let match_st = skin.char_match;
        match &line.line_type {
            LineType::Pruning => {
                x = screen.write_str(x, y, &line.name, nst, max_x);
            }
            _ => {
                if idx == 0 {
                    x = screen.write_str(x, y, &line.path.to_string_lossy(), nst, max_x);
                } else if line.direct_match && atom.is_some() {
                    let a = atom.unwrap();
                    if path_search {
                        let m = a.find_str(&line.subpath);
                        let pos = m.map(|m| m.pos).unwrap_or_default();
                        let name_start = line.subpath.chars().count() - line.name.chars().count();
                        let parent_part: String = line.subpath.chars().take(name_start).collect();
                        x = write_matched(screen, x, y, &parent_part, with_bg(skin.parent, bg), match_st, &pos, 0, max_x);
                        x = write_matched(screen, x, y, &line.name, nst, match_st, &pos, name_start, max_x);
                    } else if a.object() == SearchObject::Name {
                        let m = a.find_str(&line.name);
                        let pos = m.map(|m| m.pos).unwrap_or_default();
                        x = write_matched(screen, x, y, &line.name, nst, match_st, &pos, 0, max_x);
                    } else {
                        x = screen.write_str(x, y, &line.name, nst, max_x);
                    }
                } else {
                    x = screen.write_str(x, y, &line.name, nst, max_x);
                }
                match &line.line_type {
                    LineType::Dir => {
                        if line.unlisted > 0 && !has_pruning_child(tree, idx) && idx > 0 {
                            x = screen.write_str(x, y, " …", nst, max_x);
                        }
                    }
                    LineType::SymLink { final_is_dir, final_target, .. } => {
                        x = screen.write_str(x, y, " -> ", with_bg(skin.link, bg), max_x);
                        let tst = if *final_is_dir { skin.directory } else { skin.file };
                        x = screen.write_str(x, y, &final_target.to_string_lossy(), with_bg(tst, bg), max_x);
                    }
                    LineType::BrokenSymLink(t) => {
                        x = screen.write_str(x, y, " -> ", with_bg(skin.link, bg), max_x);
                        x = screen.write_str(x, y, t, with_bg(skin.file_error, bg), max_x);
                    }
                    _ => {}
                }
            }
        }
        screen.fill(x, y, max_x, fill_style);
        if let Some((sb_top, sb_bottom)) = scrollbar {
            if row > 0 {
                let st = if y >= sb_top && y <= sb_bottom { skin.scrollbar_thumb } else { skin.scrollbar_track };
                screen.set(area.left + area.width - 1, y, '▐', st);
            } else {
                screen.set(area.left + area.width - 1, y, ' ', fill_style);
            }
        }
    }
}

fn has_pruning_child(tree: &Tree, idx: usize) -> bool {
    let depth = tree.lines[idx].depth;
    for l in tree.lines.iter().skip(idx + 1) {
        if l.depth <= depth {
            return false;
        }
        if l.depth == depth + 1 && matches!(l.line_type, LineType::Pruning) {
            return true;
        }
    }
    false
}
