/// A piece of styled text, after fitting
#[derive(Debug, Clone)]
pub struct Piece {
    pub text: String,
    pub style: Style,
}

fn shorten_token(tok: &str, target: usize) -> String {
    // target >= 3 ; keeps the start and the end
    let chars: Vec<char> = tok.chars().collect();
    let keep = target - 1;
    let left = (keep + 1) / 2;
    let right = keep - left;
    let mut s: String = chars[..left].iter().collect();
    s.push('…');
    s.extend(chars[chars.len() - right..].iter());
    s
}

/// fit compounds in a width by shortening the longest tokens, then truncating
pub fn fit(compounds: &[Compound], width: usize, skin: &MdSkin) -> Vec<Piece> {
    // split into tokens: (text, kind, is_space)
    #[derive(Clone)]
    struct Tok {
        text: String,
        kind: Kind,
        ellipsis_at: Option<usize>,
    }
    let mut toks: Vec<Tok> = Vec::new();
    for c in compounds {
        let mut cur = String::new();
        let mut cur_space: Option<bool> = None;
        for ch in c.text.chars() {
            let is_space = ch == ' ';
            if cur_space.is_some() && cur_space != Some(is_space) {
                toks.push(Tok { text: std::mem::take(&mut cur), kind: c.kind, ellipsis_at: None });
            }
            cur_space = Some(is_space);
            cur.push(ch);
        }
        if !cur.is_empty() {
            toks.push(Tok { text: cur, kind: c.kind, ellipsis_at: None });
        }
    }
    let total: usize = toks.iter().map(|t| str_width(&t.text)).sum();
    if total > width {
        let mut excess = total - width;
        // indices of non space tokens sorted by decreasing length, ties: last first
        let mut idxs: Vec<usize> = (0..toks.len()).filter(|&i| !toks[i].text.starts_with(' ')).collect();
        idxs.sort_by(|&a, &b| {
            let la = toks[a].text.chars().count();
            let lb = toks[b].text.chars().count();
            lb.cmp(&la).then(b.cmp(&a))
        });
        for i in idxs {
            if excess == 0 {
                break;
            }
            let len = toks[i].text.chars().count();
            if len <= 3 {
                break;
            }
            let possible = len - 3;
            let r = possible.min(excess);
            let target = len - r;
            let short = shorten_token(&toks[i].text, target);
            let pos = short.chars().position(|c| c == '…');
            toks[i].text = short;
            toks[i].ellipsis_at = pos;
            excess -= r;
        }
        let mut pieces = Vec::new();
        let mut w = 0;
        let mut truncated = excess > 0;
        for t in &toks {
            let st = skin.style(t.kind);
            let tw = str_width(&t.text);
            if truncated && w + tw >= width {
                // cut here
                let room = width.saturating_sub(w + 1);
                let mut s = String::new();
                let mut sw = 0;
                for ch in t.text.chars() {
                    let cw = char_width(ch);
                    if sw + cw > room {
                        break;
                    }
                    s.push(ch);
                    sw += cw;
                }
                if !s.is_empty() {
                    push_tok(&mut pieces, &s, st, t.ellipsis_at, skin);
                }
                pieces.push(Piece { text: "…".to_string(), style: skin.ellipsis });
                truncated = false;
                w = width;
                break;
            }
            push_tok(&mut pieces, &t.text, st, t.ellipsis_at, skin);
            w += tw;
        }
        let _ = w;
        return pieces;
    }
    toks.iter().map(|t| Piece { text: t.text.clone(), style: skin.style(t.kind) }).collect()
}

fn push_tok(pieces: &mut Vec<Piece>, text: &str, style: Style, ellipsis_at: Option<usize>, skin: &MdSkin) {
    match ellipsis_at {
        Some(p) => {
            let chars: Vec<char> = text.chars().collect();
            if p < chars.len() {
                let a: String = chars[..p].iter().collect();
                let b: String = chars[p + 1..].iter().collect();
                if !a.is_empty() {
                    pieces.push(Piece { text: a, style });
                }
                pieces.push(Piece { text: "…".to_string(), style: skin.ellipsis });
                if !b.is_empty() {
                    pieces.push(Piece { text: b, style });
                }
            } else {
                pieces.push(Piece { text: text.to_string(), style });
            }
        }
        None => pieces.push(Piece { text: text.to_string(), style }),
    }
}

pub fn write_pieces(screen: &mut Screen, x: usize, y: usize, pieces: &[Piece], max_x: usize) -> usize {
    let mut x = x;
    for p in pieces {
        x = screen.write_str(x, y, &p.text, p.style, max_x);
    }
    x
}
