//! Status line composition

use crate::md::{parse_inline, Compound};

#[derive(Debug, Clone)]
pub struct Status {
    pub message: String,
    pub error: bool,
}

impl Status {
    pub fn new(message: impl Into<String>, error: bool) -> Self {
        Status { message: message.into(), error }
    }
    pub fn from_message(m: impl Into<String>) -> Self {
        Status::new(m, false)
    }
    pub fn from_error(m: impl Into<String>) -> Self {
        Status::new(m, true)
    }
    pub fn compounds(&self) -> Vec<Compound> {
        parse_inline(&format!(" {}", self.message))
    }
}

/// what's selected, for the hint
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum SelKind {
    Root,
    Dir,
    File,
    None,
}

pub fn tree_hint(sel: SelKind, has_previous_state: bool, filtered: bool, width: usize) -> Status {
    let mut parts: Vec<String> = Vec::new();
    if has_previous_state {
        parts.push("*esc* to go back".to_string());
    }
    match sel {
        SelKind::Root => parts.push("*enter* to go up".to_string()),
        SelKind::Dir => parts.push("*enter* to focus".to_string()),
        SelKind::File => parts.push("*alt-Enter* to open and quit".to_string()),
        SelKind::None => {}
    }
    if filtered {
        parts.push("*esc* to clear the filter".to_string());
    }
    parts.push("*?* for help".to_string());
    let last = if sel == SelKind::Root && !filtered {
        "a few letters to search".to_string()
    } else {
        "a space then a verb".to_string()
    };
    // try with the last part, then without
    let with_last = compose(&parts, Some(&last));
    if visible_len(&with_last) + 1 <= width {
        return Status::from_message(with_last);
    }
    let mut parts = parts;
    loop {
        let m = compose(&parts, None);
        if visible_len(&m) + 1 <= width || parts.len() <= 1 {
            return Status::from_message(m);
        }
        parts.pop();
    }
}

fn compose(parts: &[String], last: Option<&String>) -> String {
    let mut s = String::from("Hit ");
    s.push_str(&parts.join(", "));
    if let Some(l) = last {
        s.push_str(", or ");
        s.push_str(l);
    }
    s
}

fn visible_len(md: &str) -> usize {
    parse_inline(md).iter().map(|c| crate::screen::str_width(&c.text)).sum()
}
