//! The tree browsing state

use crate::app::{AppCtx, CmdResult};
use crate::pattern::InputPattern;
use crate::tree::{LineType, Sort, Tree, TreeBuilder, TreeOptions};
use std::path::{Path, PathBuf};

pub struct BrowserState {
    pub tree: Tree,
    pub filtered: Option<Tree>,
    pub pattern: InputPattern,
    pub page_height: usize,
}

pub fn build_tree(root: &Path, options: &TreeOptions, page_height: usize, ctx: &AppCtx) -> Tree {
    let builder = TreeBuilder::new(root, options, page_height, &ctx.special_paths);
    let mut tree = builder.build();
    if options.needs_sums() {
        crate::sums::compute_sums(&mut tree, &ctx.special_paths);
    }
    if options.sort != Sort::None {
        crate::sums::sort_tree(&mut tree);
    }
    tree
}

impl BrowserState {
    pub fn new(root: PathBuf, options: TreeOptions, page_height: usize, ctx: &AppCtx) -> Self {
        let tree = build_tree(&root, &options.without_pattern(), page_height, ctx);
        BrowserState { tree, filtered: None, pattern: InputPattern::none(), page_height }
    }
    pub fn displayed_tree(&self) -> &Tree {
        self.filtered.as_ref().unwrap_or(&self.tree)
    }
    pub fn displayed_tree_mut(&mut self) -> &mut Tree {
        self.filtered.as_mut().unwrap_or(&mut self.tree)
    }
    pub fn root(&self) -> PathBuf {
        self.tree.root().clone()
    }
    pub fn options(&self) -> &TreeOptions {
        &self.tree.options
    }
    pub fn selected_path(&self) -> PathBuf {
        self.displayed_tree().selected_line().path.clone()
    }
    pub fn set_pattern(&mut self, pattern: InputPattern, ctx: &AppCtx) {
        let same = match (&self.pattern.composite, &pattern.composite) {
            (None, None) => true,
            _ => self.pattern.raw == pattern.raw && self.pattern.is_some() == pattern.is_some(),
        };
        if same {
            return;
        }
        if pattern.is_none() {
            // back to the unfiltered tree, keeping the selection
            if let Some(f) = &self.filtered {
                let p = f.selected_line().path.clone();
                if !self.tree.try_select_path(&p) {
                    // keep selection
                }
                self.tree.make_selection_visible(self.page_height);
            }
            self.filtered = None;
            self.pattern = pattern;
            return;
        }
        let mut options = self.tree.options.clone();
        options.pattern = pattern.clone();
        let root = self.root();
        let mut t = build_tree(&root, &options, self.page_height, ctx);
        t.try_select_best_match();
        t.make_selection_visible(self.page_height);
        self.filtered = Some(t);
        self.pattern = pattern;
    }
    pub fn refresh(&mut self, ctx: &AppCtx) {
        let root = self.root();
        let sel = self.selected_path();
        let options = self.tree.options.clone();
        self.tree = build_tree(&root, &options, self.page_height, ctx);
        self.tree.try_select_path(&sel);
        self.tree.make_selection_visible(self.page_height);
        if self.pattern.is_some() {
            let mut o = options.clone();
            o.pattern = self.pattern.clone();
            let mut t = build_tree(&root, &o, self.page_height, ctx);
            if !t.try_select_path(&sel) {
                t.try_select_best_match();
            }
            t.make_selection_visible(self.page_height);
            self.filtered = Some(t);
        }
    }
    pub fn resize(&mut self, page_height: usize, ctx: &AppCtx) {
        if page_height != self.page_height {
            self.page_height = page_height;
            self.refresh(ctx);
        }
    }
    pub fn move_selection(&mut self, dy: i32) {
        let ph = self.page_height;
        self.displayed_tree_mut().move_selection(dy, ph, true);
    }
    pub fn page(&mut self, down: bool) {
        let ph = self.page_height;
        let t = self.displayed_tree_mut();
        let len = t.lines.len();
        if len <= ph {
            return;
        }
        let max_scroll = len - ph;
        if down {
            t.scroll = (t.scroll + ph).min(max_scroll);
            if t.selection < t.scroll + 1 {
                t.selection = t.scroll + 1;
            }
        } else {
            t.scroll = t.scroll.saturating_sub(ph);
            if t.selection > t.scroll + ph - 1 {
                t.selection = t.scroll + ph - 1;
            }
        }
        while t.selection < len && !t.lines[t.selection].is_selectable() {
            if t.selection == 0 {
                break;
            }
            t.selection -= 1;
        }
    }
    pub fn select_first(&mut self) {
        let ph = self.page_height;
        let t = self.displayed_tree_mut();
        t.selection = 0;
        t.make_selection_visible(ph);
    }
    pub fn select_last(&mut self) {
        let ph = self.page_height;
        let t = self.displayed_tree_mut();
        let mut i = t.lines.len() - 1;
        while i > 0 && !t.lines[i].is_selectable() {
            i -= 1;
        }
        t.selection = i;
        t.make_selection_visible(ph);
    }
    pub fn next_match(&mut self, dir: i32) {
        let ph = self.page_height;
        let t = self.displayed_tree_mut();
        let n = t.lines.len() as i32;
        let mut i = t.selection as i32;
        for _ in 0..n {
            i = (i + dir).rem_euclid(n);
            let l = &t.lines[i as usize];
            if l.is_selectable() && (l.direct_match || t.options.pattern.is_none()) && i != 0 {
                if t.options.pattern.is_none() || l.direct_match {
                    t.selection = i as usize;
                    break;
                }
            }
        }
        t.make_selection_visible(ph);
    }
    /// selection kind for status hints
    pub fn sel_kind(&self) -> crate::status::SelKind {
        let t = self.displayed_tree();
        if t.selection == 0 {
            return crate::status::SelKind::Root;
        }
        let l = t.selected_line();
        match l.line_type {
            LineType::Dir => crate::status::SelKind::Dir,
            LineType::SymLink { final_is_dir: true, .. } => crate::status::SelKind::Dir,
            _ => crate::status::SelKind::File,
        }
    }
    pub fn no_match(&self) -> bool {
        match &self.filtered {
            Some(f) => !f.lines.iter().any(|l| l.direct_match),
            None => false,
        }
    }
}

pub fn _unused(_: CmdResult) {}
