//! Computation of file sums (sizes, counts, dates) and sorts depending on them

use crate::tree::{FileSum, LineType, Sort, SpecialPaths, Tree};
use std::collections::HashMap;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

static CACHE: Mutex<Option<HashMap<PathBuf, FileSum>>> = Mutex::new(None);

pub fn clear_cache() {
    *CACHE.lock().unwrap() = None;
}

pub fn file_sum(path: &Path, special: &SpecialPaths) -> FileSum {
    let md = match std::fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(_) => return FileSum::default(),
    };
    let own_size = md.blocks() * 512;
    let sparse = md.is_file() && own_size < md.len();
    if !md.is_dir() {
        return FileSum { size: own_size, count: 1, modified: md.mtime(), sparse };
    }
    {
        let c = CACHE.lock().unwrap();
        if let Some(map) = c.as_ref() {
            if let Some(s) = map.get(path) {
                return *s;
            }
        }
    }
    let mut sum = FileSum { size: own_size, count: 1, modified: md.mtime(), sparse: false };
    if special.find(path).sum != Some(false) {
        let mut stack = vec![path.to_path_buf()];
        let mut seen_inodes = std::collections::HashSet::new();
        while let Some(dir) = stack.pop() {
            if let Ok(entries) = std::fs::read_dir(&dir) {
                for e in entries.flatten() {
                    let p = e.path();
                    if let Ok(m) = std::fs::symlink_metadata(&p) {
                        if m.nlink() > 1 && !m.is_dir() && !seen_inodes.insert((m.dev(), m.ino())) {
                            continue;
                        }
                        sum.count += 1;
                        sum.size += m.blocks() * 512;
                        if m.mtime() > sum.modified {
                            sum.modified = m.mtime();
                        }
                        if m.is_dir() && special.find(&p).sum != Some(false) {
                            stack.push(p);
                        }
                    }
                }
            }
        }
    }
    let mut c = CACHE.lock().unwrap();
    c.get_or_insert_with(HashMap::new).insert(path.to_path_buf(), sum);
    sum
}

pub fn compute_sums(tree: &mut Tree, special: &SpecialPaths) {
    for line in tree.lines.iter_mut() {
        if matches!(line.line_type, LineType::Pruning) {
            continue;
        }
        line.sum = Some(file_sum(&line.path, special));
    }
}

pub fn sort_tree(tree: &mut Tree) {
    let sort = tree.options.sort;
    if tree.lines.len() < 2 {
        return;
    }
    let root = tree.lines.remove(0);
    let mut lines: Vec<_> = tree.lines.drain(..).filter(|l| l.depth == 1 || matches!(sort, Sort::TypeDirsFirst | Sort::TypeDirsLast)).collect();
    match sort {
        Sort::Size => lines.sort_by(|a, b| b.sum.map(|s| s.size).unwrap_or(0).cmp(&a.sum.map(|s| s.size).unwrap_or(0))),
        Sort::Count => lines.sort_by(|a, b| b.sum.map(|s| s.count).unwrap_or(0).cmp(&a.sum.map(|s| s.count).unwrap_or(0))),
        Sort::Date => lines.sort_by(|a, b| b.sum.map(|s| s.modified).unwrap_or(0).cmp(&a.sum.map(|s| s.modified).unwrap_or(0))),
        Sort::TypeDirsFirst | Sort::TypeDirsLast => {
            lines.retain(|l| l.depth == 1);
            let dirs_first = sort == Sort::TypeDirsFirst;
            lines.sort_by(|a, b| {
                let ad = a.is_dir();
                let bd = b.is_dir();
                if ad != bd {
                    return if ad == dirs_first { std::cmp::Ordering::Less } else { std::cmp::Ordering::Greater };
                }
                let ea = a.path.extension().map(|e| e.to_string_lossy().to_lowercase()).unwrap_or_default();
                let eb = b.path.extension().map(|e| e.to_string_lossy().to_lowercase()).unwrap_or_default();
                ea.cmp(&eb).then(a.name.to_lowercase().cmp(&b.name.to_lowercase()))
            });
        }
        Sort::None => {}
    }
    lines.retain(|l| l.is_selectable());
    tree.lines.push(root);
    tree.lines.extend(lines);
    for l in tree.lines.iter_mut().skip(1) {
        l.depth = 1;
    }
    tree.after_lines_changed();
}
