//! The application: panels, states, event loop

use crate::browser::BrowserState;
use crate::command::{self, VerbInvocation};
use crate::conf::Conf;
use crate::display::{draw_tree, Area, DisplayCtx};
use crate::input::InputField;
use crate::keys;
use crate::md::{self, MdSkin};
use crate::pattern::SearchModeMap;
use crate::screen::Screen;
use crate::skin::{Skin, StyleMap};
use crate::status::{tree_hint, Status};
use crate::style::Style;
use crate::tree::{LineType, SpecialPaths, TreeOptions};
use crate::verbs::{ApplyTo, Execution, Verb, VerbSearch, VerbStore};
use crossterm::event::{self, Event, KeyCode, KeyEvent, KeyEventKind, KeyModifiers};
use std::io::Write;
use std::path::{Path, PathBuf};

pub struct AppCtx {
    pub conf: Conf,
    pub skin: Skin,
    pub verb_store: VerbStore,
    pub special_paths: SpecialPaths,
    pub search_modes: SearchModeMap,
    pub show_selection_mark: bool,
    pub date_time_format: String,
    pub outcmd: Option<PathBuf>,
    pub initial_options: TreeOptions,
    pub height: Option<u16>,
    pub launch_dir: PathBuf,
    pub color: bool,
    pub cmd_separator: String,
    pub quit_on_last_cancel: bool,
    pub verb_output: Option<PathBuf>,
}

pub enum CmdResult {
    Keep,
    Quit,
    PushState(PanelState),
    PopState,
    Error(String),
    Message(String),
    /// leave broot then do something
    Exit(ExitAction),
}

pub enum ExitAction {
    Print(String),
    WriteOutcmd(String),
    RunCommand(Vec<String>, Option<PathBuf>),
    None,
}

pub enum PanelState {
    Tree(BrowserState),
    Help(crate::help::HelpState),
}

pub struct Panel {
    pub states: Vec<PanelState>,
    pub input: InputField,
    pub status: Option<Status>,
}

impl Panel {
    pub fn state(&self) -> &PanelState {
        self.states.last().unwrap()
    }
    pub fn state_mut(&mut self) -> &mut PanelState {
        self.states.last_mut().unwrap()
    }
}

pub struct App {
    pub ctx: AppCtx,
    pub panels: Vec<Panel>,
    pub active: usize,
    pub width: usize,
    pub height: usize,
    pub exit: Option<ExitAction>,
    pub quit: bool,
    pub last_pattern: Option<String>,
}

pub fn md_skin_status(skin: &StyleMap, error: bool) -> MdSkin {
    if error {
        let e = skin.status_error;
        MdSkin { normal: e, italic: e.italic(), bold: e.bold(), code: e, ellipsis: skin.status_ellipsis }
    } else {
        MdSkin {
            normal: skin.status_normal,
            italic: skin.status_italic,
            bold: skin.status_bold,
            code: skin.status_code,
            ellipsis: skin.status_ellipsis,
        }
    }
}

impl App {
    pub fn new(ctx: AppCtx, root: PathBuf, width: usize, height: usize) -> Self {
        let page_height = Self::page_height_for(height, &ctx);
        let state = BrowserState::new(root, ctx.initial_options.clone(), page_height, &ctx);
        let panel = Panel { states: vec![PanelState::Tree(state)], input: InputField::default(), status: None };
        App { ctx, panels: vec![panel], active: 0, width, height, exit: None, quit: false, last_pattern: None }
    }

    fn page_height_for(height: usize, ctx: &AppCtx) -> usize {
        let h = match ctx.height {
            Some(h) => (h as usize).min(height.max(1)),
            None => height,
        };
        h.saturating_sub(2).max(1)
    }

    pub fn page_height(&self) -> usize {
        Self::page_height_for(self.height, &self.ctx)
    }

    fn panel(&self) -> &Panel {
        &self.panels[self.active]
    }
    fn panel_mut(&mut self) -> &mut Panel {
        &mut self.panels[self.active]
    }

    pub fn resize(&mut self, w: usize, h: usize) {
        self.width = w;
        self.height = h;
        let ph = self.page_height();
        for p in self.panels.iter_mut() {
            for s in p.states.iter_mut() {
                if let PanelState::Tree(b) = s {
                    b.resize(ph, &self.ctx);
                }
            }
        }
    }

    // ------------------------------------------------------------ rendering

    pub fn draw(&mut self, screen: &mut Screen) {
        let skin = &self.ctx.skin.focused;
        screen.clear(Style { fg: skin.default.fg, bg: None, attrs: Default::default() });
        let w = self.width;
        let h = self.height;
        let panel = &self.panels[self.active];
        let tree_h = h.saturating_sub(2).max(1);
        match panel.state() {
            PanelState::Tree(b) => {
                let ctxd = DisplayCtx {
                    skin,
                    show_selection_mark: self.ctx.show_selection_mark,
                    in_app: true,
                    focused: true,
                    date_time_format: &self.ctx.date_time_format,
                };
                let area = Area { left: 0, top: 0, width: w, height: tree_h };
                draw_tree(screen, b.displayed_tree(), &area, &ctxd, &b.pattern);
            }
            PanelState::Help(hs) => {
                hs.draw(screen, &Area { left: 0, top: 0, width: w, height: tree_h }, skin);
            }
        }
        // status
        let status = self.compute_status();
        if h >= 2 {
            let y = h - 2;
            let mds = md_skin_status(skin, status.error);
            let pieces = md::fit(&status.compounds(), w, &mds);
            let x = md::write_pieces(screen, 0, y, &pieces, w);
            screen.fill(x, y, w, mds.normal);
        }
        // input
        if h >= 1 {
            self.draw_input(screen, h - 1);
        }
    }

    fn flags(&self) -> Vec<(&'static str, &'static str)> {
        let panel = self.panel();
        match panel.state() {
            PanelState::Tree(b) => {
                let o = b.options();
                vec![("h", if o.show_hidden { "y" } else { "n" }), ("gi", if o.respect_git_ignore { "y" } else { "n" })]
            }
            PanelState::Help(_) => vec![],
        }
    }

    fn draw_input(&self, screen: &mut Screen, y: usize) {
        let skin = &self.ctx.skin.focused;
        let w = self.width;
        let flags = self.flags();
        let mut flags_w = 0;
        for (l, v) in &flags {
            flags_w += 1 + l.len() + 1 + v.len() + 1;
        }
        let input_w = w.saturating_sub(flags_w);
        let panel = self.panel();
        let input_style = skin.input;
        let chars = &panel.input.chars;
        let cursor = panel.input.cursor;
        // scrolling of the input if too long
        let start = if cursor + 1 > input_w { cursor + 1 - input_w } else { 0 };
        let mut x = 0;
        for (i, &c) in chars.iter().enumerate().skip(start) {
            if x >= input_w {
                break;
            }
            let st = if i == cursor { input_style.reverse() } else { input_style };
            x += screen.set(x, y, c, st);
        }
        if cursor >= chars.len() && x < input_w {
            x += screen.set(x, y, ' ', input_style.reverse());
        }
        screen.fill(x, y, input_w, input_style);
        let mut x = input_w;
        if matches!(panel.state(), PanelState::Help(_)) {
            // help state: just the input
            screen.fill(x, y, w, input_style);
            return;
        }
        for (l, v) in &flags {
            x = screen.write_str(x, y, &format!(" {}:", l), skin.flag_label, w);
            x = screen.write_str(x, y, v, skin.flag_value, w);
            x = screen.write_str(x, y, " ", skin.flag_label, w);
        }
    }

    pub fn compute_status(&self) -> Status {
        let panel = self.panel();
        if let Some(s) = &panel.status {
            return s.clone();
        }
        let raw = panel.input.get();
        let parts = command::parse(&raw, &self.ctx.search_modes);
        if let Some(e) = &parts.pattern_error {
            return Status::from_error(e.clone());
        }
        if let Some(vi) = &parts.verb_invocation {
            return self.verb_status(vi);
        }
        match panel.state() {
            PanelState::Tree(b) => {
                if b.pattern.is_some() && b.no_match() {
                    let mut msgs = Vec::new();
                    if !b.options().show_hidden {
                        msgs.push("Some files are hidden, use *alt-h* to display them.");
                    }
                    if b.options().respect_git_ignore {
                        msgs.push("Some files are ignored, use *alt-i* to display them");
                    }
                    if !msgs.is_empty() {
                        return Status::from_message(msgs.join(" "));
                    }
                }
                tree_hint(b.sel_kind(), panel.states.len() > 1, b.filtered.is_some(), self.width)
            }
            PanelState::Help(_) => Status::from_message("Hit *esc* to get back, or a space to start a verb"),
        }
    }

    fn selection_info(&self) -> Option<(PathBuf, bool, bool)> {
        // (path, is_dir, is_root)
        match self.panel().state() {
            PanelState::Tree(b) => {
                let t = b.displayed_tree();
                let l = t.selected_line();
                Some((l.target_path_or_path(), l.is_dir_like(), t.selection == 0))
            }
            PanelState::Help(_) => {
                let p = crate::conf::default_conf_path();
                Some((p, false, false))
            }
        }
    }

    fn verb_applies(&self, v: &Verb) -> bool {
        let Some((path, is_dir, _)) = self.selection_info() else { return true };
        match v.apply_to {
            ApplyTo::Any => true,
            ApplyTo::Directory => is_dir,
            ApplyTo::File => !is_dir,
            ApplyTo::TextFile => !is_dir && crate::preview::is_text_file(&path),
            ApplyTo::BinaryFile => !is_dir && !crate::preview::is_text_file(&path),
        }
    }

    fn search_verbs(&self, prefix: &str) -> (Vec<&Verb>, Vec<String>) {
        let mut exact: Vec<&Verb> = Vec::new();
        let mut found: Vec<&Verb> = Vec::new();
        let mut names: Vec<String> = Vec::new();
        for v in &self.ctx.verb_store.verbs {
            if !self.verb_applies(v) {
                continue;
            }
            if v.name == prefix || v.shortcut.as_deref() == Some(prefix) {
                exact.push(v);
            }
            let mut m = false;
            for n in v.names() {
                if n.starts_with(prefix) {
                    names.push(n.to_string());
                    m = true;
                }
            }
            if m {
                found.push(v);
            }
        }
        if !exact.is_empty() {
            return (vec![exact[0]], vec![]);
        }
        (found, names)
    }

    fn verb_status(&self, vi: &VerbInvocation) -> Status {
        if vi.name.is_empty() {
            return Status::from_message("Type a verb then *enter* to execute it (*?* for the list of verbs)");
        }
        let (found, names) = self.search_verbs(&vi.name);
        match found.len() {
            0 => Status::from_error("No matching verb (*?* for the list of verbs)"),
            1 => {
                let v = found[0];
                self.verb_description_status(v, vi)
            }
            _ => {
                let list: Vec<String> = names.iter().map(|n| format!("*{}*", n)).collect();
                Status::from_message(format!("Possible verbs: {}", list.join(", ")))
            }
        }
    }

    fn verb_description_status(&self, v: &Verb, vi: &VerbInvocation) -> Status {
        let args = vi.args.clone().unwrap_or_default();
        if v.needs_arg() && args.trim().is_empty() {
            return Status::from_error(format!("{} {}", vi.name, v.invocation_args.as_deref().unwrap_or("")));
        }
        match &v.execution {
            Execution::Internal(name, iargs) => {
                if name == "focus" {
                    let target = if args.trim().is_empty() {
                        match iargs {
                            Some(a) => self.expand_path_arg(a),
                            None => self.focus_target(),
                        }
                    } else {
                        self.expand_path_arg(&args)
                    };
                    return Status::from_message(format!("Hit *enter* to focus `{}`", target.to_string_lossy()));
                }
                Status::from_message(format!("Hit *enter* to **{}**: {}", v.name, v.description))
            }
            Execution::External(pattern) => {
                let cmd = self.expand_exec_pattern(pattern, v, &args);
                Status::from_message(format!("Hit *enter* to **{}**: `{}`", v.name, cmd))
            }
            Execution::Sequence(seq) => Status::from_message(format!("Hit *enter* to **{}**: `{}`", v.name, seq)),
        }
    }

    fn focus_target(&self) -> PathBuf {
        match self.panel().state() {
            PanelState::Tree(b) => {
                let t = b.displayed_tree();
                let l = t.selected_line();
                if l.is_dir_like() {
                    l.target_path_or_path()
                } else {
                    l.path.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| l.path.clone())
                }
            }
            _ => self.ctx.launch_dir.clone(),
        }
    }

    fn current_root(&self) -> PathBuf {
        for s in self.panel().states.iter().rev() {
            if let PanelState::Tree(b) = s {
                return b.root();
            }
        }
        self.ctx.launch_dir.clone()
    }

    fn expand_path_arg(&self, arg: &str) -> PathBuf {
        let arg = arg.trim();
        let p = crate::conf::expand_tilde(arg);
        let p = if p.is_absolute() { p } else { self.current_root().join(p) };
        crate::tree::normalize(&p)
    }

    /// expand an execution pattern like "mkdir -p {subpath:path-from-directory}"
    pub fn expand_exec_pattern(&self, pattern: &str, v: &Verb, args: &str) -> String {
        let (sel_path, is_dir, _) = self.selection_info().unwrap_or((self.ctx.launch_dir.clone(), true, false));
        let file = sel_path.clone();
        let parent = file.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| file.clone());
        let directory = if is_dir { file.clone() } else { parent.clone() };
        // invocation args mapping
        let mut named: Vec<(String, String)> = Vec::new();
        if let Some(inv) = &v.invocation_args {
            let names = invocation_arg_names(inv);
            if names.len() == 1 {
                named.push((names[0].clone(), args.trim().to_string()));
            } else {
                let mut parts = args.split_whitespace();
                for n in names {
                    named.push((n, parts.next().unwrap_or("").to_string()));
                }
            }
        }
        let mut out = String::new();
        let chars: Vec<char> = pattern.chars().collect();
        let mut i = 0;
        while i < chars.len() {
            if chars[i] == '{' {
                if let Some(j) = chars[i..].iter().position(|&c| c == '}') {
                    let inner: String = chars[i + 1..i + j].iter().collect();
                    let (name, fmt) = match inner.find(':') {
                        Some(k) => (inner[..k].to_string(), Some(inner[k + 1..].to_string())),
                        None => (inner.clone(), None),
                    };
                    let val = match name.as_str() {
                        "file" => Some(file.to_string_lossy().to_string()),
                        "parent" => Some(parent.to_string_lossy().to_string()),
                        "directory" => Some(directory.to_string_lossy().to_string()),
                        "file-name" => Some(file.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default()),
                        "file-stem" => Some(file.file_stem().map(|n| n.to_string_lossy().to_string()).unwrap_or_default()),
                        "file-extension" => Some(file.extension().map(|n| n.to_string_lossy().to_string()).unwrap_or_default()),
                        "file-dot-extension" => Some(file.extension().map(|n| format!(".{}", n.to_string_lossy())).unwrap_or_default()),
                        "root" => Some(self.current_root().to_string_lossy().to_string()),
                        "line" => Some("0".to_string()),
                        _ => None,
                    };
                    let val = match val {
                        Some(v) => v,
                        None => {
                            let a = named.iter().find(|(n, _)| *n == name).map(|(_, v)| v.clone());
                            match a {
                                Some(a) => {
                                    let fmt = fmt.or_else(|| default_arg_format(&name, v));
                                    match fmt.as_deref() {
                                        Some("path-from-parent") => path_from(&parent, &a),
                                        Some("path-from-directory") => path_from(&directory, &a),
                                        Some(_) | None => {
                                            if name == "subpath" || name == "newpath" {
                                                path_from(&directory, &a)
                                            } else {
                                                a
                                            }
                                        }
                                    }
                                }
                                None => format!("{{{}}}", inner),
                            }
                        }
                    };
                    out.push_str(&val);
                    i += j + 1;
                    continue;
                }
            }
            out.push(chars[i]);
            i += 1;
        }
        out
    }

    // ------------------------------------------------------------ events

    pub fn on_input_changed(&mut self) {
        let raw = self.panel().input.get();
        let parts = command::parse(&raw, &self.ctx.search_modes);
        self.panel_mut().status = None;
        let ctx = &self.ctx;
        let panel = &mut self.panels[self.active];
        match panel.states.last_mut().unwrap() {
            PanelState::Tree(b) => {
                b.set_pattern(parts.pattern.clone(), ctx);
            }
            PanelState::Help(h) => {
                h.set_pattern(&parts.raw_pattern);
            }
        }
    }

    pub fn on_key(&mut self, key: KeyEvent) {
        let id = keys::key_id(&key);
        let panel_input_empty = self.panel().input.is_empty();
        // special keys
        match key.code {
            KeyCode::Enter if key.modifiers.is_empty() => {
                let raw = self.panel().input.get();
                let parts = command::parse(&raw, &self.ctx.search_modes);
                if let Some(vi) = parts.verb_invocation {
                    if !vi.name.is_empty() {
                        self.execute_invocation(&vi, true);
                        return;
                    }
                    return;
                }
                // no verb: the key binding for enter
            }
            _ => {}
        }
        // input edition keys take precedence when there's an input
        if !panel_input_empty || matches!(key.code, KeyCode::Char(_)) {
            if self.handle_input_key(&key) {
                return;
            }
        }
        // key bindings
        let verb = self
            .ctx
            .verb_store
            .verbs
            .iter()
            .find(|v| v.keys.iter().any(|k| *k == id) && self.verb_applies(v))
            .cloned();
        if let Some(v) = verb {
            self.execute_verb(&v, "", false, true);
            return;
        }
        if panel_input_empty {
            self.handle_input_key(&key);
        }
    }

    fn handle_input_key(&mut self, key: &KeyEvent) -> bool {
        let mods = key.modifiers;
        let plain = mods.is_empty() || mods == KeyModifiers::SHIFT;
        let input = &mut self.panels[self.active].input;
        let changed;
        match key.code {
            KeyCode::Char(c) if plain => {
                if c == '?' && input.is_empty() {
                    let v = self.ctx.verb_store.internal("help").cloned().unwrap();
                    self.execute_verb(&v, "", false, true);
                    return true;
                }
                input.insert(c);
                changed = true;
            }
            KeyCode::Backspace if plain => {
                changed = input.del_char_left();
                if !changed {
                    return true;
                }
            }
            KeyCode::Delete if plain => {
                changed = input.del_char_below();
                if !changed {
                    return true;
                }
            }
            KeyCode::Left if plain && !input.is_empty() => {
                input.move_left();
                return true;
            }
            KeyCode::Right if plain && !input.is_empty() => {
                input.move_right();
                return true;
            }
            KeyCode::Home if plain && !input.is_empty() => {
                input.move_to_start();
                return true;
            }
            KeyCode::End if plain && !input.is_empty() => {
                input.move_to_end();
                return true;
            }
            _ => return false,
        }
        if changed {
            self.on_input_changed();
        }
        true
    }

    pub fn execute_invocation(&mut self, vi: &VerbInvocation, from_input: bool) {
        let (found, _) = self.search_verbs(&vi.name);
        if found.len() != 1 {
            if found.is_empty() {
                self.panel_mut().status = Some(Status::from_error("No matching verb (*?* for the list of verbs)"));
            }
            return;
        }
        let v = found[0].clone();
        let args = vi.args.clone().unwrap_or_default();
        if v.needs_arg() && args.trim().is_empty() {
            return;
        }
        self.execute_verb(&v, &args, vi.bang, from_input);
    }

    fn clear_input_verb_part(&mut self) {
        // after a verb execution, the input keeps only the pattern
        let raw = self.panel().input.get();
        let (pat, verb) = command::split(&raw);
        if verb.is_some() {
            self.panel_mut().input.set(&pat);
        }
    }

    pub fn execute_verb(&mut self, v: &Verb, args: &str, _bang: bool, _from_input: bool) {
        let result = match &v.execution {
            Execution::Internal(name, iargs) => {
                let a = if args.trim().is_empty() { iargs.clone().unwrap_or_default() } else { args.to_string() };
                let name = name.clone();
                self.execute_internal(&name, &a, v)
            }
            Execution::External(pattern) => {
                let cmd = self.expand_exec_pattern(pattern, v, args);
                self.execute_external(&cmd, v)
            }
            Execution::Sequence(seq) => {
                let seq = self.expand_exec_pattern(seq, v, args);
                self.clear_input_verb_part();
                self.execute_sequence(&seq);
                CmdResult::Keep
            }
        };
        self.apply_result(result);
    }

    pub fn execute_sequence(&mut self, seq: &str) {
        let sep = self.ctx.cmd_separator.clone();
        for c in seq.split(sep.as_str()) {
            if self.quit {
                break;
            }
            self.execute_command_str(c);
        }
    }

    /// execute a command as if it had been typed then (for verbs) enter hit
    pub fn execute_command_str(&mut self, c: &str) {
        let parts = command::parse(c, &self.ctx.search_modes);
        let has_pattern = !parts.raw_pattern.is_empty();
        if has_pattern || parts.verb_invocation.is_none() {
            self.panel_mut().input.set(&parts.raw_pattern);
            self.on_input_changed();
        }
        if let Some(vi) = parts.verb_invocation {
            if !vi.name.is_empty() {
                let raw_input = self.panel().input.get();
                self.execute_invocation(&vi, false);
                let _ = raw_input;
            }
        }
    }

    fn apply_result(&mut self, r: CmdResult) {
        match r {
            CmdResult::Keep => {
                self.clear_input_verb_part();
            }
            CmdResult::Quit => {
                self.quit = true;
            }
            CmdResult::PushState(s) => {
                let panel = self.panel_mut();
                panel.states.push(s);
                panel.input.clear();
                panel.status = None;
            }
            CmdResult::PopState => {
                let panel = self.panel_mut();
                if panel.states.len() > 1 {
                    panel.states.pop();
                    panel.input.clear();
                    panel.status = None;
                    // restore the pattern of the state
                    let pat = match panel.state() {
                        PanelState::Tree(b) => b.pattern.raw.clone(),
                        _ => String::new(),
                    };
                    panel.input.set(&pat);
                } else if self.ctx.quit_on_last_cancel {
                    self.quit = true;
                }
            }
            CmdResult::Error(e) => {
                self.clear_input_verb_part();
                self.panel_mut().status = Some(Status::from_error(e));
            }
            CmdResult::Message(m) => {
                self.clear_input_verb_part();
                self.panel_mut().status = Some(Status::from_message(m));
            }
            CmdResult::Exit(a) => {
                self.exit = Some(a);
                self.quit = true;
            }
        }
    }

    fn new_tree_state(&self, root: PathBuf, options: TreeOptions) -> PanelState {
        let ph = self.page_height();
        PanelState::Tree(BrowserState::new(root, options, ph, &self.ctx))
    }

    fn current_options(&self) -> TreeOptions {
        for s in self.panel().states.iter().rev() {
            if let PanelState::Tree(b) = s {
                return b.options().clone();
            }
        }
        self.ctx.initial_options.clone()
    }

    fn execute_internal(&mut self, name: &str, args: &str, _v: &Verb) -> CmdResult {
        let ph = self.page_height();
        let is_tree = matches!(self.panel().state(), PanelState::Tree(_));
        match name {
            "quit" => return CmdResult::Quit,
            "help" => {
                let hs = crate::help::HelpState::new(&self.ctx);
                return CmdResult::PushState(PanelState::Help(hs));
            }
            "escape" => {
                let panel = self.panel_mut();
                if !panel.input.is_empty() {
                    let raw = panel.input.get();
                    let (_pat, verb) = command::split(&raw);
                    let _ = verb;
                    panel.input.clear();
                    panel.status = None;
                    self.on_input_changed();
                    return CmdResult::Keep;
                }
                if panel.status.is_some() {
                    panel.status = None;
                }
                return CmdResult::PopState;
            }
            "back" => return CmdResult::PopState,
            _ => {}
        }
        if let PanelState::Help(h) = self.panel_mut().state_mut() {
            match name {
                "line_down" => h.scroll_by(1),
                "line_up" => h.scroll_by(-1),
                "page_down" => h.scroll_page(1),
                "page_up" => h.scroll_page(-1),
                "open_stay" | "open_leave" => {}
                "print_path" => {
                    return CmdResult::Exit(ExitAction::Print(crate::conf::default_conf_path().to_string_lossy().to_string()));
                }
                _ => {}
            }
            return CmdResult::Keep;
        }
        if !is_tree {
            return CmdResult::Keep;
        }
        let ctx = &self.ctx;
        let panel = &mut self.panels[self.active];
        let PanelState::Tree(b) = panel.states.last_mut().unwrap() else { return CmdResult::Keep };
        let sel_line = b.displayed_tree().selected_line().clone();
        let sel_is_root = b.displayed_tree().selection == 0;
        let root = b.root();
        match name {
            "line_down" => {
                b.move_selection(1);
                CmdResult::Keep
            }
            "line_up" => {
                b.move_selection(-1);
                CmdResult::Keep
            }
            "page_down" => {
                b.page(true);
                CmdResult::Keep
            }
            "page_up" => {
                b.page(false);
                CmdResult::Keep
            }
            "select_first" => {
                b.select_first();
                CmdResult::Keep
            }
            "select_last" => {
                b.select_last();
                CmdResult::Keep
            }
            "next_match" => {
                b.next_match(1);
                CmdResult::Keep
            }
            "previous_match" => {
                b.next_match(-1);
                CmdResult::Keep
            }
            "refresh" => {
                crate::sums::clear_cache();
                b.refresh(ctx);
                CmdResult::Keep
            }
            "select" | "show" => {
                let p = if args.trim().is_empty() { root.clone() } else { expand_rel(&root, args) };
                let t = b.displayed_tree_mut();
                if t.try_select_path(&p) {
                    t.make_selection_visible(ph);
                }
                CmdResult::Keep
            }
            "open_stay" | "open_stay_filter" => {
                if sel_is_root {
                    match root.parent() {
                        Some(p) => {
                            let p = p.to_path_buf();
                            let mut opts = b.options().clone();
                            opts.pattern = crate::pattern::InputPattern::none();
                            let mut st = BrowserState::new(p, opts, ph, ctx);
                            st.tree.try_select_path(&root);
                            st.tree.make_selection_visible(ph);
                            CmdResult::PushState(PanelState::Tree(st))
                        }
                        None => CmdResult::Keep,
                    }
                } else if sel_line.is_dir_like() {
                    let target = sel_line.target_path_or_path();
                    let st = BrowserState::new(target, b.options().clone(), ph, ctx);
                    CmdResult::PushState(PanelState::Tree(st))
                } else {
                    open_with_os(&sel_line.path);
                    CmdResult::Keep
                }
            }
            "open_leave" => {
                if sel_line.is_dir_like() && ctx.outcmd.is_some() {
                    CmdResult::Exit(ExitAction::WriteOutcmd(format!("cd {}", shell_quote(&sel_line.target_path_or_path().to_string_lossy()))))
                } else {
                    let p = sel_line.path.clone();
                    CmdResult::Exit(ExitAction::RunCommand(vec!["xdg-open".to_string(), p.to_string_lossy().to_string()], None))
                }
            }
            "cd" => {
                let target = if sel_line.is_dir_like() {
                    sel_line.target_path_or_path()
                } else {
                    sel_line.path.parent().map(|p| p.to_path_buf()).unwrap_or(root.clone())
                };
                if ctx.outcmd.is_some() {
                    CmdResult::Exit(ExitAction::WriteOutcmd(format!("cd {}", shell_quote(&target.to_string_lossy()))))
                } else {
                    CmdResult::Error("This feature needs broot to be launched with the `br` script".to_string())
                }
            }
            "focus" => {
                let target = if !args.trim().is_empty() {
                    expand_rel(&root, args)
                } else if sel_is_root || sel_line.is_dir_like() {
                    sel_line.target_path_or_path()
                } else {
                    sel_line.path.parent().map(|p| p.to_path_buf()).unwrap_or(root.clone())
                };
                let mut opts = b.options().clone();
                opts.pattern = crate::pattern::InputPattern::none();
                let st = BrowserState::new(target, opts, ph, ctx);
                CmdResult::PushState(PanelState::Tree(st))
            }
            "parent" => {
                let base = if sel_is_root { root.clone() } else { sel_line.path.parent().map(|p| p.to_path_buf()).unwrap_or(root.clone()) };
                let target = if sel_is_root { base.parent().map(|p| p.to_path_buf()).unwrap_or(base.clone()) } else { base.parent().map(|p| p.to_path_buf()).unwrap_or(base.clone()) };
                let mut st = BrowserState::new(target, b.options().without_pattern(), ph, ctx);
                st.tree.try_select_path(&base);
                st.tree.make_selection_visible(ph);
                CmdResult::PushState(PanelState::Tree(st))
            }
            "up_tree" | "root_up" => match root.parent() {
                Some(p) => {
                    let mut st = BrowserState::new(p.to_path_buf(), b.options().without_pattern(), ph, ctx);
                    st.tree.try_select_path(&root);
                    st.tree.make_selection_visible(ph);
                    CmdResult::PushState(PanelState::Tree(st))
                }
                None => CmdResult::Keep,
            },
            "root_down" => {
                if !sel_is_root && sel_line.is_dir_like() {
                    let st = BrowserState::new(sel_line.target_path_or_path(), b.options().without_pattern(), ph, ctx);
                    CmdResult::PushState(PanelState::Tree(st))
                } else {
                    CmdResult::Keep
                }
            }
            "print_path" => CmdResult::Exit(ExitAction::Print(sel_line.path.to_string_lossy().to_string())),
            "print_relative_path" => {
                let rel = pathdiff(&sel_line.path, &ctx.launch_dir);
                CmdResult::Exit(ExitAction::Print(rel))
            }
            "print_tree" => {
                let t = b.displayed_tree().clone();
                let s = crate::print::tree_to_string(&t, ctx, &b.pattern, self.width);
                CmdResult::Exit(ExitAction::Print(s))
            }
            n if n.starts_with("toggle_") || n.starts_with("sort_by") || n == "no_sort" || n == "set_max_depth" || n == "unset_max_depth" || n == "apply_flags" => {
                let mut opts = b.options().clone();
                match n {
                    "toggle_hidden" => opts.show_hidden = !opts.show_hidden,
                    "toggle_ignore" | "toggle_git_ignore" => opts.respect_git_ignore = !opts.respect_git_ignore,
                    "toggle_files" => opts.only_folders = !opts.only_folders,
                    "toggle_sizes" => opts.show_sizes = !opts.show_sizes,
                    "toggle_dates" => opts.show_dates = !opts.show_dates,
                    "toggle_perm" => opts.show_permissions = !opts.show_permissions,
                    "toggle_counts" => opts.show_counts = !opts.show_counts,
                    "toggle_git_file_info" => opts.show_git_file_info = !opts.show_git_file_info,
                    "toggle_git_status" => opts.filter_by_git_status = !opts.filter_by_git_status,
                    "toggle_root_fs" => opts.show_root_fs = !opts.show_root_fs,
                    "toggle_device_id" => opts.show_device_id = !opts.show_device_id,
                    "toggle_trim_root" => opts.trim_root = !opts.trim_root,
                    "toggle_tree" => opts.show_tree = !opts.show_tree,
                    "sort_by_count" => opts.sort = if opts.sort == crate::tree::Sort::Count { crate::tree::Sort::None } else { crate::tree::Sort::Count },
                    "sort_by_date" => opts.sort = if opts.sort == crate::tree::Sort::Date { crate::tree::Sort::None } else { crate::tree::Sort::Date },
                    "sort_by_size" => opts.sort = if opts.sort == crate::tree::Sort::Size { crate::tree::Sort::None } else { crate::tree::Sort::Size },
                    "sort_by_type" => opts.sort = if opts.sort == crate::tree::Sort::TypeDirsFirst { crate::tree::Sort::None } else { crate::tree::Sort::TypeDirsFirst },
                    "no_sort" => opts.sort = crate::tree::Sort::None,
                    "set_max_depth" => opts.max_depth = args.trim().parse().ok(),
                    "unset_max_depth" => opts.max_depth = None,
                    "apply_flags" => crate::flags::apply_flags(&mut opts, args.trim()),
                    _ => return CmdResult::Keep,
                }
                if opts.show_sizes || opts.sort == crate::tree::Sort::Size {
                    // size computation
                }
                let pattern = b.pattern.clone();
                let mut st = BrowserState::new(root.clone(), opts, ph, ctx);
                st.tree.try_select_path(&sel_line.path);
                st.tree.make_selection_visible(ph);
                if pattern.is_some() {
                    st.set_pattern(pattern, ctx);
                }
                CmdResult::PushState(PanelState::Tree(st))
            }
            "search_again" => CmdResult::Keep,
            "total_search" => CmdResult::Keep,
            _ => CmdResult::Keep,
        }
    }

    fn execute_external(&mut self, cmd: &str, v: &Verb) -> CmdResult {
        let parts = crate::shell::split_command(cmd);
        if parts.is_empty() {
            return CmdResult::Keep;
        }
        let dir = if v.set_working_dir { Some(self.current_root()) } else { None };
        if v.leave_broot {
            return CmdResult::Exit(ExitAction::RunCommand(parts, dir));
        }
        // run while broot is suspended
        crate::term::suspend();
        let status = std::process::Command::new(&parts[0]).args(&parts[1..]).current_dir(dir.unwrap_or_else(|| self.current_root())).status();
        crate::term::resume();
        let ctx = &self.ctx;
        let panel = &mut self.panels[self.active];
        if let PanelState::Tree(b) = panel.states.last_mut().unwrap() {
            crate::sums::clear_cache();
            b.refresh(ctx);
        }
        match status {
            Ok(s) if s.success() => CmdResult::Keep,
            Ok(s) => CmdResult::Error(format!("Command returned code {}", s.code().unwrap_or(-1))),
            Err(e) => CmdResult::Error(format!("Command not found: {} ({})", parts[0], e)),
        }
    }
}

trait TargetPath {
    fn target_path_or_path(&self) -> PathBuf;
}
impl TargetPath for crate::tree::TreeLine {
    fn target_path_or_path(&self) -> PathBuf {
        match &self.line_type {
            LineType::SymLink { .. } => self.path.clone(),
            _ => self.path.clone(),
        }
    }
}

fn invocation_arg_names(inv: &str) -> Vec<String> {
    let mut names = Vec::new();
    let mut rest = inv;
    while let Some(i) = rest.find('{') {
        if let Some(j) = rest[i..].find('}') {
            let inner = &rest[i + 1..i + j];
            let name = inner.split(':').next().unwrap_or("").to_string();
            names.push(name);
            rest = &rest[i + j + 1..];
        } else {
            break;
        }
    }
    names
}

fn default_arg_format(name: &str, v: &Verb) -> Option<String> {
    if let Some(inv) = &v.invocation_args {
        let key = format!("{{{}:", name);
        if let Some(i) = inv.find(&key) {
            let rest = &inv[i + key.len()..];
            if let Some(j) = rest.find('}') {
                return Some(rest[..j].to_string());
            }
        }
    }
    None
}

fn path_from(base: &Path, a: &str) -> String {
    let p = crate::conf::expand_tilde(a);
    let p = if p.is_absolute() { p } else { base.join(p) };
    crate::tree::normalize(&p).to_string_lossy().to_string()
}

fn expand_rel(root: &Path, a: &str) -> PathBuf {
    let p = crate::conf::expand_tilde(a.trim());
    let p = if p.is_absolute() { p } else { root.join(p) };
    crate::tree::normalize(&p)
}

pub fn shell_quote(s: &str) -> String {
    if s.chars().all(|c| c.is_alphanumeric() || "/._-+=@%^,:".contains(c)) {
        s.to_string()
    } else {
        format!("'{}'", s.replace('\'', "'\\''"))
    }
}

fn pathdiff(path: &Path, base: &Path) -> String {
    let pc: Vec<_> = path.components().collect();
    let bc: Vec<_> = base.components().collect();
    let mut i = 0;
    while i < pc.len() && i < bc.len() && pc[i] == bc[i] {
        i += 1;
    }
    let mut out = PathBuf::new();
    for _ in i..bc.len() {
        out.push("..");
    }
    for c in &pc[i..] {
        out.push(c.as_os_str());
    }
    let s = out.to_string_lossy().to_string();
    if s.is_empty() {
        ".".to_string()
    } else {
        s
    }
}

fn open_with_os(path: &Path) {
    let _ = std::process::Command::new("xdg-open")
        .arg(path)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn();
}

/// run the app; returns the exit action
pub fn run(mut app: App, cmd: Option<String>) -> std::io::Result<Option<ExitAction>> {
    let mut out = std::io::stderr();
    let mut screen = Screen::new(app.width, app.height);
    if let Some(c) = cmd {
        app.execute_sequence(&c);
        if app.quit {
            return Ok(app.exit.take());
        }
    }
    app.draw(&mut screen);
    screen.flush(&mut out)?;
    loop {
        let ev = event::read()?;
        match ev {
            Event::Key(k) => {
                if k.kind == KeyEventKind::Release {
                    continue;
                }
                app.on_key(k);
            }
            Event::Resize(w, h) => {
                app.resize(w as usize, h as usize);
                screen.resize(w as usize, h as usize);
            }
            Event::Mouse(_) => {
                continue;
            }
            _ => continue,
        }
        if app.quit {
            break;
        }
        app.draw(&mut screen);
        screen.flush(&mut out)?;
    }
    out.flush()?;
    Ok(app.exit.take())
}
