//! Terminal setup

use std::io::Write;

pub const LUMA_QUERY: &str = "\x1bP\x1b]11;?\x07\x1b[5n\x1b\\";
pub const ENTER: &str = "\x1b[?1049h\x1b[?25l\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1015h\x1b[?1006h";
pub const LEAVE: &str = "\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?25h\x1b[?1049l";

pub fn enter() -> std::io::Result<()> {
    crossterm::terminal::enable_raw_mode()?;
    let mut e = std::io::stderr();
    e.write_all(ENTER.as_bytes())?;
    e.flush()
}

pub fn leave() {
    let mut e = std::io::stderr();
    let _ = e.write_all(LEAVE.as_bytes());
    let _ = e.flush();
    let _ = crossterm::terminal::disable_raw_mode();
}

pub fn suspend() {
    leave();
}

pub fn resume() {
    let _ = enter();
    let mut e = std::io::stderr();
    let _ = e.write_all(b"\x1b[2J");
}

pub fn is_tty(fd: i32) -> bool {
    unsafe { libc::isatty(fd) == 1 }
}

/// terminal size from any tty fd
pub fn size() -> Option<(u16, u16)> {
    for fd in [2, 0, 1] {
        unsafe {
            let mut ws: libc::winsize = std::mem::zeroed();
            if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 && ws.ws_row > 0 {
                return Some((ws.ws_col, ws.ws_row));
            }
        }
    }
    // try /dev/tty
    if let Ok(f) = std::fs::File::open("/dev/tty") {
        use std::os::unix::io::AsRawFd;
        unsafe {
            let mut ws: libc::winsize = std::mem::zeroed();
            if libc::ioctl(f.as_raw_fd(), libc::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 {
                return Some((ws.ws_col, ws.ws_row));
            }
        }
    }
    None
}

