    let _ = o.write_all(LUMA_QUERY.as_bytes());
    let _ = o.flush();
    wait_luma_answer();
}

pub fn luma_query_stderr() {
    let mut o = std::io::stderr();
    let _ = o.write_all(LUMA_QUERY.as_bytes());
    let _ = o.flush();
    wait_luma_answer();
