    // we don't really parse the answer: we just wait for the terminal
    // (an answer, if any, is consumed by the raw mode reader)
    let raw_was = crossterm::terminal::is_raw_mode_enabled().unwrap_or(false);
    if !raw_was {
        let _ = crossterm::terminal::enable_raw_mode();
    }
    let start = std::time::Instant::now();
    while start.elapsed() < std::time::Duration::from_millis(100) {
