use std::io::Write;

pub const LUMA_QUERY: &str = "\x1bP\x1b]11;?\x07\x1b[5n\x1b\\";
pub const ENTER: &str = "\x1b[?1049h\x1b[?25l\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1015h\x1b[?1006h";
