use crate::cli::{self, Args};
use crate::conf::{self, Conf, Luma};
use crate::skin::Skin;
use crate::tree::{Sort, TreeOptions};
use crate::verbs::VerbStore;
use std::io::Write;
use std::path::PathBuf;

pub fn run() -> i32 {
    let args = cli::parse();
    if args.help {
        crate::clap_help::print_help();
        return 0;
    }
    if args.version {
        println!("broot 1.54.0");
        return 0;
    }
    if let Some(shell) = &args.print_shell_function {
        match crate::install::shell_function(shell) {
            Some(f) => {
                print!("{}", f);
                return 0;
            }
            None => {
                eprintln!("Unknown shell: {}", shell);
                return 1;
            }
        }
    }
    if let Some(state) = &args.set_install_state {
        return crate::install::set_install_state(state);
    }
    if let Some(dir) = &args.write_default_conf {
        if let Err(e) = conf::write_default_conf_in(&PathBuf::from(dir)) {
            eprintln!("IO Error : {}", e);
            return 1;
        }
        return 0;
    }
    if args.install {
        return crate::install::install(true);
    }
    // installation check
    match crate::install::check_install() {
        crate::install::CheckResult::Continue => {}
        crate::install::CheckResult::Quit(code) => return code,
    }
    match launch_app(args) {
        Ok(code) => code,
        Err(e) => {
            eprintln!("{}", e);
            1
        }
    }
}

