                        dir
                    );
                    println!("You should have a look at them: their comments will help you configure broot.");
                    println!("You should especially set up your favourite editor in verbs.hjson.");
                }
            }
            vec![main]
        }
    };
    let interactive = crate::term::is_tty(2) || crate::term::is_tty(0);
    if interactive {
        crate::term::luma_query_stderr();
    }
    for p in &conf_paths {
        if let Err(e) = conf.read_file(p, &luma, 0) {
            return Err(format!("Bad configuration file {:?} : {}", p, e));
        }
    }
    let color = color_enabled(&args);
    let skin = Skin::from_entries(&conf.skin, false);
    let verb_store = VerbStore::new(std::mem::take(&mut conf.verbs));
    let special_paths = conf.special_paths();
    let search_modes = conf.search_mode_map();
    let initial_options = tree_options(&conf, &args);
    let launch_dir = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("/"));
    let root = match &args.root {
        Some(r) => {
            let p = PathBuf::from(r);
            let p = if p.is_absolute() { p } else { launch_dir.join(p) };
            match std::fs::canonicalize(&p) {
                Ok(c) => c,
                Err(e) => return Err(format!("IO Error : {}", e)),
            }
        }
        None => launch_dir.clone(),
    };
    let ctx = AppCtx {
        show_selection_mark: conf.show_selection_mark.unwrap_or(false),
        date_time_format: conf.date_time_format.clone().unwrap_or_else(|| "%Y/%m/%d %R".to_string()),
