        verb_output: args.verb_output.as_ref().map(PathBuf::from),
    };
    let (w, h) = match crate::term::size() {
        Some(s) => s,
        None => {
            let mut e = std::io::stderr();
            let _ = e.write_all(crate::term::ENTER.as_bytes());
            let _ = e.write_all(crate::term::LEAVE.as_bytes());
