    }
    let res = crate::app::run(app, args.cmd.clone());
    crate::term::leave();
    let action = match res {
        Ok(a) => a,
        Err(e) => return Err(format!("IO Error : {}", e)),
    };
    let outcmd = args.outcmd.as_ref().map(PathBuf::from);
    match action {
        Some(ExitAction::Print(s)) => {
            let mut o = std::io::stdout();
            if s.ends_with('\n') {
                let _ = o.write_all(s.as_bytes());
            } else {
                let _ = writeln!(o, "{}", s);
            }
            let _ = o.flush();
        }
        Some(ExitAction::WriteOutcmd(s)) => {
            if let Some(p) = outcmd {
                let _ = std::fs::write(p, format!("{}\n", s));
            }
        }
        Some(ExitAction::RunCommand(cmd, dir)) => {
            if !cmd.is_empty() {
                let mut c = std::process::Command::new(&cmd[0]);
                c.args(&cmd[1..]);
                if let Some(d) = dir {
                    c.current_dir(d);
                }
                let _ = c.status();
            }
        }
        Some(ExitAction::None) | None => {}
    }
    Ok(0)
}
