{"command":"cd /workspace/src && cat > mdtext.rs <<'EOF'
//! Formatting of markdown texts (paragraphs, headers, bullets, tables)
//! into lines of styled pieces, a small part of termimad.

use crate::md::{parse_inline, Compound, Kind, MdSkin, Piece};
use crate::screen::{char_width, str_width};
use crate::style::Style;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Align {
    Left,
    Center,
    Right,
}

#[derive(Debug, Clone)]
pub struct TextSkin {
    pub md: MdSkin,
    pub headers: [Style; 2],
    pub table_border: Style,
    pub bullet: Style,
}

pub type FLine = Vec<Piece>;

fn compounds_width(c: &[Compound]) -> usize {
    c.iter().map(|c| str_width(&c.text)).sum()
}

/// a "word" for wrapping: a sequence of (char, kind) up to and including a break point
fn split_words(comps: &[Compound]) -> Vec<Vec<(char, Kind)>> {
    let mut words: Vec<Vec<(char, Kind)>> = Vec::new();
    let mut cur: Vec<(char, Kind)> = Vec::new();
    for c in comps {
        for ch in c.text.chars() {
            if ch == ' ' {
                // spaces are attached at the end of the current word
                cur.push((ch, c.kind));
                words.push(std::mem::take(&mut cur));
                continue;
            }
            cur.push((ch, c.kind));
            if ch == '/' {
                words.push(std::mem::take(&mut cur));
            }
        }
    }
    if !cur.is_empty() {
        words.push(cur);
    }
    words
}

fn chars_to_compounds(chars: &[(char, Kind)]) -> Vec<Compound> {
    let mut out: Vec<Compound> = Vec::new();
    for &(c, k) in chars {
        match out.last_mut() {
            Some(last) if last.kind == k => last.text.push(c),
            _ => out.push(Compound { text: c.to_string(), kind: k }),
        }
    }
    out
}

/// wrap compounds in lines of at most width
pub fn wrap(comps: &[Compound], width: usize) -> Vec<Vec<Compound>> {
    let width = width.max(1);
    if compounds_width(comps) <= width {
        return vec![comps.to_vec()];
    }
    let words = split_words(comps);
    let mut lines: Vec<Vec<(char, Kind)>> = Vec::new();
    let mut cur: Vec<(char, Kind)> = Vec::new();
    let mut cur_w = 0;
    for word in words {
        let ww: usize = word.iter().map(|(c, _)| char_width(*c)).sum();
        // width without trailing space
        let ww_trim: usize = ww - if word.last().map(|(c, _)| *c == ' ').unwrap_or(false) { 1 } else { 0 };
        if cur_w + ww_trim <= width {
            cur_w += ww;
            cur.extend(word);
            continue;
        }
        if cur_w > 0 {
            lines.push(std::mem::take(&mut cur));
            cur_w = 0;
        }
        // the word alone
        if ww_trim <= width {
            cur_w = ww;
            cur = word;
            continue;
        }
        // hard cut of a too long word
        for (c, k) in word {
            let cw = char_width(c);
            if cur_w + cw > width {
                if c == ' ' {
                    continue;
                }
                lines.push(std::mem::take(&mut cur));
                cur_w = 0;
            }
            cur.push((c, k));
            cur_w += cw;
        }
    }
    if !cur.is_empty() {
        lines.push(cur);
    }
    lines.iter().map(|l| chars_to_compounds(l)).collect()
}

fn pieces(comps: &[Compound], skin: &MdSkin) -> Vec<Piece> {
    comps.iter().map(|c| Piece { text: c.text.clone(), style: skin.style(c.kind) }).collect()
}

fn trim_end_compounds(mut comps: Vec<Compound>) -> Vec<Compound> {
    while let Some(last) = comps.last_mut() {
        let t = last.text.trim_end_matches(' ').to_string();
        if t.is_empty() {
            comps.pop();
        } else {
            last.text = t;
            break;
        }
    }
    comps
}

pub struct Table {
    pub header_aligns: Vec<Align>,
    pub body_aligns: Vec<Align>,
    pub header: Vec<Vec<Compound>>,
    pub rows: Vec<Vec<Vec<Compound>>>,
}

fn parse_align_row(line: &str) -> Option<Vec<Align>> {
    let inner = line.trim().trim_start_matches('|').trim_end_matches('|');
    let mut aligns = Vec::new();
    for cell in inner.split('|') {
        let c = cell.trim();
        if c.is_empty() || !c.chars().all(|ch| ch == '-' || ch == ':') || !c.contains('-') {
            return None;
        }
        let a = match (c.starts_with(':'), c.ends_with(':')) {
            (true, true) => Align::Center,
            (false, true) => Align::Right,
            _ => Align::Left,
        };
        aligns.push(a);
    }
    Some(aligns)
}

fn split_cells(line: &str) -> Vec<String> {
    let t = line.trim();
    let t = t.strip_prefix('|').unwrap_or(t);
    let t = t.strip_suffix('|').unwrap_or(t);
    // split on unescaped |, not inside backquotes
    let mut cells = Vec::new();
    let mut cur = String::new();
    let mut in_code = false;
    let mut chars = t.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&n) = chars.peek() {
                if n == '|' {
                    cur.push('|');
                    chars.next();
                    continue;
                }
            }
            cur.push(c);
            continue;
        }
        if c == '`' {
            in_code = !in_code;
        }
        if c == '|' && !in_code {
            cells.push(std::mem::take(&mut cur));
            continue;
