/// compute the columns widths
pub fn fit_columns(natural: &[usize], avgs: &[usize], available: usize) -> Vec<usize> {
    let n = natural.len();
    let borders = n + 1;
    let mut widths = natural.to_vec();
    let target = available.saturating_sub(borders);
    let sum = |w: &Vec<usize>| -> usize { w.iter().sum() };
    if sum(&widths) <= target {
        return widths;
    }
    // order of columns: widest first
    let mut order: Vec<usize> = (0..n).collect();
    order.sort_by(|&a, &b| natural[b].cmp(&natural[a]).then(a.cmp(&b)));
    // phase 1 : down to the average (min 4)
    for &i in &order {
        let s = sum(&widths);
        if s <= target {
            break;
        }
        let excess = s - target;
        let floor = avgs[i].max(4).min(widths[i]);
        let possible = widths[i] - floor;
        let r = possible.min(excess);
        widths[i] -= r;
    }
    // phase 2 : down to 3
    for &i in &order {
        let s = sum(&widths);
        if s <= target {
            break;
        }
        let excess = s - target;
        let floor = 3.min(widths[i]);
        let possible = widths[i] - floor;
        let r = possible.min(excess);
        widths[i] -= r;
    }
    widths
}

