/// format a markdown text
/// text_width: wrapping and centering width ; table_width: the available width for tables
pub fn format_text(md: &str, text_width: usize, table_width: usize, skin: &TextSkin) -> Vec<FLine> {
    let mut out: Vec<FLine> = Vec::new();
    let src_lines: Vec<&str> = md.lines().collect();
    let mut i = 0;
    while i < src_lines.len() {
        let line = src_lines[i];
        let t = line.trim_end();
        if t.starts_with('|') {
            // table: collect consecutive lines
            let mut tlines = Vec::new();
            while i < src_lines.len() && src_lines[i].trim_start().starts_with('|') {
                tlines.push(src_lines[i]);
                i += 1;
            }
            if let Some(tbl) = parse_table(&tlines) {
                let (lines, tw) = tbl.format(table_width, skin);
                let margin = text_width.saturating_sub(tw) / 2;
                for l in lines {
                    let mut fl = Vec::new();
                    if margin > 0 {
                        fl.push(Piece { text: " ".repeat(margin), style: skin.md.normal });
                    }
                    fl.extend(l);
                    out.push(fl);
                }
            }
            continue;
        }
        i += 1;
        if t.is_empty() {
            out.push(vec![]);
            continue;
        }
        if let Some(h) = t.strip_prefix("# ") {
            let comps = parse_inline(h);
            let st = skin.headers[0];
            let w = compounds_width(&comps);
            let margin = text_width.saturating_sub(w) / 2;
            let mut fl = Vec::new();
            if margin > 0 {
                fl.push(Piece { text: " ".repeat(margin), style: skin.md.normal });
            }
            for c in comps {
                fl.push(Piece { text: c.text, style: st });
            }
            out.push(fl);
            continue;
        }
        if let Some(h) = t.strip_prefix("## ") {
            let comps = parse_inline(h);
            let st = skin.headers[1];
            for l in wrap(&comps, text_width) {
                out.push(l.into_iter().map(|c| Piece { text: c.text, style: st }).collect());
            }
            continue;
        }
        if let Some(b) = t.strip_prefix("* ") {
            let mut comps = vec![Compound { text: "• ".to_string(), kind: Kind::Normal }];
            comps.extend(parse_inline(b));
            for l in wrap(&comps, text_width) {
                let mut fl = pieces(&l, &skin.md);
                if let Some(first) = fl.first_mut() {
                    if first.text.starts_with('•') {
                        let rest = first.text[('•'.len_utf8())..].to_string();
                        let st = first.style;
                        *first = Piece { text: "•".to_string(), style: skin.bullet };
                        if !rest.is_empty() {
                            fl.insert(1, Piece { text: rest, style: st });
                        }
                    }
                }
                out.push(fl);
            }
            continue;
        }
        let comps = parse_inline(t);
        for l in wrap(&comps, text_width) {
            out.push(pieces(&l, &skin.md));
        }
    }
    out
}

pub fn parse_table(lines: &[&str]) -> Option<Table> {
    // expected: an align row, a header row, an align row, body rows, an end row
    let mut idx = 0;
    let mut header_aligns = None;
    if let Some(a) = lines.get(idx).and_then(|l| parse_align_row(l)) {
        header_aligns = Some(a);
        idx += 1;
    }
    let header_line = lines.get(idx)?;
    let header: Vec<Vec<Compound>> = split_cells(header_line).iter().map(|c| parse_inline(c)).collect();
    idx += 1;
    let mut body_aligns = header_aligns.clone().unwrap_or_else(|| vec![Align::Left; header.len()]);
    if let Some(a) = lines.get(idx).and_then(|l| parse_align_row(l)) {
        body_aligns = a;
        idx += 1;
    }
    let header_aligns = header_aligns.unwrap_or_else(|| vec![Align::Center; header.len()]);
    let mut rows = Vec::new();
    while idx < lines.len() {
        let l = lines[idx];
        idx += 1;
        let tl = l.trim();
        if tl == "|-" || (tl.starts_with("|-") && tl.chars().all(|c| c == '|' || c == '-')) {
            break;
        }
        rows.push(split_cells(l).iter().map(|c| parse_inline(c)).collect());
    }
    Some(Table { header_aligns, body_aligns, header, rows })
}
