    if let Some(a) = lines.get(idx).and_then(|l| parse_align_row(l)) {
        header_aligns = Some(a);
        idx += 1;
    }
    let header_line = lines.get(idx)?;
    let header: Vec<Vec<Compound>> = split_cells(header_line).iter().map(|c| parse_inline(c)).collect();
    idx += 1;
    let mut body_aligns = header_aligns.clone().unwrap_or_else(|| vec![Align::Left; header.len()]);
    if let Some(a) = lines.get(idx).and_then(|l| parse_align_row(l)) {
        body_aligns = a;
        idx += 1;
    }
    let header_aligns = header_aligns.unwrap_or_else(|| vec![Align::Center; header.len()]);
    let mut rows = Vec::new();
    while idx < lines.len() {
        let l = lines[idx];
        idx += 1;
        let tl = l.trim();
        if tl == "|-" || (tl.starts_with("|-") && tl.chars().all(|c| c == '|' || c == '-')) {
            break;
        }
        rows.push(split_cells(l).iter().map(|c| parse_inline(c)).collect());
    }
    Some(Table { header_aligns, body_aligns, header, rows })
}
