//! The help screen

use crate::app::AppCtx;
use crate::display::Area;
use crate::screen::Screen;
use crate::skin::StyleMap;
use crate::verbs::Execution;

pub struct HelpState {
    pub scroll: usize,
    pub pattern: String,
    /// name, shortcut, keys, description (markdown)
    pub verbs: Vec<(String, String, String, String)>,
    pub conf_files: Vec<String>,
    pub page_height: usize,
    pub lines_count: usize,
}

impl HelpState {
    pub fn new(ctx: &AppCtx) -> Self {
        let mut verbs = Vec::new();
        for v in &ctx.verb_store.verbs {
            let desc = match &v.execution {
                Execution::External(e) => {
                    if v.from_conf && v.description != *e {
                        v.description.clone()
                    } else {
                        format!("`{}`", e)
                    }
                }
                Execution::Sequence(c) => {
                    if v.description != *c {
                        v.description.clone()
                    } else {
                        format!("`{}`", c)
                    }
                }
                Execution::Internal(_, _) => internal_md_description(&v.name, &v.description),
            };
            verbs.push((v.name.clone(), v.shortcut.clone().unwrap_or_default(), v.keys_desc.clone(), desc));
        }
        let conf_files = ctx.conf.files.iter().map(|f| f.to_string_lossy().to_string()).collect();
        HelpState { scroll: 0, pattern: String::new(), verbs, conf_files, page_height: 20, lines_count: 0 }
    }
    pub fn set_pattern(&mut self, p: &str) {
        if p != self.pattern {
            self.pattern = p.to_string();
            self.scroll = 0;
        }
    }
    pub fn scroll_by(&mut self, d: i32) {
        let s = self.scroll as i32 + d;
        let max = self.lines_count.saturating_sub(self.page_height) as i32;
        self.scroll = s.max(0).min(max.max(0)) as usize;
    }
    pub fn scroll_page(&mut self, d: i32) {
        let ph = self.page_height as i32;
        self.scroll_by(d * ph);
    }
    pub fn update_layout(&mut self, area: &Area, skin: &StyleMap) {
        let (lines, _, _) = crate::help_render::layout(self, area, skin);
        self.lines_count = lines.len();
        self.page_height = area.height;
        let max = self.lines_count.saturating_sub(self.page_height);
        if self.scroll > max {
            self.scroll = max;
        }
    }
    pub fn draw(&self, screen: &mut Screen, area: &Area, skin: &StyleMap) {
        crate::help_render::draw_help(self, screen, area, skin);
    }
}

fn internal_md_description(name: &str, d: &str) -> String {
    match name {
        "back" => "revert to the previous state (mapped to *esc*)".to_string(),
        "apply_flags" => "apply flags (eg `-sd` to show sizes and dates)".to_string(),
        "focus" => "display the directory (mapped to *enter*)".to_string(),
        _ => d.to_string(),
    }
}
