    pub fn scroll_page(&mut self, d: i32) {
        let ph = self.page_height as i32;
        self.scroll_by(d * ph);
    }
    pub fn update_layout(&mut self, area: &Area, skin: &StyleMap) {
        let (lines, _, _) = crate::help_render::layout(self, area, skin);
        self.lines_count = lines.len();
        self.page_height = area.height;
        let max = self.lines_count.saturating_sub(self.page_height);
        if self.scroll > max {
            self.scroll = max;
        }
    }
    pub fn draw(&self, screen: &mut Screen, area: &Area, skin: &StyleMap) {
        crate::help_render::draw_help(self, screen, area, skin);
    }
}

fn internal_md_description(name: &str, d: &str) -> String {
    match name {
        "back" => "revert to the previous state (mapped to *esc*)".to_string(),
        "apply_flags" => "apply flags (eg `-sd` to show sizes and dates)".to_string(),
        "focus" => "display the directory (mapped to *enter*)".to_string(),
        _ => d.to_string(),
    }
}
