//! --help output, reproducing the clap-help/termimad rendering

use crate::md::{Compound, Kind};
use crate::mdtext::{wrap, Align, Table};
use crate::screen::str_width;
use std::io::Write;

const EMPTY_ITALIC: &str = "\u{200C}";

fn c(text: &str, kind: Kind) -> Compound {
    Compound { text: text.to_string(), kind }
}

struct Opt {
