fn inline_code_split(s: &str) -> Vec<Compound> {
    // simple: `x` -> code
    crate::md::parse_inline(s)
}

fn build_table() -> Table {
    let header = vec![vec![c("short", Kind::Normal)], vec![c("long", Kind::Normal)], vec![c("description", Kind::Normal)]];
    let mut rows = Vec::new();
    for opt in options() {
        let value = opt.value.map(|v| format!("<{}>", v)).unwrap_or_default();
        let ival = if value.is_empty() { EMPTY_ITALIC.to_string() } else { value.clone() };
        let short = match opt.short {
            Some(s) => vec![c(&format!("-{} ", s), Kind::Normal), c(&ival, Kind::Italic)],
            None => vec![c(EMPTY_ITALIC, Kind::Italic)],
        };
        let long = vec![c(&format!("--{} ", opt.long), Kind::Normal), c(&ival, Kind::Italic)];
        rows.push(vec![short, long, inline_code_split(opt.help)]);
        if let Some(pv) = opt.possible {
            let vals: Vec<String> = pv.iter().map(|v| format!("`{}`", v)).collect();
            let desc = format!(" Possible values: [{}]", vals.join(", "));
            rows.push(vec![
                vec![c(EMPTY_ITALIC, Kind::Italic)],
                vec![c(" ", Kind::Normal), c(EMPTY_ITALIC, Kind::Italic)],
                inline_code_split(&desc),
            ]);
        }
        if let Some(d) = opt.default {
            let desc = format!(" Default: `{}`", d);
            rows.push(vec![
                vec![c(EMPTY_ITALIC, Kind::Italic)],
                vec![c(" ", Kind::Normal), c(EMPTY_ITALIC, Kind::Italic)],
                inline_code_split(&desc),
            ]);
        }
    }
    Table {
        header_aligns: vec![Align::Center, Align::Center, Align::Left],
        body_aligns: vec![Align::Center, Align::Left, Align::Left],
        header,
        rows,
    }
}

fn ser(comps: &[Compound], out: &mut String) {
    for cp in comps {
        ser_one(&cp.text, cp.kind, out);
    }
}

fn ser_one(text: &str, kind: Kind, out: &mut String) {
    let t = text.replace(EMPTY_ITALIC, "");
    match kind {
        Kind::Normal => out.push_str(&t),
        Kind::Bold => {
            out.push_str("\x1b[1m");
            out.push_str(&t);
            out.push_str("\x1b[0m");
        }
        Kind::Italic => {
            out.push_str("\x1b[3m");
            out.push_str(&t);
            out.push_str("\x1b[0m");
        }
        Kind::BoldItalic => {
            out.push_str("\x1b[1m\x1b[3m");
            out.push_str(&t);
            out.push_str("\x1b[0m");
        }
        Kind::Code => {
            out.push_str("\x1b[48;5;235m\x1b[38;5;249m");
            out.push_str(&t);
            out.push_str("\x1b[49m\x1b[39m");
        }
        Kind::Strike => {
            out.push_str("\x1b[9m");
            out.push_str(&t);
            out.push_str("\x1b[0m");
        }
    }
}

fn border(s: &str) -> String {
    format!("\x1b[38;5;239m{}\x1b[39m", s)
}

fn width_of(c: &[Compound]) -> usize {
    c.iter().map(|x| str_width(&x.text)).sum()
}

fn paragraph(md: &str, width: usize, out: &mut String) {
    let comps = crate::md::parse_inline(md);
    for line in wrap_keep_spaces(&comps, width) {
        ser(&line, out);
        out.push('\n');
    }
}

/// wrapping keeping the trailing spaces at line ends
fn wrap_keep_spaces(comps: &[Compound], width: usize) -> Vec<Vec<Compound>> {
    wrap(comps, width)
}

fn table_lines(table: &Table, width: usize, out: &mut String) {
    let natural = table.natural_widths();
    let avgs = table.avg_widths();
    let widths = crate::mdtext::fit_columns(&natural, &avgs, width);
    let hline = |l: &str, m: &str, r: &str, out: &mut String| {
        out.push_str(&border(l));
        for (i, w) in widths.iter().enumerate() {
            if i > 0 {
                out.push_str(&border(m));
            }
            out.push_str(&border(&"─".repeat(*w)));
        }
        out.push_str(&border(r));
        out.push('\n');
    };
    hline("┌", "┬", "┐", out);
    row_lines(&table.header, &widths, &table.header_aligns, out);
    hline("├", "┼", "┤", out);
    for r in &table.rows {
        row_lines(r, &widths, &table.body_aligns, out);
    }
    hline("└", "┴", "┘", out);
}

fn trim_end(mut comps: Vec<Compound>) -> Vec<Compound> {
    while let Some(last) = comps.last_mut() {
        if last.text.replace(EMPTY_ITALIC, "").is_empty() && last.text.contains(EMPTY_ITALIC) {
            break;
        }
        let t = last.text.trim_end_matches(' ').to_string();
        if t.is_empty() {
            comps.pop();
        } else {
            last.text = t;
            break;
        }
    }
    comps
}

fn row_lines(row: &[Vec<Compound>], widths: &[usize], aligns: &[Align], out: &mut String) {
    let n = widths.len();
    let mut cells: Vec<Vec<Vec<Compound>>> = Vec::new();
    for i in 0..n {
        let cell = row.get(i).cloned().unwrap_or_default();
        let w = wrap(&cell, widths[i]);
        let w: Vec<Vec<Compound>> = if w.len() > 1 { w.into_iter().map(trim_end).collect() } else { w };
        cells.push(w);
    }
    let h = cells.iter().map(|c| c.len()).max().unwrap_or(1).max(1);
    for li in 0..h {
        out.push_str(&border("│"));
        for i in 0..n {
            let comps = cells[i].get(li).cloned().unwrap_or_default();
            let cw = width_of(&comps);
            let free = widths[i].saturating_sub(cw);
            let (lp, rp) = match aligns[i] {
                Align::Left => (0, free),
                Align::Right => (free, 0),
                Align::Center => (free / 2, free - free / 2),
            };
            out.push_str(&" ".repeat(lp));
            ser(&comps, out);
            out.push_str(&" ".repeat(rp));
            out.push_str(&border("│"));
        }
        out.push('\n');
    }
}

pub fn help_text(width: usize) -> String {
    let mut out = String::new();
    // title
    let title_w = 12;
    let margin = width.saturating_sub(title_w) / 2;
    out.push_str(&" ".repeat(margin));
    out.push_str("\x1b[1m\x1b[4mbroot\x1b[0m\x1b[1m\x1b[4m \x1b[0m\x1b[1m\x1b[4m1.54.0\x1b[0m\n");
    out.push('\n');
    out.push('\n');
    paragraph("**broot** lets you explore file hierarchies with a tree-like view, manipulate and preview files, launch actions, and define your own shortcuts.", width, &mut out);
    out.push('\n');
    paragraph("**broot** is best launched as `br`: this shell function gives you access to more commands, especially `cd.` The br shell function is interactively installed on first broot launch.", width, &mut out);
    out.push('\n');
    paragraph("Flags and options can be classically passed on launch but also written in the configuration file. Each flag has a counter-flag so that you can cancel at command line a flag which has been set in the configuration file.", width, &mut out);
    out.push('\n');
    paragraph("Complete documentation and tips at https://dystroy.org/broot", width, &mut out);
    out.push('\n');
    let usage = vec![
        c("Usage: ", Kind::Bold),
        c(" ", Kind::Normal),
        c("broot", Kind::Code),
        c(" [options]", Kind::Code),
        c(" [ROOT]", Kind::Code),
    ];
    for line in wrap(&usage, width) {
        ser(&line, &mut out);
        out.push('\n');
    }
    out.push('\n');
    let bullet = vec![c("• ", Kind::Normal), c("ROOT", Kind::Code), c(" : Root Directory", Kind::Normal)];
    for line in wrap(&bullet, width) {
        let mut s = String::new();
        ser(&line, &mut s);
        if let Some(rest) = s.strip_prefix('•') {
            out.push_str("\x1b[38;5;240m•\x1b[39m");
            out.push_str(rest);
        } else {
            out.push_str(&s);
        }
        out.push('\n');
    }
    out.push('\n');
    out.push_str("\x1b[1mOptions:\x1b[0m\n");
    table_lines(&build_table(), width, &mut out);
    out.push('\n');
    out
}

pub fn print_help() {
    let has_tty = std::fs::OpenOptions::new().read(true).write(true).open("/dev/tty").is_ok();
    if has_tty {
        crate::term::luma_query_stdout();
    }
    let width = match crossterm::terminal::size() {
        Ok((w, _)) => w as usize,
        Err(_) => 50,
    };
    let width = width.min(110);
    let s = help_text(width);
    let mut o = std::io::stdout();
    let _ = o.write_all(s.as_bytes());
    let _ = o.flush();
}
