/// print markdown the way termimad does with broot's installer skin
pub fn md_print(md: &str, width: usize, out: &mut String) {
    use crate::md::Kind;
    for line in md.split('\\n') {
        let (bullet, text) = match line.strip_prefix("* ") {
            Some(t) => (true, t),
            None => (false, line),
        };
        let mut comps = crate::md::parse_inline(text);
        if bullet {
            comps.insert(0, crate::md::Compound { text: "• ".to_string(), kind: Kind::Normal });
        }
        if comps.is_empty() {
            out.push('\\n');
            continue;
        }
        for (li, l) in crate::mdtext::wrap(&comps, width).into_iter().enumerate() {
            let mut s = String::new();
            if bullet && li > 0 {
                s.push_str("  ");
            }
            for c in l {
                match c.kind {
                    Kind::Normal => s.push_str(&c.text),
                    Kind::Bold => {
                        s.push_str("\\x1b[1m");
                        s.push_str(&c.text);
                        s.push_str("\\x1b[0m");
                    }
                    Kind::Italic => {
                        s.push_str("\\x1b[38;5;13m\\x1b[3m");
                        s.push_str(&c.text);
                        s.push_str("\\x1b[0m");
                    }
                    Kind::Code => {
                        s.push_str("\\x1b[48;5;234m\\x1b[38;5;250m");
                        s.push_str(&c.text);
                        s.push_str("\\x1b[49m\\x1b[39m");
                    }
                    _ => s.push_str(&c.text),
                }
            }
            if bullet && li == 0 {
                if let Some(rest) = s.strip_prefix('•') {
                    s = format!("\\x1b[38;5;240m•\\x1b[39m{}", rest);
                }
            }
            out.push_str(&s);
            out.push('\\n');
        }
    }
}

fn script_content(s: &str) -> String {
    // the printed version has an additional newline
    let mut c = s.to_string();
    if c.ends_with("\\n\\n") {
        c.pop();
    }
    c
}

fn write_script(path: &PathBuf, content: &str, width: usize, out: &mut String) -> std::io::Result<()> {
    md_print(&format!("Writing *br* shell function in `{}`.", path.to_string_lossy()), width, out);
    if let Some(p) = path.parent() {
        std::fs::create_dir_all(p)?;
    }
    std::fs::write(path, content)
}

fn create_link(link: &PathBuf, target: &PathBuf, width: usize, out: &mut String) -> std::io::Result<()> {
    md_print(&format!("Creating link from `{}` to `{}`.", link.to_string_lossy(), target.to_string_lossy()), width, out);
    if let Some(p) = link.parent() {
        std::fs::create_dir_all(p)?;
    }
    let _ = std::fs::remove_file(link);
    std::os::unix::fs::symlink(target, link)
}

pub fn install(_forced: bool) -> i32 {
    let width = match crossterm::terminal::size() {
        Ok((w, _)) => w as usize,
        Err(_) => 50,
    };
    let mut out = String::new();
    let home = conf::home_dir();
    let data = conf::data_dir().join("launcher");
    let launcher = launcher_dir();
    // bash/zsh
    let bash_script = data.join("bash").join("1");
    let bash_link = launcher.join("bash").join("br");
    let _ = write_script(&bash_script, &script_content(BASH), width, &mut out);
    let _ = create_link(&bash_link, &bash_script, width, &mut out);
    let source_line = format!("source {}", bash_link.to_string_lossy());
    let mut patched = 0;
    let zdotdir = std::env::var_os("ZDOTDIR").map(PathBuf::from).unwrap_or_else(|| home.clone());
    let rc_files = [(home.join(".bashrc"), false), (home.join(".bash_profile"), false), (zdotdir.join(".zshrc"), true)];
    for (rc, zsh) in rc_files.iter() {
        if !rc.exists() {
            continue;
        }
        let content = std::fs::read_to_string(rc).unwrap_or_default();
        if !content.contains(&source_line) {
            let mut c = content.clone();
            c.push_str(&format!("\\n{}\\n", source_line));
            let _ = std::fs::write(rc, c);
        }
        let how = if *zsh { "`exec zsh`".to_string() } else { format!("`source ``{}`", rc.to_string_lossy()) };
        md_print(&format!("`{}` successfully patched, you can make the function immediately available with {}", rc.to_string_lossy(), how), width, &mut out);
        patched += 1;
    }
    let mut complete = true;
    if patched == 0 {
        md_print("\\nI found no sourcing file for the bash/zsh family.\\nIf you're using bash or zsh, then installation isn't complete:\\nthe br function initialization script won't be sourced unless you source it yourself.", width, &mut out);
        complete = false;
    }
    // fish
    let fish_dir = home.join(".config").join("fish");
    if fish_dir.exists() {
        let fish_script = data.join("fish").join("br.fish");
        let _ = write_script(&fish_script, &script_content(FISH), width, &mut out);
        let _ = create_link(&fish_dir.join("functions").join("br.fish"), &fish_script, width, &mut out);
    }
    // nushell
    let nu_dir = home.join(".config").join("nushell");
    if nu_dir.exists() {
        let nu_script = data.join("nushell").join("6");
        let _ = write_script(&nu_script, &script_content(NUSHELL), width, &mut out);
        let _ = create_link(&launcher.join("nushell").join("br"), &nu_script, width, &mut out);
    }
    let _ = std::fs::create_dir_all(&launcher);
    let _ = std::fs::write(launcher.join("installed-v4"), INSTALLED_CONTENT);
    if complete {
        md_print("\\nThe **br** function has been successfully installed.\\nYou may have to restart your shell or source your shell init files.\\nAfterwards, you should start broot with `br` in order to use its full power.\\n", width, &mut out);
    }
    print!("{}", out);
    0
}
