pub fn fs_info(path: &std::path::Path) -> Option<FsInfo> {
    let cpath = std::ffi::CString::new(path.to_string_lossy().as_bytes()).ok()?;
    let mut st: libc::statvfs = unsafe { std::mem::zeroed() };
    if unsafe { libc::statvfs(cpath.as_ptr(), &mut st) } != 0 {
        return None;
    }
    let frsize = st.f_frsize as u64;
    let total = st.f_blocks as u64 * frsize;
    let used = (st.f_blocks as u64 - st.f_bfree as u64) * frsize;
    // find the mount point
    let mounts = std::fs::read_to_string("/proc/mounts").unwrap_or_default();
    let p = path.to_string_lossy().to_string();
    let mut best: Option<(usize, String)> = None;
    for line in mounts.lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 3 {
            continue;
        }
        let mp = parts[1];
        let matches = p == mp || mp == "/" || p.starts_with(&format!("{}/", mp));
        if matches && best.as_ref().map(|b| mp.len() >= b.0).unwrap_or(true) {
            best = Some((mp.len(), parts[0].to_string()));
        }
    }
    let fs_type = best.map(|b| b.1).unwrap_or_default();
    Some(FsInfo { fs_type, used, total })
