        };
        PreviewState { path, lines, is_text, selection: 0, scroll: 0, page_height: 10 }
    }
    pub fn move_selection(&mut self, d: i32) {
        if self.lines.is_empty() {
            return;
        }
        let n = self.lines.len() as i32;
        let s = (self.selection as i32 + d).rem_euclid(n);
        self.selection = s as usize;
        let ph = self.page_height.saturating_sub(1).max(1);
        if self.selection < self.scroll {
            self.scroll = self.selection;
        } else if self.selection >= self.scroll + ph {
            self.scroll = self.selection + 1 - ph;
        }
    }
    pub fn page(&mut self, d: i32) {
        let ph = self.page_height.saturating_sub(1).max(1) as i32;
        let max = self.lines.len().saturating_sub(ph as usize) as i32;
        self.scroll = (self.scroll as i32 + d * ph).max(0).min(max.max(0)) as usize;
        self.selection = self.scroll;
    }
