        let name = self.path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
        // title
        let count = if self.lines.is_empty() { String::new() } else { format!("lines: {}", self.lines.len()) };
        let title_w = w.saturating_sub(crate::screen::str_width(&count));
        let mut x = screen.write_str(x0, y0, &name, skin.preview_title, x0 + title_w);
        x = screen.fill(x, y0, x0 + title_w, skin.preview_title);
