            screen.fill(x, y, text_end, fill);
            if let Some((t, b)) = sb {
                let st = if y >= t && y <= b { skin.scrollbar_thumb } else { skin.scrollbar_track };
                let st = Style { fg: st.fg, bg, attrs: Default::default() };
                screen.set(x0 + w - 1, y, '▐', st);
            }
        }
    }
}

fn hex_lines(path: &std::path::Path) -> Vec<String> {
    let bytes = std::fs::read(path).unwrap_or_default();
    let mut out = Vec::new();
    for chunk in bytes.chunks(16).take(10000) {
        let hex: Vec<String> = chunk.iter().map(|b| format!("{:02x}", b)).collect();
        let ascii: String = chunk.iter().map(|&b| if (0x20..0x7f).contains(&b) { b as char } else { '.' }).collect();
        out.push(format!("{:<48} {}", hex.join(" "), ascii));
    }
    out
}
