//! git information, using the git command

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::process::Command;

pub struct GitInfo {
    pub root: PathBuf,
    pub statuses: HashMap<PathBuf, char>,
    pub branch: Option<String>,
    pub insertions: usize,
    pub deletions: usize,
}

fn git(dir: &Path, args: &[&str]) -> Option<String> {
    let out = Command::new("git").arg("-C").arg(dir).args(args).stderr(std::process::Stdio::null()).output().ok()?;
    if !out.status.success() {
        return None;
    }
    Some(String::from_utf8_lossy(&out.stdout).to_string())
}

pub fn git_info(path: &Path) -> Option<GitInfo> {
    let root = crate::gitignore::find_git_root(path)?;
    let mut statuses = HashMap::new();
    if let Some(s) = git(&root, &["status", "--porcelain=v1", "-z", "--untracked-files=all"]) {
        let mut parts = s.split('\0');
        while let Some(entry) = parts.next() {
            if entry.len() < 4 {
                continue;
            }
            let x = entry.as_bytes()[0] as char;
            let y = entry.as_bytes()[1] as char;
            let file = &entry[3..];
            let c = match (x, y) {
                ('?', '?') => 'N',
                ('A', _) => 'N',
                ('U', _) | (_, 'U') => 'C',
                ('R', _) => {
                    parts.next();
                    'R'
                }
                ('!', '!') => 'I',
                (_, 'D') | ('D', _) => 'D',
                _ => 'M',
            };
            statuses.insert(root.join(file), c);
        }
    }
    let branch = git(&root, &["rev-parse", "--abbrev-ref", "HEAD"]).map(|b| b.trim().to_string());
    let mut insertions = 0;
    let mut deletions = 0;
    if let Some(s) = git(&root, &["diff", "--numstat", "HEAD"]) {
        for l in s.lines() {
            let p: Vec<&str> = l.split('\t').collect();
            if p.len() >= 2 {
                insertions += p[0].parse::<usize>().unwrap_or(0);
                deletions += p[1].parse::<usize>().unwrap_or(0);
            }
        }
    }
    Some(GitInfo { root, statuses, branch, insertions, deletions })
}

impl GitInfo {
    pub fn status_of(&self, p: &Path) -> Option<char> {
        self.statuses.get(p).copied()
    }
    /// whether a dir contains a file with an interesting status
    pub fn dir_has_status(&self, p: &Path) -> bool {
        self.statuses.keys().any(|k| k.starts_with(p) && k != p)
    }
}
