        let (vname, arg) = vpart.split_at(vpart.find(' ').unwrap());
        let arg = arg.trim_start();
        let root = self.current_root();
        let (dir_part, file_part) = match arg.rfind('/') {
            Some(i) => (&arg[..=i], &arg[i + 1..]),
            None => ("", arg),
        };
        let dir = if dir_part.starts_with('/') { PathBuf::from(dir_part) } else { root.join(dir_part) };
        let mut cands: Vec<String> = Vec::new();
        if let Ok(rd) = std::fs::read_dir(&dir) {
            for e in rd.flatten() {
                let n = e.file_name().to_string_lossy().to_string();
                if n.starts_with(file_part) && (!n.starts_with('.') || file_part.starts_with('.')) {
                    cands.push(n);
                }
            }
        }
        cands.sort();
        if cands.len() == 1 {
            let new = format!("{}{} {}{}", base, vname, dir_part, cands[0]);
            self.panel_mut().input.set(&new);
            self.on_input_changed();
        } else if cands.len() > 1 {
            let mut prefix = cands[0].clone();
            for n in &cands[1..] {
                while !n.starts_with(&prefix) {
                    prefix.pop();
                }
            }
            if prefix.len() > file_part.len() {
                let new = format!("{}{} {}{}", base, vname, dir_part, prefix);
                self.panel_mut().input.set(&new);
                self.on_input_changed();
            }
        }
        true
    }

    fn handle_input_key(&mut self, key: &KeyEvent) -> bool {""")
